const JARGON=[{"name":"Nucleus","aliases":["nucleus","nuclei"],"def":"The tiny central part of an atom that contains protons and neutrons and almost all of the atom’s mass."},{"name":"Proton","aliases":["proton","protons"],"def":"A positively charged particle in the nucleus. The number of protons determines which chemical element an atom is."},{"name":"Neutron","aliases":["neutron","neutrons"],"def":"An electrically neutral particle in the nucleus. Neutrons affect nuclear mass, stability, and the ability of some nuclei to sustain fission."},{"name":"Nucleon","aliases":["nucleon","nucleons"],"def":"A collective name for either a proton or a neutron."},{"name":"Nuclide","aliases":["nuclide","nuclides"],"def":"A particular kind of nucleus specified by its numbers of protons and neutrons."},{"name":"Isotope","aliases":["isotope","isotopes","isotopic"],"def":"Atoms of the same element with the same number of protons but different numbers of neutrons."},{"name":"Atomic number, Z","aliases":["atomic number","number z"," z "],"def":"The number of protons in a nucleus. It identifies the chemical element."},{"name":"Mass number, A","aliases":["mass number"," a - z","a-z"],"def":"The total number of protons plus neutrons in a nucleus."},{"name":"Atomic mass unit, u","aliases":["atomic mass unit"," mass units"," mev/u"," u/nucleon"],"def":"A mass unit used for atoms and nuclei. One atomic mass unit is close to the mass of one proton or neutron."},{"name":"Mass defect","aliases":["mass defect"],"def":"The difference between the summed masses of separate protons and neutrons and the smaller mass of the bound nucleus."},{"name":"Binding energy","aliases":["binding energy","binding-energy"],"def":"The energy required to separate a nucleus into its individual protons and neutrons; equivalently, the energy released when the nucleus is formed."},{"name":"Binding energy per nucleon","aliases":["binding energy per nucleon","binding-energy-per-nucleon"],"def":"The average binding energy for each proton or neutron. It is a useful broad indicator of how tightly a nucleus is bound."},{"name":"Rest-mass energy","aliases":["rest-mass energy","rest mass energy","e=mc","mc²","mc^2"],"def":"The energy associated with mass itself, expressed by E = mc²."},{"name":"MeV","aliases":["mev"],"def":"Mega-electron-volt, a unit of energy equal to one million electron-volts and commonly used for nuclear processes."},{"name":"Fission","aliases":["fission","fissioning"],"def":"The splitting of a heavy nucleus into smaller nuclei, usually accompanied by neutrons and a release of energy."},{"name":"Fusion","aliases":["fusion"],"def":"The joining of light nuclei into a heavier nucleus, which can release energy when the final nucleus is more tightly bound."},{"name":"Radioactive decay","aliases":["radioactive decay","decay law","decays"],"def":"A spontaneous nuclear transformation. Individual decay times are random, but a large population follows a predictable statistical law."},{"name":"Decay constant, λ","aliases":["decay constant","lambda","λ"],"def":"The probability per unit time that a radioactive nucleus will decay."},{"name":"Half-life","aliases":["half-life","half life","half-lives"],"def":"The time required for half of a large radioactive population to decay."},{"name":"Activity","aliases":["activity a=","radioactive activity","activity"],"def":"The number of nuclear decays occurring per unit time in a sample."},{"name":"Count rate","aliases":["count rate","counts/s","counts per second","counting rate"],"def":"The number of events recorded by a detector per unit time. It can differ from the true activity because detection is imperfect and backgrounds are present."},{"name":"Detector efficiency","aliases":["detector efficiency","intrinsic efficiency","absolute efficiency","efficiency correction","efficiency"],"def":"The fraction of relevant particles or decays that a detector actually records."},{"name":"Geometric acceptance","aliases":["geometric acceptance","solid angle"],"def":"The fraction of particles that travel toward and enter a detector because of its size and position."},{"name":"Background","aliases":["background subtraction","background rate","background counts","background"],"def":"Detector events not produced by the source or process of interest. They must be measured or estimated separately."},{"name":"Cross section","aliases":["microscopic cross section","cross section","cross-section"],"def":"A measure of the likelihood that a particle will undergo a particular interaction with a target nucleus. It has units of area."},{"name":"Barn","aliases":["barn scale","barns","barn"],"def":"A nuclear cross-section unit equal to 10⁻²⁴ square centimeters."},{"name":"Macroscopic cross section, Σ","aliases":["macroscopic cross section","sigma=n","sigma = n","Σ"],"def":"The interaction probability per unit path length in a bulk material, found by multiplying microscopic cross section by target number density."},{"name":"Number density","aliases":["number density","atoms per cubic","cm⁻³","cm^-3"],"def":"The number of target atoms or nuclei in a unit volume."},{"name":"Mean free path","aliases":["mean free path"],"def":"The average distance a particle travels in a material before the specified interaction occurs."},{"name":"Exponential attenuation","aliases":["exponential attenuation","attenuation"],"def":"The gradual reduction of an uncollided particle beam as particles interact while moving through matter."},{"name":"Absorption","aliases":["absorption","absorbing","absorbed"],"def":"An interaction in which the incoming particle is captured or otherwise removed from the outgoing particle population."},{"name":"Scattering","aliases":["elastic scattering","scattering","scatter"],"def":"An interaction that changes a particle’s direction and often its energy without necessarily removing the particle."},{"name":"Moderator","aliases":["moderator","moderation","moderates"],"def":"A material used to slow neutrons through repeated scattering while ideally absorbing relatively few of them."},{"name":"Heavy water","aliases":["heavy water","deuterium oxide"],"def":"Water whose hydrogen is mostly deuterium. It can slow neutrons while absorbing fewer of them than ordinary water."},{"name":"Fast neutron","aliases":["fast neutron","fast-neutron"],"def":"A neutron with relatively high kinetic energy, typically soon after being produced by fission or another nuclear reaction."},{"name":"Thermal neutron","aliases":["thermal neutron","thermal-neutron"],"def":"A neutron slowed until its typical energy is comparable to the thermal motion of surrounding matter."},{"name":"Random walk","aliases":["random walk","random-walk"],"def":"Motion made of many steps in changing directions. The net displacement grows roughly with the square root of the number of steps."},{"name":"Diffusion","aliases":["diffusion length","diffusion"],"def":"The statistical spreading of particles through many random scattering events."},{"name":"Leakage","aliases":["neutron leakage","leakage"],"def":"Neutrons escaping from the boundary of a system instead of causing further interactions inside it."},{"name":"Multiplication factor, k","aliases":["multiplication factor","k="," k "],"def":"The ratio of neutrons in one chain-reaction generation to the preceding generation."},{"name":"Subcritical","aliases":["subcritical","below critical"],"def":"A state with multiplication factor below one, so the neutron population decreases from generation to generation."},{"name":"Critical","aliases":["criticality","exactly critical","critical state"],"def":"A state with multiplication factor equal to one, so the average neutron population remains steady."},{"name":"Supercritical","aliases":["supercritical","above critical"],"def":"A state with multiplication factor above one, so the neutron population grows from generation to generation."},{"name":"Chain reaction","aliases":["chain reaction","chain-reaction"],"def":"A process in which neutrons from one fission can cause additional fissions, producing successive generations."},{"name":"Prompt neutron","aliases":["prompt neutron","prompt-neutron"],"def":"A neutron emitted essentially immediately during fission."},{"name":"Delayed neutron","aliases":["delayed neutron","delayed-neutron"],"def":"A neutron emitted later by certain radioactive fission products. Delayed neutrons are important for controllable reactor behavior."},{"name":"Generation time","aliases":["generation time","neutron generation"],"def":"The characteristic time between one neutron generation and the next in a multiplying system."},{"name":"Neutron economy","aliases":["neutron economy"],"def":"An accounting of where neutrons are produced, absorbed usefully, absorbed parasitically, or lost by leakage."},{"name":"Spontaneous fission","aliases":["spontaneous fission","spontaneous-fission"],"def":"Fission that occurs without an incoming neutron or other external trigger."},{"name":"Preinitiation","aliases":["preinitiation","pre-initiation"],"def":"The start of a neutron chain earlier than intended because a neutron appears before the desired physical state is reached."},{"name":"Fissile material","aliases":["fissile material","fissile isotope","fissile"],"def":"A material whose nuclei can sustain a neutron-driven fission chain under suitable conditions."},{"name":"Poisson statistics","aliases":["poisson","counting statistics","statistical counting"],"def":"The probability model commonly used for independent counted events. Its standard fluctuation is approximately the square root of the number of counts."},{"name":"Standard deviation, σ","aliases":["standard deviation","1σ","sigma_net","σ"],"def":"A measure of the typical spread or uncertainty of repeated measurements."},{"name":"Uncertainty in quadrature","aliases":["quadrature","combine uncertainties"],"def":"Combining independent uncertainties by taking the square root of the sum of their squares."},{"name":"Random error","aliases":["random error","random uncertainty"],"def":"Measurement variation that changes unpredictably from one observation to another and can often be reduced by collecting more data."},{"name":"Systematic error","aliases":["systematic error","systematic uncertainty"],"def":"A consistent bias or calibration problem that does not necessarily shrink when more data are collected."},{"name":"Scintillation detector","aliases":["scintillation","scintillator"],"def":"A detector in which radiation produces flashes of light that are converted into electrical signals."},{"name":"Photoelectron","aliases":["photoelectron","photoelectrons"],"def":"An electron released when light transfers energy to a photosensitive surface; photoelectrons form the counted signal in many light-based detectors."},{"name":"Ionization chamber","aliases":["ionization chamber"],"def":"A detector that measures electric charge created when radiation ionizes gas."},{"name":"Proportional counter","aliases":["proportional counter"],"def":"A gas detector whose pulse size is approximately proportional to the energy deposited by the incoming radiation."},{"name":"Geiger–Müller counter","aliases":["geiger","geiger–müller","geiger-müller"],"def":"A gas detector that produces a large standard pulse for each event; it counts events well but generally does not measure their energy."},{"name":"Dead time","aliases":["dead time","dead-time"],"def":"The short recovery period after an event during which a detector or electronics cannot record another event correctly."},{"name":"Saturation","aliases":["saturation","saturated","clips","clipping"],"def":"A condition in which increasing the true signal no longer produces a larger recorded response because the instrument has reached its limit."},{"name":"Gain drift","aliases":["gain drift","drift"],"def":"A gradual change in the conversion between a physical signal and the instrument’s recorded output."},{"name":"Pulse height","aliases":["pulse height","pulse-height"],"def":"The amplitude of a detector’s electrical pulse, often related to the energy deposited in the detector."},{"name":"Energy resolution","aliases":["energy resolution","spectral resolution","resolution broadening"],"def":"A detector’s ability to distinguish nearby particle or photon energies."},{"name":"Calibration","aliases":["calibration","calibrate","calibrated"],"def":"Determining how an instrument’s output corresponds to known physical inputs."},{"name":"Coincidence","aliases":["coincidence window","coincidence counts","coincidence"],"def":"The requirement that signals in two or more detectors occur within a defined short time interval, helping identify correlated events."},{"name":"Timing gate","aliases":["timing gate","gate duration","timing window","trigger window"],"def":"A selected time interval during which detector events are accepted for analysis."},{"name":"Time of flight","aliases":["time-of-flight","time of flight"],"def":"A measurement that infers speed or energy from the time a particle takes to travel a known distance."},{"name":"Trigger","aliases":["trigger","triggering"],"def":"The electronic condition that tells a measurement system when to begin recording an event."},{"name":"Bandwidth","aliases":["bandwidth"],"def":"The range of signal frequencies an instrument can reproduce accurately; insufficient bandwidth can distort fast signals."},{"name":"Dynamic range","aliases":["dynamic range"],"def":"The span from the smallest to the largest signal an instrument can measure without losing sensitivity or saturating."},{"name":"Signal-to-noise ratio","aliases":["signal-to-noise","signal to noise","snr"],"def":"The size of the desired signal compared with fluctuations and unwanted background."},{"name":"Radiography","aliases":["radiography","radiograph","x-ray image","flash x-ray"],"def":"Imaging the interior of an object using penetrating radiation; fast radiography can capture rapidly changing density patterns."},{"name":"Tracer","aliases":["radioactive tracer","tracer"],"def":"A detectable isotope used to follow material through a chemical, biological, or industrial process."},{"name":"Chemical yield","aliases":["chemical yield","recovery fraction","recovered fraction","separation yield"],"def":"The fraction of the desired material recovered after a chemical process."},{"name":"Carrier","aliases":["carrier material","carrier"],"def":"A larger amount of chemically similar material added so a tiny radioactive quantity can be handled or recovered more reliably."},{"name":"Precipitation","aliases":["precipitation","precipitate"],"def":"A chemical process in which dissolved material forms a solid that can be separated from the liquid."},{"name":"Oxidation state","aliases":["oxidation state","valence state"],"def":"A bookkeeping description of how many electrons an atom has effectively lost or gained in a compound; it strongly affects chemical behavior."},{"name":"Assay","aliases":["assay","assayed"],"def":"A quantitative measurement of a material’s composition, purity, or amount of a specified isotope."},{"name":"Contamination","aliases":["contamination","contaminated"],"def":"Unwanted radioactive or chemical material present in a sample, instrument, or workspace."},{"name":"Stoichiometry","aliases":["stoichiometry","stoichiometric"],"def":"The numerical ratios in which chemical elements or compounds react."},{"name":"Phase","aliases":["phase diagram","phase transition","phase change","allotrope","phase"],"def":"A physically distinct form of a material, such as a particular crystal structure, liquid, or gas."},{"name":"Grain boundary","aliases":["grain boundary","grain boundaries"],"def":"The interface between differently oriented crystals in a solid; it can affect strength, corrosion, and diffusion."},{"name":"Porosity","aliases":["porosity","voids"],"def":"The fraction of a material occupied by small empty spaces or pores."},{"name":"Thermal expansion","aliases":["thermal expansion"],"def":"The change in a material’s dimensions as its temperature changes."},{"name":"Tolerance","aliases":["tolerance stack","tolerances","tolerance"],"def":"The permitted variation in a dimension, timing, or property while a part or process remains acceptable."},{"name":"Acceptance criterion","aliases":["acceptance criteria","acceptance criterion","pass/fail criteria"],"def":"A measurable rule decided before a test that determines whether the result is acceptable."},{"name":"Chain of custody","aliases":["chain of custody"],"def":"A documented record of who handled a sample or component and when, preserving identity and traceability."},{"name":"Configuration control","aliases":["configuration control","configuration freeze","freeze the configuration"],"def":"The formal process for documenting and approving exactly which version of every part and procedure is being used."},{"name":"Interface","aliases":["interface requirement","system interfaces","interface"],"def":"The physical, electrical, timing, or information boundary where two subsystems must work together."},{"name":"Prototype","aliases":["prototype"],"def":"An early version built to expose design, fit, timing, or manufacturing problems before final production."},{"name":"Qualification test","aliases":["qualification","qualify","qualified"],"def":"A test showing that a component or process meets defined requirements under representative conditions."},{"name":"Firing chain","aliases":["firing chain","firing system"],"def":"The ordered set of commands, safety conditions, timing elements, and outputs that leads from authorization to initiation."},{"name":"Detonator","aliases":["detonator","detonators"],"def":"A device that initiates a high-explosive detonation at a controlled time."},{"name":"Simultaneity","aliases":["simultaneity","simultaneous initiation","synchronization"],"def":"The requirement that multiple events occur within a very small allowed timing difference."},{"name":"Explosive lens","aliases":["explosive lens","explosive lenses","lens system"],"def":"A shaped combination of explosive materials used to transform an outward detonation into a controlled converging shock pattern."},{"name":"Detonation wave","aliases":["detonation wave","detonation"],"def":"A rapidly moving reaction front in high explosive, coupled to a strong shock wave."},{"name":"Shock wave","aliases":["shock wave","shock-like","shock front"],"def":"A very abrupt pressure disturbance that moves faster than ordinary sound and strongly compresses material."},{"name":"Hydrodynamic test","aliases":["hydrodynamic test","hydrodynamic testing","hydrodynamics"],"def":"A test that studies materials moving under extreme pressure as if they were fluids, often using non-nuclear substitutes and fast diagnostics."},{"name":"Compression","aliases":["compression","compress"],"def":"A reduction in volume that raises material density."},{"name":"Symmetry","aliases":["symmetry","symmetric","asymmetry","asymmetric"],"def":"How uniformly a physical process occurs around a center or axis. In converging systems, small asymmetries can grow and spoil the intended state."},{"name":"Converging wave","aliases":["converging wave","converging shock","convergence"],"def":"A wave moving inward toward a central region, where its geometry can amplify pressure and sensitivity to imperfections."},{"name":"RaLa experiment","aliases":["rala","ra-la"],"def":"The Los Alamos radiolanthanum method that used gamma radiation to infer changing density during implosion experiments."},{"name":"Surrogate material","aliases":["surrogate","non-nuclear substitute","inert substitute"],"def":"A safer or more available material used to reproduce selected physical behavior without using the final hazardous material."},{"name":"Discriminating test","aliases":["discriminating test","discriminating evidence","separate competing"],"def":"A test designed so competing explanations predict measurably different outcomes."},{"name":"Observable","aliases":["observable","observables"],"def":"A quantity that can actually be measured and compared with a prediction."},{"name":"Sensitivity analysis","aliases":["sensitivity analysis","sensitivity"],"def":"Studying how strongly a prediction changes when an input or assumption is varied."},{"name":"Prediction band","aliases":["prediction band","uncertainty band","prediction range"],"def":"A range of outcomes considered plausible after accounting for uncertain inputs and model limitations."},{"name":"Independent diagnostic","aliases":["independent diagnostic","independent diagnostics","independent measurement"],"def":"A second measurement method with different failure modes, used to check whether a conclusion depends on one instrument."},{"name":"Redundancy","aliases":["redundancy","redundant"],"def":"Using more than one component or measurement path so one failure does not erase the needed evidence or function."},{"name":"Single-point failure","aliases":["single-point failure","single point failure"],"def":"One component or event whose failure would cause the entire system or evidence chain to fail."},{"name":"Decision gate","aliases":["decision gate","hold point","final hold"],"def":"A formally defined point where evidence is reviewed and authority is required before work proceeds."},{"name":"Readiness review","aliases":["readiness review","review board"],"def":"A structured assessment of evidence, unresolved risks, interfaces, and contingency plans before proceeding."},{"name":"Arming","aliases":["arming"],"def":"Changing a system from a safe condition toward a state in which it can function as intended, under controlled authorization."},{"name":"Fuzing","aliases":["fuzing","fuze"],"def":"The sensing and logic used to determine when a weapon or test article should initiate its firing sequence."},{"name":"Safety interlock","aliases":["safety interlock","interlock"],"def":"A device or rule that prevents an action unless specified safety conditions are satisfied."},{"name":"Silverplate","aliases":["silverplate"],"def":"The modification program for B-29 aircraft intended to carry early atomic weapons."},{"name":"Thin Man","aliases":["thin man"],"def":"An early elongated plutonium gun-type weapon concept abandoned when spontaneous-neutron measurements made premature initiation too likely."},{"name":"Fat Man","aliases":["fat man"],"def":"The implosion-type plutonium weapon developed at Los Alamos and used against Nagasaki."},{"name":"Trinity","aliases":["trinity"],"def":"The July 1945 test in New Mexico of the plutonium implosion design."},{"name":"Gadget","aliases":["the gadget","gadget"],"def":"The name commonly used for the implosion test device assembled for Trinity."},{"name":"Project Alberta","aliases":["project alberta"],"def":"The Manhattan Project unit responsible for final weapon assembly, overseas deployment, and aircraft integration."},{"name":"Prompt radiation","aliases":["prompt ionizing radiation","prompt radiation"],"def":"Neutrons and gamma rays emitted during and immediately after a nuclear event."},{"name":"Residual radiation","aliases":["residual radiation","residual radioactivity"],"def":"Radiation emitted later by radioactive products and activated materials."},{"name":"Fallout","aliases":["fallout"],"def":"Radioactive particles transported through the atmosphere and deposited after a nuclear explosion."},{"name":"Activation","aliases":["activated material","activation"],"def":"The creation of radioactive nuclei when stable material captures neutrons or undergoes another nuclear reaction."},{"name":"Ionizing radiation","aliases":["ionizing radiation"],"def":"Radiation energetic enough to remove electrons from atoms or molecules, potentially damaging living tissue."},{"name":"Mass balance","aliases":["mass balance","material balance"],"def":"An accounting rule stating that material entering a process must equal material leaving, accumulating, or being lost through identified pathways."},{"name":"Ion exchange","aliases":["ion exchange","ion-exchange"],"def":"A separation method in which charged atoms or molecules attach selectively to a solid resin and are later released under different chemical conditions."},{"name":"Corrosion","aliases":["corrosion","corrode","corrosive"],"def":"The chemical or electrochemical degradation of a material through reaction with its environment."},{"name":"Material compatibility","aliases":["material compatibility","compatibility"],"def":"Whether two materials can remain in contact without unacceptable corrosion, reaction, contamination, swelling, or loss of strength."},{"name":"Mechanical properties","aliases":["mechanical properties","tensile strength","ductility","hardness"],"def":"Measurements describing how a material responds to force, including strength, stiffness, hardness, and ability to deform without cracking."},{"name":"Process safety","aliases":["process safety","chemical process safety"],"def":"The systematic control of chemical, thermal, pressure, contamination, and equipment hazards during an operation."},{"name":"Waste control","aliases":["waste control","waste and environmental","environmental control"],"def":"Tracking, containing, treating, and monitoring unwanted radioactive or chemical material so it does not spread to workers or the environment."},{"name":"Drop time","aliases":["drop time","fall time"],"def":"The elapsed time between release and impact or another defined point during a drop test."},{"name":"Pumpkin bomb","aliases":["pumpkin bomb","pumpkin-bomb"],"def":"An inert or conventionally filled test shape used to practice aircraft handling and bombing behavior similar to the Fat Man external form."},{"name":"Inspection","aliases":["inspection","inspect"],"def":"A planned examination or measurement used to determine whether a part, material, or process meets documented requirements."},{"name":"Lot traceability","aliases":["lot traceability","lot record","batch traceability"],"def":"The ability to connect each finished item to its production batch, materials, process history, inspections, and test records."}];

function allChallengeText(lesson,ch,includeAnswer=false){
 const parts=[lesson.title,lesson.progress,lesson.takeaway,ch.title,ch.setup,ch.play,ch.task,ch.question];
 ['cards','scenarios','choices','givens'].forEach(k=>{if(Array.isArray(ch[k]))parts.push(...ch[k])});
 if(Array.isArray(ch.proposals))ch.proposals.forEach(p=>parts.push(p.text));
 if(ch.type==='Ballpark'){
  const spec=BALLPARK_CALCS[`${activeChallenge?activeChallenge.id:''}-${lesson.day}`];
  if(spec)parts.push(spec.prompt,spec.question,...spec.labels,includeAnswer?spec.solution:'',includeAnswer?spec.explanation:'');
 }
 if(includeAnswer)parts.push(ch.answer,ch.why);
 return parts.filter(Boolean).join(' ').toLowerCase();
}
function jargonMatches(text,max=12){
 const normalized=` ${String(text||'').toLowerCase()} `;
 const found=[];
 for(const item of JARGON){
  if(item.aliases.some(a=>normalized.includes(String(a).toLowerCase()))){found.push(item);if(found.length>=max)break}
 }
 return found;
}
function jargonHTML(text,title='Click a term for a definition'){
 const terms=jargonMatches(text,12);
 if(!terms.length)return '';
 return `<div class="termStrip"><div class="termStripLabel">${esc(title)}</div><div class="termButtons">${terms.map(t=>`<button type="button" class="termChip" data-term="${JARGON.indexOf(t)}">${esc(t.name)}</button>`).join('')}</div><div class="termDefinition hidden"></div></div>`;
}
const CURRICULUM={"T":[{"day":1,"title":"The nucleus as a physical system","progress":"Define protons, neutrons, nuclides, isotopes, atomic number, mass number, and the distinction between nuclear and electronic energy scales.","takeaway":"Nuclear reasoning starts by translating notation into particles and conserved quantities.","game":{"type":"Protocol","columns":["What you want to know","How you get it"],"title":"Read a nuclide card","setup":"A theorist receives four unfamiliar nuclide labels and must extract the right quantity before doing any calculation.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Need the number of protons -> Read atomic number Z; Need the number of neutrons -> Compute A - Z; Need to decide whether two atoms are isotopes -> Compare Z while A differs; Need the net charge of a neutral atom -> Set electron count equal to Z","why":"Notation is only useful when each symbol is tied to a physical count. The atomic number Z is the proton count, and it fixes which element this is. The mass number A counts protons and neutrons together, so the neutron count is A minus Z — a subtraction, not a symbol on the label. Two atoms are isotopes of one element when Z is the same and A differs. And a neutral atom has as many electrons as protons, which is why Z decides the chemistry as well as the identity.","scenarios":["Need the number of protons","Need the number of neutrons","Need to decide whether two atoms are isotopes","Need the net charge of a neutral atom"],"choices":["Read atomic number Z.","Compute A - Z.","Compare Z while A differs.","Set electron count equal to Z."],"mapping":[0,1,2,3],"rebuttals":["The proton count is read straight off the atomic number Z. It is the one quantity the notation gives you directly.","The neutron count is A minus Z. Nothing on the label states it, which is why this is the step people skip.","Isotopes share Z and differ in A. Same element, different nucleus — and that difference is the reason this site exists.","A neutral atom balances its protons with electrons, so the electron count equals Z. That is what ties chemistry to the nucleus."]},"story":"Your first morning on the Hill. The Theoretical Division hands you four nuclide labels with no explanation and expects you to pull the right quantity out of each one before anybody calculates anything.","assumes":["an atom has a nucleus of protons and neutrons, with electrons around it"]},{"day":2,"title":"Mass defect and binding energy","progress":"Introduce rest-mass energy, mass defect, total binding energy, and binding energy per nucleon as a measure of nuclear stability.","takeaway":"Tiny changes in mass correspond to large nuclear energies.","game":{"type":"Ballpark","title":"Turn mass defect into energy","setup":"A medium-heavy nucleus has about 200 nucleons and a mass defect of about 0.008 atomic mass units per nucleon.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 1.5 x 10^3 MeV.","why":"A bound nucleus weighs less than the loose protons and neutrons that went into it. That missing mass is the binding energy holding it together. The conversion factor is the speed of light squared. So a mass difference far too small to weigh becomes an energy larger than any chemical reaction can produce. Work in atomic mass units and one unit is about 931 MeV. That is what turns a defect of eight thousandths of a unit per nucleon into more than a thousand MeV for the whole nucleus.","givens":["Mass defect is about 0.008 u per nucleon","A nucleus of this size has about 200 nucleons","1 atomic mass unit corresponds to about 931 MeV"],"task":"Estimate the total binding energy in MeV.","relationship":"Binding energy = mass defect per nucleon × number of nucleons × the energy equivalent of one mass unit."},"story":"A theorist at the blackboard wants a number before lunch: how tightly a medium-heavy nucleus is bound. This arithmetic is the reason the laboratory exists at all.","assumes":["mass and energy are related by E = mc²"]},{"day":3,"title":"The binding-energy curve","progress":"Explain why very light nuclei can release energy by fusion and very heavy nuclei can release energy by fission, without treating the curve as an operational design recipe.","takeaway":"Energy release is a difference between states, not a property of one isolated point.","game":{"type":"Sequence","title":"Read the binding-energy curve","setup":"Place the reasoning steps that connect the curve to energy release.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Locate the initial nuclei on the binding-energy-per-nucleon curve -> Identify products closer to the broad maximum -> Recognize that the products are more tightly bound -> Convert the binding-energy difference into released energy)","why":"The curve predicts energy release only after initial and final states are compared.","cards":["Locate the initial nuclei on the binding-energy-per-nucleon curve","Identify products closer to the broad maximum","Recognize that the products are more tightly bound","Convert the binding-energy difference into released energy"],"order":[0,1,2,3]},"story":"Nuclei near the middle of the periodic table are bound more tightly per particle than very heavy nuclei. When a heavy nucleus splits into medium-mass fragments, the products sit lower in energy and the difference is released. This binding-energy curve gives Los Alamos scientists the broad physical reason fission can power a bomb, while reminding them that energy comes from comparing the starting and ending nuclei."},{"day":4,"title":"Radioactive decay law","progress":"Derive N(t)=N0 exp(-lambda t), connect lambda to half-life, and distinguish decay probability from the exact lifetime of one nucleus.","takeaway":"Half-life is a population statement produced by random individual decays.","game":{"type":"Ballpark","title":"Three half-lives","setup":"A tracer with a 2-hour half-life starts at 10,000 nuclei and is left for a 6-hour shift.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 1,250 nuclei.","why":"Decay is random for any single nucleus and predictable for a large population. After one half-life about half the original nuclei remain. After two, a quarter. After three, an eighth. That holds regardless of how many you started with, which is what makes decay usable as a clock and as a correction. A six-hour shift against a two-hour half-life is three halvings. So the shift length is part of the measurement, not a detail about when it was taken.","givens":["Each half-life leaves one-half of the previous amount","A 6-hour wait is three 2-hour half-lives"],"task":"Estimate the number remaining.","relationship":"After n half-lives, what is left = the starting number × (½)ⁿ."},"story":"A tracer sample has been sitting through a six-hour shift and somebody needs to know what is left in it. Every count taken here is a count of something that has been decaying since it was made.","assumes":["a half-life is the time for half of a large population to decay"]},{"day":5,"title":"Activity and count rate","progress":"Connect activity A=lambda N to measured count rate, efficiency, geometry, and background.","takeaway":"A detector does not observe every decay, and it also observes events that are not from the source.","game":{"type":"Protocol","columns":["What you want to work out","How you work it out"],"title":"From activity to observed counts","setup":"A calculation group must choose the missing factor for four count-rate questions.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Convert number of nuclei to decays per second -> Multiply by decay constant; Convert decays per second to detected events -> Multiply by detector efficiency; Correct a measured gross rate -> Subtract background rate; Compare two sources measured at different efficiencies -> Divide by efficiency before comparison","why":"Activity belongs to the source; count rate belongs to the source-detector arrangement.","scenarios":["Convert number of nuclei to decays per second","Convert decays per second to detected events","Correct a measured gross rate","Compare two sources measured at different efficiencies"],"choices":["Multiply by decay constant.","Multiply by detector efficiency.","Subtract background rate.","Divide by efficiency before comparison."],"mapping":[0,1,2,3]},"story":"Activity is the number of nuclear decays occurring each second, but a detector records only some of them and also records background events from the room and electronics. The bomb program depends on turning detector counts into trustworthy estimates of what a source is actually doing. That requires separating source behavior from efficiency, geometry, and background instead of treating the displayed count rate as the whole truth."},{"day":6,"title":"Reaction cross sections","progress":"Define microscopic cross section as an interaction probability scale and macroscopic cross section Sigma=n sigma as the rate per path length.","takeaway":"Cross section becomes experimentally useful when combined with the number of targets per volume.","game":{"type":"Ballpark","title":"From atoms to macroscopic attenuation","setup":"A solid has number density n = 10^22 cm^-3, and the cross section is 1 barn = 10^-24 cm^2.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"Sigma is about 0.01 cm^-1; the mean free path is about 100 cm.","why":"A cross section is not the physical size of a nucleus. It is how likely an interaction is, given as an area so it can be multiplied by how many targets a beam actually passes through. Probability per nucleus times nuclei per volume gives the macroscopic cross section, an inverse length — how much interaction there is per centimetre travelled. Invert that and you have the mean free path, the average distance before the interaction happens. Multiply the powers of ten first; the arithmetic is easier than the units.","givens":["Sigma = n sigma","Mean free path = 1/Sigma"],"task":"Estimate the macroscopic cross section and the mean free path.","relationship":"Mean free path = 1 ÷ (number density × cross section)."},"story":"The Theoretical Division needs a reaction rate and has a cross section written in barns. Nearly every number this laboratory argues about is built out of the multiplication that follows.","assumes":["a cross section is expressed as an area"]},{"day":7,"title":"Exponential attenuation and mean free path","progress":"Use I=I0 exp(-Sigma x), interpret one mean free path, and distinguish removal from absorption.","takeaway":"Exponential attenuation is a probability model, not a guarantee that every particle travels exactly one mean free path.","game":{"type":"Sequence","title":"Follow a particle through matter","setup":"Order the conceptual chain behind exponential attenuation.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (A particle enters a uniform material -> Each short path interval carries a small interaction probability -> Survival probabilities multiply along the path -> The surviving intensity becomes exponential in thickness)","why":"An exponential appears because the same fractional survival process repeats over many small intervals.","cards":["A particle enters a uniform material","Each short path interval carries a small interaction probability","Survival probabilities multiply along the path","Transmitted intensity falls exponentially with thickness"],"order":[0,1,2,3]},"story":"A neutron moving through matter has some chance of interacting in every small distance it travels, so the surviving population falls exponentially rather than linearly. The mean free path is the average distance between interactions, not a fixed distance traveled by every neutron. For bomb theory, attenuation and mean free path help predict how many neutrons will remain available as they cross different materials and geometries."},{"day":8,"title":"Neutron energy and moderation","progress":"Explain elastic scattering, energy transfer, why light nuclei can be effective moderators, and the distinction between slowing and absorbing neutrons.","takeaway":"Energy management and neutron removal are not interchangeable.","game":{"type":"Protocol","columns":["What happens to the neutron","Which process that is"],"title":"Choose the neutron interaction","setup":"Match each physical observation to the most relevant interaction idea.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Neutron loses energy but remains a neutron -> Elastic scattering; Neutron disappears and a compound nucleus forms -> Absorption; Direction changes with little energy loss -> Scattering from a heavy nucleus; A material slows neutrons efficiently through repeated collisions -> Scattering from light nuclei","why":"Slowing, redirecting and absorbing are three different processes with three different consequences. In elastic scattering the neutron transfers some energy and continues as a neutron — it is still in the system. In absorption it is captured into a compound nucleus and is gone. Scattering off a heavy nucleus changes direction and gives up very little energy, because a heavy target barely recoils. Scattering off light nuclei is what slows neutrons efficiently, because a light nucleus can take a large share of the energy in one collision.","scenarios":["Neutron loses energy but remains a neutron","Neutron disappears and a compound nucleus forms","Direction changes with little energy loss","A material slows neutrons efficiently through repeated collisions"],"choices":["Identify elastic scattering: a neutron collides with a nucleus, transfers some energy, and continues as a neutron.","Identify absorption: the neutron is captured and becomes part of a compound nucleus, so it no longer continues through the material.","Expect scattering from a heavy nucleus: the neutron may change direction but usually gives up only a small fraction of its energy.","Use repeated scattering from light nuclei to slow neutrons efficiently, because a light nucleus can take a larger share of the neutron’s energy."],"mapping":[0,1,2,3],"rebuttals":["A neutron that loses energy and remains a neutron has scattered elastically. It is still available to do something later.","A neutron that disappears into a compound nucleus has been absorbed. It is removed from the population entirely, which is a different consequence.","A direction change with little energy loss is scattering off a heavy nucleus: the target hardly recoils, so it hardly takes any energy.","Efficient slowing through repeated collisions needs light nuclei, because a light nucleus can take a large share of the energy each time."]},"story":"A neutron leaving a fission event carries a great deal of energy, and what happens next depends entirely on what it hits. Confusing the possibilities is how a shielding calculation goes quietly wrong.","assumes":["a light ball loses more energy hitting something its own size"]},{"day":9,"title":"Diffusion and leakage","progress":"Introduce random walks, diffusion length, boundary leakage, and the competition between interaction and escape.","takeaway":"Many collisions can produce a modest net displacement because directions randomize.","game":{"type":"Ballpark","title":"Random-walk distance","setup":"A neutron in a large water tank makes about 100 scattering steps of about 2 cm each.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 20 cm.","why":"2 x sqrt(100) = 20 cm, far less than the 200 cm of path travelled.","givens":["Root-mean-square displacement is roughly step length x sqrt(number of steps)"],"task":"Estimate the net displacement.","relationship":"A random walk goes net distance ≈ step length × the square root of the number of steps."},"story":"After many random collisions, a neutron’s total path can be long even though its net displacement is modest. This random-walk behavior is called diffusion, and boundaries allow some neutrons to leak out before they cause another reaction. Because a bomb is finite rather than an infinite block of material, the theory group must estimate the competition between collisions inside the assembly and escape through its surface."},{"day":10,"title":"Neutron multiplication factor","progress":"Define k as neutrons in one generation divided by the previous generation and interpret subcritical, critical, and supercritical behavior at a high level.","takeaway":"Small deviations of k from one compound over many generations.","game":{"type":"Ballpark","title":"Generation-by-generation multiplication","setup":"A simplified system begins with 1,000 neutrons and has k=0.95.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 900 neutrons.","why":"1000 x 0.95^2 is about 903.","givens":["After one generation N1=k N0","After two generations N2=k^2 N0"],"task":"Estimate the population after two generations.","relationship":"After n generations, the population = the starting number × kⁿ."},"story":"The multiplication factor k compares the number of neutrons in one generation with the number in the previous generation. If k is below one the chain fades, at one it stays steady, and above one it grows. A bomb requires a rapidly growing chain for a very short time, so even a small change in k can have a large effect after many generations."},{"day":11,"title":"Prompt and delayed neutron timescales","progress":"Distinguish prompt and delayed contributions, explain why multiple timescales matter in reactor control, and avoid weapon-specific timing details.","takeaway":"A small component can dominate controllability when its timescale is very different.","game":{"type":"Sequence","title":"Separate the timescales","setup":"Order the reasoning used to analyze a mixed prompt-delayed population.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Identify which neutron populations are present -> Assign each population its characteristic delay or lifetime -> Weight each contribution by its fraction -> Combine them to predict the system response)","why":"A useful kinetics model preserves both the small delayed fraction and its much longer timescale.","cards":["Identify which neutron populations are present","Assign each population its characteristic delay or lifetime","Weight each contribution by its fraction","Combine them to predict the system response"],"order":[0,1,2,3]},"story":"Most fission neutrons appear almost immediately, while a small fraction are emitted later by radioactive fragments. Delayed neutrons make reactors controllable on human timescales, but a bomb’s energy release is governed mainly by prompt neutrons because the assembly changes in microseconds. The theory team therefore must separate two very different clocks that come from the same fission process."},{"day":12,"title":"Criticality safety as a systems concept","progress":"Treat criticality safety as control of mass, geometry, moderation, reflection, spacing, and process discipline without giving operational thresholds.","takeaway":"Criticality safety is achieved by layered limits and verified process control, not by one calculation.","game":{"type":"Science Tank","title":"Where should the safety-analysis budget go?","setup":"A laboratory has 100 credits to reduce uncertainty in routine handling of fissile materials.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 45 to A, 50 to B, 5 held for follow-up; near-zero to C.","why":"The highest-value work reduces uncertainty in the variables that govern neutron balance and provides independent controls.","proposals":[{"label":"A","text":"Improve independent mass-accounting and process limits"},{"label":"B","text":"Characterize accidental moderation and geometry changes"},{"label":"C","text":"Add a decorative warning display with no new measurement"}],"research":"","recommended":{"A":45,"B":50}},"story":"A system can become dangerous long before anyone intends to build a weapon if enough fissile material, reflection, moderation, or favorable geometry brings k close to one. Criticality safety treats those factors as a connected system rather than relying on a single rule. At Los Alamos, scientists must study chain reactions while also designing handling arrangements that prevent an accidental self-sustaining reaction."},{"day":13,"title":"Energy released in fission","progress":"Explain Q-values and the distribution of released energy among fragments, neutrons, and radiation.","takeaway":"Macroscopic nuclear energy comes from an immense number of microscopic events.","game":{"type":"Ballpark","title":"Scale an energy release","setup":"Assume a notional fission releases about 200 MeV and 1 MeV=1.60 x 10^-13 joule.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 3.2 x 10^-11 J.","why":"The energy per event is tiny macroscopically but enormous per atom.","givens":["Energy per event = 200 x 1.60 x 10^-13 J"],"task":"Estimate joules per fission.","relationship":"Energy in joules = energy in MeV × the number of joules in one MeV."},"story":"A single fission releases energy in several forms, and multiplying that microscopic energy by an enormous number of nuclei produces a macroscopic explosion. Estimating the total energy requires the theory group to move carefully from energy per event to number of events. This scale conversion helps connect nuclear physics to the blast, heat, and radiation that a bomb can produce."},{"day":14,"title":"Fission fragments and heat deposition","progress":"Describe why charged fragments stop over short distances and deposit most of their energy locally.","takeaway":"Energy accounting must include both immediate deposition and later decay heat.","game":{"type":"Protocol","columns":["Which product carries the energy","Where that energy ends up"],"title":"Where does the energy go?","setup":"Match each fission-energy carrier to its dominant transport behavior.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Heavy charged fragments -> Stops within microns of the event, making it the dominant source of immediate local heating.; Fast neutrons -> Carries energy tens of centimetres away and can start further fissions before slowing down.; Prompt gamma rays -> Leaves at the speed of light and needs dense material to be stopped.; Delayed beta and gamma radiation -> Keeps releasing energy for minutes to years afterwards, so the products must be cooled and shielded long after the event.","why":"Different carriers move energy over different distances and times.","scenarios":["Heavy charged fragments","Fast neutrons","Prompt gamma rays","Delayed beta and gamma radiation"],"choices":["Stops within microns of the event, making it the dominant source of immediate local heating.","Carries energy tens of centimetres away and can start further fissions before slowing down.","Leaves at the speed of light and needs dense material to be stopped.","Keeps releasing energy for minutes to years afterwards, so the products must be cooled and shielded long after the event."],"mapping":[0,1,2,3]},"story":"Most fission energy first appears as the kinetic energy of two heavy fragments, which stop quickly and heat nearby material. Neutrons and gamma rays travel farther, while later radioactive decays continue to release energy after the initial event. Understanding these channels is essential for predicting both the rapid heating that drives an explosion and the radiation hazards that remain afterward."},{"day":15,"title":"Neutron spectra","progress":"Distinguish thermal, epithermal, and fast ranges qualitatively and explain why cross sections depend on neutron energy.","takeaway":"Reaction rates depend on the overlap of the spectrum with the cross-section curve.","game":{"type":"Sequence","title":"From source spectrum to reaction rate","setup":"Order the steps in a spectrum-aware reaction calculation.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Describe the neutron flux as a function of energy -> Use an energy-dependent cross section -> Multiply flux and cross section within each energy range -> Integrate or sum over the spectrum)","why":"One average energy can hide resonances and threshold behavior.","cards":["Describe the neutron flux as a function of energy","Use an energy-dependent cross section","Multiply flux and cross section within each energy range","Integrate or sum over the spectrum"],"order":[0,1,2,3]},"story":"Neutrons are not all born with the same energy, and reaction probabilities can change sharply across the neutron-energy spectrum. A useful prediction must combine how many neutrons exist at each energy with the cross section at that energy. For bomb design, this prevents the theory group from replacing a broad spectrum with one misleading ‘average neutron.’"},{"day":16,"title":"Resonances and thresholds","progress":"Explain resonant absorption and threshold reactions in qualitative terms.","takeaway":"When the physics may vary rapidly with energy, coverage can matter more than one exquisitely precise point.","game":{"type":"Science Tank","title":"Fund the next cross-section campaign","setup":"Only one of three measurement campaigns can be fully supported.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 70 to B, 20 to A, 10 held or used for calibration; little to C.","why":"A scan can reveal structure that a single point cannot, while some precision and calibration remain valuable.","proposals":[{"label":"A","text":"One high-precision point far from any predicted structure"},{"label":"B","text":"A coarse energy scan across the expected resonance region"},{"label":"C","text":"Repeat a known thermal point with the same apparatus"}],"research":"","recommended":{"B":70,"A":20}},"story":"Some nuclear reactions become especially likely at resonance energies, while others require a threshold energy before they can occur at all. These features make reaction rates sensitive to the neutron spectrum and material composition. Los Alamos needs to know where such sharp changes occur because a small shift in energy can alter whether neutrons multiply, scatter, or disappear."},{"day":17,"title":"Spontaneous fission and neutron backgrounds","progress":"Describe spontaneous fission, alpha-n reactions, cosmic backgrounds, and why a source term must include uncertainty.","takeaway":"The same background source term is negligible or decisive depending on how long the system is exposed to it.","game":{"type":"Ballpark","title":"Neutrons during the assembly window","setup":"A sample emits spontaneous-fission neutrons at about 10^4 per second. A slow mechanical assembly takes about 10^-3 s; a fast one takes about 10^-6 s.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 10 neutrons for the slow assembly, against about 0.01 for the fast one.","why":"A spontaneous-fission source gives a steady random background of neutrons. Whether that background matters depends entirely on how long the assembly spends in a state where one stray neutron could start something, because the expected number of neutrons is the rate multiplied by that window. A process lasting a thousandth of a second sees a thousand times as many chances as one lasting a millionth. Same source term, same material, and two completely different verdicts — which is the whole reason to do the arithmetic rather than argue about the number.","givens":["Expected events = rate x exposure time","Slow assembly window = 10^-3 s","Fast assembly window = 10^-6 s"],"task":"Estimate the neutrons expected during the slow assembly, then compare with the fast one.","relationship":"Expected events = the rate × the length of the window they could land in."},"story":"A sample on the bench is emitting neutrons all by itself, at a rate the counters can measure. Two assembly schemes are on the table, and one takes a thousand times longer than the other.","assumes":["some heavy nuclei split without being hit by anything"]},{"day":18,"title":"Branching processes","progress":"Model a chain reaction as a branching process and connect average reproduction to fluctuations.","takeaway":"Near a threshold, fluctuations matter as much as the mean.","game":{"type":"Sequence","title":"Build a branching model","setup":"Order the steps in a simple neutron-family simulation.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Assign a probability distribution for offspring per neutron -> Sample offspring for the first generation -> Repeat sampling for later generations -> Summarize extinction probability and population spread)","why":"An average multiplication factor does not describe the full distribution of outcomes.","cards":["Assign a probability distribution for offspring per neutron","Sample offspring for the first generation","Repeat sampling for later generations","Summarize extinction probability and population spread"],"order":[0,1,2,3]},"story":"A neutron chain reaction is a branching process: each neutron may produce zero, one, or several descendants. Even when the average grows, individual chains can die out by chance, while others become unusually large. This statistical picture helps Los Alamos scientists understand why averages alone cannot describe the early generations of a bomb’s chain reaction."},{"day":19,"title":"Geometry and neutron leakage","progress":"Explain qualitatively how surface-to-volume ratio affects leakage, without calculating weapon dimensions or critical masses.","takeaway":"Geometry influences neutron economy through boundary leakage, not merely through total mass.","game":{"type":"Ballpark","title":"Surface-to-volume of a sphere","setup":"A sphere has a radius of 5 cm.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 0.6 cm^-1; doubling the radius halves it to about 0.3 cm^-1.","why":"Surface-to-volume falls as 1/L, so a larger body has less boundary per unit volume and leaks relatively less.","givens":["For a sphere, surface-to-volume ratio = 3/R","Surface scales as L^2 and volume as L^3"],"task":"Estimate the surface-to-volume ratio, then say what doubling the radius does to it.","relationship":"For a sphere, surface-to-volume ratio = 3 ÷ radius. Leakage follows surface; production follows volume."},"story":"A compact shape has less surface area relative to its volume than an elongated or fragmented shape, so fewer neutrons reach a boundary and escape. Geometry therefore changes neutron leakage even when the material is unchanged. Bomb theorists must connect shape and compression to multiplication because increasing density and reducing leakage can push the system into a rapidly growing chain reaction."},{"day":20,"title":"Uncertainty propagation","progress":"Combine independent uncertainties, separate random and systematic terms, and use sensitivity derivatives.","takeaway":"Adding independent uncertainties linearly is usually too pessimistic; ignoring correlation can be too optimistic.","game":{"type":"Ballpark","title":"Combine two independent uncertainties","setup":"A predicted reaction rate has an 8% cross-section uncertainty and a 6% flux uncertainty.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 10%.","why":"Independent uncertainties combine in quadrature: each is squared, the squares are added, and the root is taken. Eight per cent and six per cent make ten, not fourteen. The consequence is that the largest term dominates and small ones matter far less than intuition suggests — halving the six per cent moves the total barely at all, while halving the eight per cent moves it a great deal. For a laboratory with limited people and time, that ranking is the point: the first job of an uncertainty calculation is to say where effort should go.","givens":["Independent fractional uncertainties combine in quadrature"],"task":"Estimate the total fractional uncertainty.","relationship":"Independent uncertainties add in quadrature: the root of the sum of the squares."},"story":"A predicted reaction rate rests on a cross section known to a few per cent and a flux known to a few more. Theory is being asked how well the prediction is known.","assumes":["two independent errors are unlikely to be wrong the same way at once"]},{"day":21,"title":"Monte Carlo transport","progress":"Explain random sampling of path lengths, reactions, and tallies, along with convergence and variance.","takeaway":"Monte Carlo is a numerical experiment whose uncertainty decreases with the number of histories.","game":{"type":"Sequence","title":"One Monte Carlo history","setup":"Arrange one simulated particle history.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Sample a free path from the attenuation law -> Move the particle to the sampled interaction point -> Sample the interaction type and outgoing state -> Update tallies and continue or terminate the history)","why":"A transport code repeats this physically ordered chain for many histories.","cards":["Sample a free path from the attenuation law","Move the particle to the sampled interaction point","Sample the interaction type and outgoing state","Update tallies and continue or terminate the history"],"order":[0,1,2,3]},"story":"Neutron transport through a complicated assembly involves many possible collisions and paths, so scientists use Monte Carlo methods to follow large numbers of simulated neutrons chosen by random sampling. The result is a statistical estimate rather than one exact trajectory. This gives Los Alamos a way to study complex geometry and rare paths that are difficult to solve with pencil-and-paper equations alone."},{"day":22,"title":"Sensitivity analysis","progress":"Rank parameters by how strongly they affect a prediction and distinguish local sensitivity from global uncertainty.","takeaway":"The largest-looking uncertainty is not always the most important one.","game":{"type":"Science Tank","title":"Which uncertainty should theory reduce first?","setup":"A model depends on three uncertain inputs.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 55 to B, 35 to C, 10 to A.","why":"Decision value depends on uncertainty multiplied by sensitivity, not uncertainty alone.","proposals":[{"label":"A","text":"A parameter with 20% uncertainty but almost no effect on the output"},{"label":"B","text":"A parameter with 5% uncertainty and a very large sensitivity"},{"label":"C","text":"A parameter with 10% uncertainty and moderate sensitivity"}],"research":"","recommended":{"B":55,"C":35,"A":10}},"story":"Sensitivity analysis changes one input at a time to see which uncertain quantity most strongly changes the prediction. A parameter can be poorly known yet unimportant, or precisely known yet crucial. With limited wartime time and equipment, the bomb program needs sensitivity studies to decide which measurements or calculations will most reduce risk."},{"day":23,"title":"Transport equations and approximations","progress":"Introduce the Boltzmann transport equation conceptually, then compare deterministic, diffusion, and Monte Carlo approaches.","takeaway":"Model choice should follow the question and required fidelity.","game":{"type":"Protocol","columns":["What you want to compute","Which method computes it"],"title":"Choose the modeling tool","setup":"Match each modeling need to the most appropriate simplified method.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Rapid whole-system estimate in a strongly scattering region -> The diffusion approximation. Valid once scattering has smoothed the angular distribution, and cheap enough to run by hand.; Detailed treatment of complex geometry and rare paths -> Monte Carlo. Cost scales with the number of histories rather than with geometric complexity, and rare paths appear only if enough are run.; High-precision benchmark in a simple geometry -> A deterministic transport solver. Repeatable and free of statistical noise, but only where the geometry can be gridded.; First-order hand estimate -> A scaling argument. Gives no absolute number, only how the answer moves with size or density — often the decision that actually matters.","why":"No single method is best for every geometry, energy range, or decision.","scenarios":["Rapid whole-system estimate in a strongly scattering region","Detailed treatment of complex geometry and rare paths","High-precision benchmark in a simple geometry","First-order hand estimate"],"choices":["The diffusion approximation. Valid once scattering has smoothed the angular distribution, and cheap enough to run by hand.","Monte Carlo. Cost scales with the number of histories rather than with geometric complexity, and rare paths appear only if enough are run.","A deterministic transport solver. Repeatable and free of statistical noise, but only where the geometry can be gridded.","A scaling argument. Gives no absolute number, only how the answer moves with size or density — often the decision that actually matters."],"mapping":[0,1,2,3]},"story":"No single transport method is best for every problem. Diffusion gives quick estimates when scattering smooths the neutron population, deterministic solvers treat equations directly, and Monte Carlo follows individual random histories. Los Alamos must choose the simplest method that still captures the physics, then check it against more detailed calculations where the approximation might fail."},{"day":24,"title":"Equations of state","progress":"Explain pressure-density-temperature relationships, compressibility, and why extreme-state data require extrapolation.","takeaway":"Extreme-state calculations require both thermodynamic relationships and careful unit scaling.","game":{"type":"Ballpark","title":"Estimate compressive work","setup":"A notional sample experiences an average pressure of 5 x 10^9 Pa while its volume decreases by 2 x 10^-6 m^3.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 1 x 10^4 J.","why":"An equation of state ties pressure, density, temperature and internal energy together for a substance. The familiar handbook values were all taken at room conditions. They describe a completely different regime from the one implosion makes. That is why this work is unforgiving in two directions at once. The thermodynamics has to be right. So does every unit conversion carrying it across many powers of ten. Pressure in pascals times a volume change in cubic metres gives joules, and the powers of ten do most of the work.","givens":["Work scale is pressure x volume change"],"task":"Estimate the work scale.","relationship":"Work ≈ pressure × the volume change it acts through."},"story":"The Theoretical Division is calculating work done on a material at pressures nothing in the laboratory has ever measured. An error in the units looks exactly like an error in the physics.","assumes":["pressure times a volume change is work"]},{"day":25,"title":"Shock waves and conservation laws","progress":"Use conservation of mass, momentum, and energy across a moving discontinuity at a conceptual level.","takeaway":"Shock physics is conservation plus constitutive information.","game":{"type":"Sequence","title":"Analyze a shock","setup":"Order the reasoning for a one-dimensional shock calculation.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Choose upstream and downstream states -> Apply mass conservation across the front -> Apply momentum conservation -> Use energy or an equation of state to close the system)","why":"Conservation equations constrain the jump, while an equation of state supplies missing material behavior.","cards":["Choose upstream and downstream states","Apply mass conservation across the front","Apply momentum conservation","Use energy or an equation of state to close the system"],"order":[0,1,2,3]},"story":"A shock wave is a very thin region where pressure, density, and velocity change abruptly. Conservation of mass, momentum, and energy connects the material before and after the shock. Implosion depends on using shocks to compress material inward, so theory must predict how those waves change at boundaries and whether they produce the intended density increase."},{"day":26,"title":"Symmetry and perturbations","progress":"Introduce spherical harmonics conceptually, distinguish uniform compression from low-order asymmetry, and connect perturbations to observables without specifying device geometry.","takeaway":"Symmetry errors are best diagnosed by decomposing them into modes.","game":{"type":"Protocol","columns":["What the compression looks like","Which mode that is"],"title":"Name the symmetry defect","setup":"Match the observed pattern to the simplest qualitative description.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"All directions shift together -> A monopole, or uniform mode. Changes the assembly’s size but not its shape, altering density without breaking symmetry.; One side leads while the opposite side lags -> A dipole. The centre of compression moves off the geometric centre — displacement rather than distortion.; Four alternating high-low regions appear -> A quadrupole. Volume survives but the sphere goes elongated or flattened, so the shape is wrong even when the size is right.; Small-scale roughness grows over time -> High-order perturbation growth. Short wavelengths grow fastest, so a small initial defect can dominate late in the compression.","why":"Mode language converts a complicated shape into interpretable patterns.","scenarios":["All directions shift together","One side leads while the opposite side lags","Four alternating high-low regions appear","Small-scale roughness grows over time"],"choices":["A monopole, or uniform mode. Changes the assembly’s size but not its shape, altering density without breaking symmetry.","A dipole. The centre of compression moves off the geometric centre — displacement rather than distortion.","A quadrupole. Volume survives but the sphere goes elongated or flattened, so the shape is wrong even when the size is right.","High-order perturbation growth. Short wavelengths grow fastest, so a small initial defect can dominate late in the compression."],"mapping":[0,1,2,3]},"story":"A perfectly spherical implosion is an idealization; real systems contain timing errors, material variations, gaps, and surface roughness. Scientists describe those departures as perturbations with different spatial patterns. Because asymmetries can grow during compression and prevent the core from reaching the required state, Los Alamos must identify which patterns are harmless and which can spoil the bomb."},{"day":27,"title":"Competing timescales","progress":"Compare neutron, hydrodynamic, thermal, detector, and control timescales in a generic coupled system.","takeaway":"Processes separated by many orders of magnitude often require different numerical or experimental treatments.","game":{"type":"Ballpark","title":"How far the front runs during a timing error","setup":"A shock front crosses a generic assembly at about 8 x 10^3 m/s. Two initiation channels fire 0.5 microseconds apart. These are classroom values, not a Fat Man specification.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 4 mm.","why":"Several clocks run at once. Neutron generations multiply on one. The material compresses on another. The assembly begins to blow itself apart on a third. The device works only if multiplication outruns disassembly. These processes differ by many powers of ten, so no single calculation or experiment can hold all of them. The interfaces between them are where it gets hard. This is one: a timing disagreement becomes a geometric error at the speed the wave travels. Half a microsecond is millimetres of asymmetry.","givens":["Wave speed = 8 x 10^3 m/s","Channel spread = 0.5 microseconds = 5 x 10^-7 s","Lead distance = speed x time"],"task":"Estimate how far ahead the early side runs, in millimetres.","relationship":"Distance = speed × time. Multiply by 1,000 to turn metres into millimetres."},"story":"Several clocks run at once during a nuclear explosion, and the whole design problem lives in the gaps between them. The figures here are classroom values.","assumes":["a wave crosses a distance in a time set by its speed"]},{"day":13,"title":"Where the energy in fission comes from","place":"Theoretical Division","scene":"A visitor asks why splitting a heavy nucleus releases energy while splitting a light one costs energy. The blackboard has the binding-energy curve on it and nobody has used it to answer.","story":"A visitor asks why splitting a heavy nucleus releases energy while splitting a light one costs energy. The blackboard has the binding-energy curve on it and nobody has used it to answer.","takeaway":"The binding-energy-per-nucleon curve says which way a nuclear reaction releases energy.","game":{"type":"CHOICE","title":"Where the energy in fission comes from","setup":"Theoretical Division","play":"Why does splitting uranium release energy while splitting carbon would absorb it?","question":"Why does splitting uranium release energy while splitting carbon would absorb it?","choices":["Binding energy per nucleon peaks near iron, so heavy nuclei move up the curve by splitting and light ones do not.","Heavy nuclei are unstable and light nuclei are stable, and instability is itself the energy source.","Uranium has more protons, so electrostatic repulsion supplies the energy directly.","Splitting always releases energy; carbon simply releases less of it."],"correctChoice":"Binding energy per nucleon peaks near iron, so heavy nuclei move up the curve by splitting and light ones do not.","answer":"Binding energy per nucleon peaks near iron, so heavy nuclei move up the curve by splitting and light ones do not.","why":"Binding energy per nucleon rises steeply from hydrogen, peaks around iron and nickel, and falls slowly to uranium. A reaction releases energy when its products sit HIGHER on that curve than its reactants, because the products are more tightly bound. Uranium splitting into two mid-mass fragments moves up the curve, so energy comes out. Carbon splitting would move down it, so energy would have to go in. The same curve is why fusion of light nuclei also releases energy — from the other side of the peak.","rebuttals":["Instability sets the rate at which something decays, not how much energy the reaction releases.","Repulsion is part of why heavy nuclei are less tightly bound, but the energy released is the change in binding energy of the whole system.","Splitting light nuclei costs energy. That is what the left-hand side of the curve means."]},"assumes":["a nucleus is held together by binding energy"]},{"day":29,"title":"Theory-experiment reconciliation","progress":"Use residuals, covariance, alternative hypotheses, and experiment design to resolve disagreement.","takeaway":"The best response to disagreement is a test that can separate competing causes.","game":{"type":"CHOICE","title":"Spend the last theory campaign","setup":"Theory and experiment disagree by three standard deviations.","play":"Theory and experiment differ by three standard deviations. What does the division do?","answer":"Audit the shared calibrations and covariance, then design a discriminating measurement.","why":"Two numbers that share a calibration can be three sigma apart because one error was counted twice. The audit is cheap enough to do first. What has to follow it is a measurement whose outcome differs depending on which explanation is true. A detector artefact, a missing physical effect, or an approximation pushed past its range all predict different things. Design the test that separates them, and spend the credits there rather than on the one that reassures.","task":"Theory and experiment differ by three standard deviations. What does the division do?","question":"Theory and experiment differ by three standard deviations. What does the division do?","choices":["Audit the shared calibrations and covariance, then design a discriminating measurement.","Retune the uncertain parameters until the model reproduces the measurement.","Collect more of the same data, to see whether the gap narrows.","Adopt the experimental value and record the disagreement in the report."],"correctChoice":"Audit the shared calibrations and covariance, then design a discriminating measurement.","rebuttals":["Retuning parameters to force agreement hides the discrepancy inside a number and destroys the only evidence that something was wrong.","More of the same data carries the same systematic. It narrows the statistical error around a value that may be biased.","Adopting the experimental value settles the disagreement by whoever wrote it down last, and leaves the cause in place for the next comparison."]},"story":"Theory and experiment disagree by three standard deviations and the division has to decide what to do about it. Arguing about which explanation is right is cheaper than finding out, and worth less.","assumes":["three standard deviations is a real disagreement, not noise"]},{"day":15,"title":"Why light nuclei release energy too","place":"Theoretical Division","scene":"The curve on the board runs from 1.1 MeV per nucleon at deuterium to 8.8 at iron and back to 7.6 at uranium. A younger member of the division has asked what happens at the light end of it, where the slope is steepest.","story":"The curve on the board runs from 1.1 MeV per nucleon at deuterium to 8.8 at iron and back to 7.6 at uranium. A younger member of the division has asked what happens at the light end of it, where the slope is steepest.","takeaway":"Fusion of light nuclei releases energy for the same reason fission of heavy ones does, and it is harder to start.","game":{"type":"CHOICE","title":"Why light nuclei release energy too","setup":"Theoretical Division","play":"Fusing hydrogen releases energy. Why is it so much harder to bring about than fission?","question":"Fusing hydrogen releases energy. Why is it so much harder to bring about than fission?","choices":["Both nuclei are positive, so they must overcome electrostatic repulsion before the short-range nuclear force can bind them.","Fusion releases less energy per reaction, so less is available to sustain it.","Light nuclei are more tightly bound already, so there is little to gain.","Fusion requires a neutron to start it, and free neutrons are scarce."],"correctChoice":"Both nuclei are positive, so they must overcome electrostatic repulsion before the short-range nuclear force can bind them.","answer":"Both nuclei are positive, so they must overcome electrostatic repulsion before the short-range nuclear force can bind them.","why":"Fusion moves up the binding-energy curve from the light end, so it releases energy — more per nucleon than fission does. The difficulty is getting there: two positive nuclei repel, and the nuclear force that binds them only reaches across about a femtometre. Closing that gap needs kinetic energy, which means temperatures of millions of kelvin, whereas fission needs only a slow neutron and no barrier at all. Energy released and ease of ignition are separate questions, and confusing them is the usual error.","rebuttals":["Fusion releases more energy per nucleon than fission, not less.","Light nuclei are LESS tightly bound per nucleon, which is exactly why fusing them gains energy.","A neutron initiates fission. Fusion is initiated by temperature and pressure."]},"assumes":["like charges repel, and the nuclear force acts only at very short range"]}],"P":[{"day":1,"title":"Ionization and detector signals","progress":"Explain how radiation deposits energy and creates ionization, excitation, light, or charge that can be converted to an electrical signal.","takeaway":"A detector measures the consequences of an interaction, not radiation directly.","game":{"type":"Sequence","title":"From radiation to a recorded pulse","setup":"Order a generic detector chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Radiation deposits energy in the sensitive material -> The material produces charge carriers or photons -> Electronics collect and amplify the response -> The data system digitizes and stores a pulse)","why":"A detector measures the consequences of an interaction, never the radiation itself. Energy has to be deposited in the sensitive material first — nothing downstream exists until that happens. That deposit produces charge carriers or photons, which is the transducer step and the one that decides what the instrument is sensitive to at all. Electronics then collect and amplify a response too small to handle raw. The data system digitises and stores a pulse last. Get the chain wrong and you are measuring your own apparatus.","cards":["Radiation deposits energy in the sensitive material","The material produces charge carriers or photons","Electronics collect and amplify the response","The data system digitizes and stores a pulse"],"order":[0,1,2,3],"rebuttals":["Energy deposited in the sensitive material is where everything starts. No deposit, no signal, however good the electronics are.","Charge carriers or photons are the transducer step: the point where a nuclear event becomes something electrical.","Collection and amplification come third. They make a tiny response handleable, and they cannot create one that was never made.","Digitising and storing the pulse is last. It is the step people picture as the measurement, and it is the only one that adds no physics."]},"story":"The Physics Division cannot see a single neutron or alpha particle, and neither can anybody else. Everything the Hill will claim about cross sections, backgrounds and yields rests on a chain of conversions working in order.","assumes":["radiation deposits energy in whatever it passes through"]},{"day":2,"title":"Gas-filled detectors","progress":"Compare ionization chambers, proportional counters, and Geiger-Muller operation qualitatively.","takeaway":"Operating voltage determines what information a gas detector preserves.","game":{"type":"Protocol","columns":["What you want to measure","Which operating region measures it"],"title":"Choose the gas-detector regime","setup":"Match the measurement goal to the best operating regime.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Measure average dose rate over a broad range -> The ionization-chamber region. No gas multiplication, so the output is a steady current proportional to total ionization rather than one pulse per event.; Preserve some pulse-size information -> The proportional region. Multiplication is large but linear, so pulse height still tracks energy deposited.; Count individual events with simple electronics -> The Geiger–Müller region. Every event yields the same large pulse: easy to count, useless for spectroscopy.; Avoid operation where continuous discharge dominates -> Below electrical breakdown. Past it the discharge sustains itself and the output stops depending on the radiation at all.","why":"Electric-field strength changes whether the detector measures total ionization, amplified ionization, or a saturated discharge.","scenarios":["Measure average dose rate over a broad range","Preserve some pulse-size information","Count individual events with simple electronics","Avoid operation where continuous discharge dominates"],"choices":["The ionization-chamber region. No gas multiplication, so the output is a steady current proportional to total ionization rather than one pulse per event.","The proportional region. Multiplication is large but linear, so pulse height still tracks energy deposited.","The Geiger–Müller region. Every event yields the same large pulse: easy to count, useless for spectroscopy.","Below electrical breakdown. Past it the discharge sustains itself and the output stops depending on the radiation at all."],"mapping":[0,1,2,3]},"story":"A gas-filled detector collects charge created when radiation ionizes gas molecules. Depending on the applied voltage, the same tube can measure average current, amplify individual ionization events, or produce nearly identical large pulses. Choosing the correct operating region matters because the bomb program needs different instruments for dose, counting, and pulse information rather than one detector used beyond its useful range."},{"day":3,"title":"Scintillation detectors","progress":"Describe scintillation light production, photodetectors, light collection, decay time, and energy resolution.","takeaway":"More detected photons usually improve statistical energy resolution.","game":{"type":"Ballpark","title":"Photon statistics","setup":"A scintillator produces about 10,000 detected photoelectrons for a reference event.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 1%.","why":"1/sqrt(10000)=0.01.","givens":["Statistical fractional fluctuation is roughly 1/sqrt(N)"],"task":"Estimate the fractional statistical fluctuation.","relationship":"Counting fluctuation is Poisson: the fractional noise = 1 ÷ the square root of the number counted."},"story":"A scintillator gives off tiny flashes of light when radiation deposits energy, and a photosensor converts those flashes into electrical pulses. Different scintillators vary in speed, brightness, and sensitivity to particle type. Los Alamos uses fast scintillation signals when timing is crucial, but must separate real flashes from electronic noise and understand how light output relates to deposited energy."},{"day":4,"title":"Semiconductor detectors","progress":"Explain electron-hole creation, depletion regions, bias, low-noise electronics, and why cooling can matter.","takeaway":"Semiconductors provide excellent energy information because little energy is required per charge pair.","game":{"type":"Sequence","title":"Build a semiconductor measurement","setup":"Order the detector preparation and measurement steps.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Establish a depleted sensitive region with bias -> Radiation creates electron-hole pairs -> The electric field collects the carriers -> A low-noise preamplifier converts charge to a pulse)","why":"Charge must be created, transported, and measured before energy can be inferred.","cards":["Establish a depleted sensitive region with bias","Radiation creates electron-hole pairs","The electric field collects the carriers","A low-noise preamplifier converts charge to a pulse"],"order":[0,1,2,3]},"story":"In a semiconductor detector, radiation creates mobile electrons and holes inside a solid crystal. An electric field sweeps those charges to electrodes, producing a pulse whose size can measure energy very precisely. Such detectors illustrate the same basic challenge that appears throughout the bomb program: preserve a small physical signal while preventing leakage current, noise, and imperfect charge collection from distorting it."},{"day":5,"title":"Efficiency and geometry","progress":"Distinguish intrinsic efficiency, geometric efficiency, absolute efficiency, and solid angle.","takeaway":"A highly efficient material can still record few events if it covers little solid angle.","game":{"type":"Ballpark","title":"Geometric efficiency scale","setup":"A small detector intercepts 1% of isotropically emitted particles and detects 50% of those that enter.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 0.5%.","why":"0.01 x 0.50 = 0.005.","givens":["Absolute efficiency = geometric fraction x intrinsic efficiency"],"task":"Estimate the absolute efficiency.","relationship":"Absolute efficiency = geometric acceptance × intrinsic efficiency."},"story":"Detector efficiency is the fraction of emitted particles that are actually recorded, and geometry controls how many particles travel toward the detector at all. Moving a detector farther away can reduce the count even though the source has not changed. Los Alamos must correct for both effects before comparing experiments or using count rates to test bomb calculations."},{"day":6,"title":"Background measurement","progress":"Identify environmental, electronic, cosmic, and sample-container backgrounds and design a background run.","takeaway":"Background subtraction is credible only when the background is measured under comparable conditions.","game":{"type":"Diagnosis","pack":"p6","title":"The excess that would not go away","setup":"You are deciding whether a weak sample is really emitting anything.","play":"Read the whole reading panel, including the calm readings, then select the one cause that fits all of it.","answer":"The detector or its holder is contaminated","why":"A detector counts events with no sample present. Cosmic rays, natural activity in the walls and containers, and the electronics all contribute. Subtracting a background only means something if it was measured the same way as the sample. Same geometry, same shielding, same instrument, close enough in time that nothing has drifted. So the background is taken with the instrument you will use, not merely in the room you will use it in. An excess that follows the instrument to a clean room was never coming from the sample."},"story":"A weak sample has been counting for an hour and the question is whether it is emitting anything at all. This is where an experimental group either establishes a real signal or convinces itself of one.","assumes":["a detector records events even with no sample present"]},{"day":7,"title":"Poisson counting statistics","progress":"Use mean, variance, standard deviation, and the square-root-N rule for independent counts.","takeaway":"Four times as many counts are needed to cut statistical uncertainty in half.","game":{"type":"Ballpark","title":"Counting precision","setup":"A run records 400 net counts with negligible background uncertainty.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 5%.","why":"A repeat of the same run would not give the same total, and for counting like this the typical fluctuation grows like the square root of the number of counts. So the fractional uncertainty is one over that square root, and it falls slowly: four hundred counts gives five per cent, and halving that to two and a half means counting four times as long. That is what makes this a planning tool rather than a curiosity. Knowing what a longer run would actually buy is how experiments get planned instead of wished for.","givens":["Poisson standard deviation is about sqrt(N)","Fractional uncertainty is sqrt(N)/N"],"task":"Estimate the fractional statistical uncertainty.","relationship":"Fractional uncertainty = 1 ÷ the square root of the number of counts."},"story":"A run has finished with four hundred net counts and somebody wants to know how well it is known. Beam time, material and shift hours are all scarce here.","assumes":["radioactive decays arrive at random"]},{"day":8,"title":"Background subtraction uncertainty","progress":"Combine sample and background counting uncertainties with proper scaling.","takeaway":"Subtracted backgrounds add uncertainty even though they reduce the central value.","game":{"type":"Ballpark","title":"Subtract a background","setup":"A sample run records 1,000 counts and an equal-duration background run records 100 counts.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"900 +/- about 33 counts.","why":"Net is 900; sqrt(1100) is about 33.","givens":["Net counts = sample - background","Variance of independent difference = 1000 + 100"],"task":"Estimate net counts and its standard deviation.","relationship":"Each count has Poisson noise, and the two are independent, so the uncertainty on the difference = √(sample + background)."},"story":"A corrected signal is often the sample count minus a separately measured background count. Both measurements fluctuate, so their uncertainties must be combined rather than assigning all uncertainty to the sample alone. In bomb experiments, weak diagnostic signals can be overwhelmed by an uncertain background even when the subtraction produces a positive number."},{"day":9,"title":"Dead time","progress":"Explain paralyzable and nonparalyzable dead time qualitatively and identify count losses at high rate.","takeaway":"High observed rates can understate the true rate because the system is temporarily blind after each event.","game":{"type":"Ballpark","title":"Dead-time correction scale","setup":"A detector has nonparalyzable dead time tau = 10 microseconds and records 2,000 counts/s.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 98%.","why":"R tau = 0.02, small enough for the linear correction to hold.","givens":["Live fraction is about 1 - R tau while R tau stays small"],"task":"Estimate the live fraction.","relationship":"Live fraction = 1 − (event rate × dead time per event). Multiply by 100 for a percentage."},"story":"After recording an event, a detector or electronic circuit may need a short recovery time during which it cannot record another event. At high rates, this dead time causes the measured count to fall below the true rate. Los Alamos must correct or avoid dead-time losses because the most important bomb experiments can produce signals far faster than ordinary laboratory measurements."},{"day":10,"title":"Pulse height and energy calibration","progress":"Connect pulse amplitude to deposited energy and use known lines to create a calibration curve.","takeaway":"Calibration is a measured mapping, not a label pasted onto the x-axis.","game":{"type":"Sequence","title":"Calibrate an energy spectrum","setup":"Order the calibration workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Acquire spectra from known reference lines -> Locate peak channel positions -> Fit channel-to-energy relationship -> Apply the calibration to unknown peaks and propagate uncertainty)","why":"The instrument never measured energy. It measured the size of electrical pulses, and the axis is a claim that a particular pulse size corresponds to a particular deposited energy. That claim has to be established before an unknown spectrum means anything, which fixes the order: spectra from known reference lines first, then the peak channel positions, then a fit that maps channel to energy. Only then can the calibration be applied to unknown peaks — and the uncertainty in the fit has to travel with it.","cards":["Acquire spectra from known reference lines","Locate peak channel positions","Fit channel-to-energy relationship","Apply the calibration to unknown peaks and propagate uncertainty"],"order":[0,1,2,3],"rebuttals":["Acquire the reference spectra first. Without lines of known energy there is nothing to calibrate against.","Locate the peak channels second. The peak position is the measured quantity; the energy is not, yet.","Fit channel to energy third. This is the mapping, and it is where the uncertainty in the calibration is born.","Apply it to the unknowns last, and propagate the uncertainty. An uncalibrated axis is a confident-looking way to compare two things that were never comparable."]},"story":"A spectrum is on the bench and somebody has written particle energies along the bottom of it. Los Alamos is about to compare spectra taken on different instruments in different buildings.","assumes":["an instrument records something electrical, not the quantity you wanted"]},{"day":11,"title":"Energy resolution","progress":"Define full width at half maximum, separate statistical and electronic contributions, and compare detectors fairly.","takeaway":"Resolution should be quoted relative to energy when comparing peaks at different energies.","game":{"type":"Ballpark","title":"Resolution percentage","setup":"A spectral peak is centered at 1.0 MeV with FWHM 0.05 MeV.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"5%.","why":"0.05/1.0 x 100%=5%.","givens":["Percent resolution = FWHM / peak energy x 100%"],"task":"Estimate the percent resolution.","relationship":"Resolution = peak width ÷ peak energy, as a percentage."},"story":"Energy resolution describes whether a detector can distinguish two nearby energies. Even a perfectly monoenergetic source produces a peak with finite width because charge production, light collection, and electronics fluctuate. Los Alamos needs enough resolution to tell whether a broad feature represents one process, several overlapping processes, or an instrument that is performing poorly."},{"day":12,"title":"Timing calibration","progress":"Explain trigger delay, cable delay, clock synchronization, time walk, and reference pulses.","takeaway":"Timing systems require both a common reference and channel-by-channel calibration.","game":{"type":"Diagnosis","pack":"p12","title":"Eight channels that will not agree","setup":"You are finding out why a timing array disagrees with itself.","play":"Read the whole reading panel, including the calm readings, then select the one cause that fits all of it.","answer":"Random jitter at the threshold","why":"Every channel has to share one clock and have its own delays known. Cable length adds time. An electronic threshold shifts when a pulse is registered. A larger pulse crosses a threshold sooner than a smaller one even when the physical event was simultaneous. All of that is instrument, not physics — and the useful distinction is that a fixed error can be calibrated out, while a random one has to be engineered out. A channel with an uncalibrated delay produces a beautiful, repeatable, wrong answer."},"story":"A timing array is disagreeing with itself, and until that is settled no symmetry claim from it means anything. The Hill is about to spend months measuring differences of nanoseconds.","assumes":["an instrument adds its own delays to what it records"]},{"day":13,"title":"Coincidence measurements","progress":"Explain coincidence windows, accidental coincidences, true correlations, and timing spectra.","takeaway":"Coincidence is powerful only when the accidental rate is quantified.","game":{"type":"Ballpark","title":"Accidental coincidence rate","setup":"Two independent detectors count at 100/s and 200/s with a 1 microsecond coincidence window.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 0.02 per second.","why":"100 x 200 x 10^-6 = 0.02/s.","givens":["Accidental rate is roughly R1 R2 Delta t"],"task":"Estimate the accidental coincidence rate.","relationship":"Accidental coincidences = rate in one detector × rate in the other × the width of the coincidence window."},"story":"Coincidence measurements ask whether two detectors recorded events within the same short time window. True coincidences can reveal that signals came from one physical event, while random coincidences occur by chance. The bomb program uses coincidence logic to reject background and to connect different measurements to the same rapidly changing experiment."},{"day":14,"title":"Time of flight","progress":"Connect path length and arrival time to particle velocity and energy at a conceptual level.","takeaway":"Time-of-flight converts precise timing and known geometry into kinematic information.","game":{"type":"Ballpark","title":"A simple time-of-flight estimate","setup":"A particle travels 3 m in 100 ns.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 3 x 10^7 m/s.","why":"3/(100 x 10^-9)=3 x 10^7 m/s.","givens":["Speed = distance/time"],"task":"Estimate the speed.","relationship":"Speed = distance ÷ time."},"story":"Time of flight estimates particle speed by measuring how long it takes to cross a known distance. The method requires a start signal, a stop signal, and a carefully measured path. Los Alamos uses timing to infer neutron energies and other fast processes, so a clock error can masquerade as a change in the physics."},{"day":15,"title":"Neutron detection","progress":"Compare recoil-proton, capture-reaction, activation, and scintillation approaches qualitatively.","takeaway":"The best neutron detector depends on energy range, timing, and whether real-time data are required.","game":{"type":"Diagnosis","pack":"p15","title":"The neutrons that never arrived","setup":"You are checking a neutron counter that reads well below prediction.","play":"Read the whole reading panel, including the calm readings, then select the one cause that fits all of it.","answer":"The discriminator threshold is set too high","why":"A neutron carries no charge, so it cannot ionise a detector the way an alpha particle does. Every neutron detector works indirectly. It turns the neutron into something charged, or into light, or into a radioactive product counted later. Each conversion has its own efficiency and its own energy range. Each is a place a count can be lost with nothing looking broken. So before believing a low number, find one measurement that does not go through the same electronics. A threshold set too high loses real events silently."},"story":"A neutron counter is reading well below prediction and nobody yet knows whether the physics or the instrument is at fault. The measurement about to be built on this counter is one the whole plutonium programme depends on.","assumes":["a detector responds to charge, and a neutron carries none"]},{"day":16,"title":"Gamma-ray spectroscopy","progress":"Introduce photopeaks, Compton continua, escape features, and shielding.","takeaway":"A spectral line is evidence only after instrumental response and background are understood.","game":{"type":"Sequence","title":"Interpret a gamma spectrum","setup":"Order the analysis from raw spectrum to line identification.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Subtract or model the background -> Calibrate energy and resolution -> Identify statistically significant peaks -> Compare energies and intensities with candidate transitions)","why":"Peak finding without background and calibration invites false identifications.","cards":["Subtract or model the background","Calibrate energy and resolution","Identify statistically significant peaks","Compare energies and intensities with candidate transitions"],"order":[0,1,2,3]},"story":"Gamma-ray spectroscopy identifies nuclear transitions by measuring the energies of penetrating photons. Peaks can reveal which radioactive nuclei are present, but background, detector resolution, and efficiency all affect the spectrum. Los Alamos uses gamma measurements to study fission products and materials, making careful calibration essential for turning peaks into physical conclusions."},{"day":17,"title":"Alpha and beta counting","progress":"Explain short ranges, window losses, self-absorption, backscatter, and sample preparation.","takeaway":"Good sample preparation is part of the detector, not an afterthought.","game":{"type":"Protocol","columns":["What the counter shows","What you do about it"],"title":"Prepare the right source","setup":"Match each measurement problem to the best control.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Alpha peak is broadened and shifted low -> Prepare a thinner, more uniform deposit; Beta rate changes with backing material -> Standardize backing and geometry; Counts vanish when the source is moved a few centimeters away -> Recognize the short alpha range in air; Window blocks nearly all events -> Use an appropriately thin entrance window","why":"Sample geometry and window materials can dominate charged-particle measurements.","scenarios":["Alpha peak is broadened and shifted low","Beta rate changes with backing material","Counts vanish when the source is moved a few centimeters away","Window blocks nearly all events"],"choices":["Prepare a thinner, more uniform deposit.","Standardize backing and geometry.","Recognize the short alpha range in air.","Use an appropriately thin entrance window."],"mapping":[0,1,2,3]},"story":"Alpha particles deposit energy densely but travel only a short distance, while beta particles travel farther and are more sensitive to source thickness and backing material. A poorly prepared sample can absorb its own radiation and distort the count. The bomb program needs thin, reproducible samples so measured differences reflect nuclear composition rather than sample geometry."},{"day":18,"title":"Activation analysis","progress":"Describe irradiation, radioactive product formation, cooling time, counting, and decay correction.","takeaway":"Activation turns an otherwise hard-to-detect interaction into a delayed radioactive signature.","game":{"type":"Sequence","title":"One activation measurement","setup":"Order the activation-analysis workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Irradiate the sample under a characterized flux -> Allow a defined cooling interval -> Count the induced radiation with calibrated efficiency -> Correct for production and decay to infer the target quantity)","why":"Time history matters because the product is created and decays during the measurement sequence.","cards":["Irradiate the sample under a characterized flux","Allow a defined cooling interval","Count the induced radiation with calibrated efficiency","Correct for production and decay to infer the target quantity"],"order":[0,1,2,3]},"story":"Activation analysis exposes a material to neutrons and later measures the radiation from newly created radioactive nuclei. The observed signal depends on neutron flux, reaction probability, irradiation time, cooling time, decay, and detector efficiency. Los Alamos uses this chain of reasoning to infer material content and neutron exposure from measurements made after an experiment."},{"day":19,"title":"Signal-to-noise optimization","progress":"Trade detector area, shielding, energy window, timing window, and run duration.","takeaway":"The best improvement depends on whether the measurement is signal-limited or background-limited.","game":{"type":"Science Tank","title":"Improve a weak measurement","setup":"A weak line sits on substantial background.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 45 to B, 35 to C, 20 to A.","why":"Targeted background reduction can outperform raw area; longer running improves statistics as the square root of time.","proposals":[{"label":"A","text":"Double detector area, raising signal and background together"},{"label":"B","text":"Add targeted shielding and narrow the energy window"},{"label":"C","text":"Run four times longer with no other change"}],"research":"","recommended":{"B":45,"C":35,"A":20}},"story":"Signal-to-noise optimization is not simply making the signal larger; it is improving the ability to distinguish the desired effect from random fluctuations and systematic backgrounds. Shielding, geometry, timing windows, and detector choice can all help. With limited test opportunities, Los Alamos must design diagnostics that answer a clear question rather than merely produces impressive traces."},{"day":20,"title":"Saturation and dynamic range","progress":"Recognize clipping, pileup, amplifier saturation, digitizer range, and recovery time.","takeaway":"A flat-topped signal is usually an instrument warning, not a new law of physics.","game":{"type":"Protocol","columns":["What the trace shows","What it means"],"title":"Diagnose the clipped trace","setup":"Match each pattern to the likely dynamic-range failure.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"All large pulses have identical height -> Amplitude clipping; Two close pulses merge into one broad pulse -> Pulse pileup; Baseline remains displaced after a huge pulse -> Slow recovery or overload; Digitized values alternate between maximum and normal -> ADC saturation","why":"Saturation patterns identify which stage of the measurement chain has exceeded its range.","scenarios":["All large pulses have identical height","Two close pulses merge into one broad pulse","Baseline remains displaced after a huge pulse","Digitized values alternate between maximum and normal"],"choices":["Diagnose amplitude clipping when every large pulse reaches the same ceiling because the amplifier cannot represent a larger voltage.","Diagnose pulse pileup when two events arrive too close together and their signals merge into one broad or unusually large pulse.","Diagnose slow recovery or overload when a huge pulse shifts the baseline and the electronics take time to return to normal.","Diagnose analog-to-digital converter saturation when recorded values repeatedly hit the maximum digital code even though the analog signal continues to change."],"mapping":[0,1,2,3]},"story":"Every instrument has a finite dynamic range between signals too small to distinguish from noise and signals so large that the electronics saturate. Pulse pileup, clipping, and slow recovery can make a strong signal look deceptively simple. Bomb tests require overlapping high- and low-sensitivity channels so at least one instrument remains useful when the true signal differs from predictions."},{"day":21,"title":"Gain drift and environmental control","progress":"Connect temperature, high voltage, electronics, and reference peaks to long-term stability.","takeaway":"Stability is demonstrated through references and logs, not assumed from one successful calibration.","game":{"type":"Sequence","title":"Correct a drifting detector","setup":"Order a responsible drift response.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Confirm the shift with a stable reference source -> Check temperature, bias, and electronics logs -> Recalibrate or correct the gain model -> Verify the correction on independent reference data)","why":"Recalibration should follow diagnosis and should itself be verified.","cards":["Confirm the shift with a stable reference source","Check temperature, bias, and electronics logs","Recalibrate or correct the gain model","Verify the correction on independent reference data"],"order":[0,1,2,3]},"story":"Detector gain can drift as temperature, voltage, or electronics change, causing the same physical event to produce a different pulse size later. Reference pulses and environmental records reveal that drift. Los Alamos needs these checks because a changing instrument can otherwise be mistaken for changing nuclear behavior."},{"day":22,"title":"Redundancy and common-mode failure","progress":"Design independent diagnostics with different physical channels and failure modes.","takeaway":"Three copies of one instrument can still behave like one instrument.","game":{"type":"Science Tank","title":"Buy one more diagnostic","setup":"The current system relies on two detectors sharing the same clock and amplifier design.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 80 to B, 15 to A for capacity, 5 held; near-zero to C.","why":"Independence matters more than count when all channels share the same failure mode.","proposals":[{"label":"A","text":"A third identical detector on the same electronics"},{"label":"B","text":"A different detector type with an independent clock"},{"label":"C","text":"A larger display for the existing traces"}],"research":"","recommended":{"B":80,"A":15}},"story":"Redundant instruments help only when they do not share the same hidden failure. Two channels using one clock, one power supply, or one analysis assumption can agree and still be wrong. The bomb program therefore seeks independent diagnostics based on different physical principles so agreement carries real evidential weight."},{"day":11,"title":"Where the fragments go","place":"Diagnostics Bay","scene":"A nucleus at rest splits into two fragments, one heavy and one light. The team is arguing about which one carries more of the kinetic energy.","story":"A nucleus at rest splits into two fragments, one heavy and one light. The team is arguing about which one carries more of the kinetic energy.","takeaway":"Momentum conservation fixes the ratio of fragment speeds, and energy follows from it.","game":{"type":"CHOICE","title":"Where the fragments go","setup":"Diagnostics Bay","play":"A nucleus at rest splits into a heavy and a light fragment. Which carries more kinetic energy?","question":"A nucleus at rest splits into a heavy and a light fragment. Which carries more kinetic energy?","choices":["The lighter one: equal and opposite momenta give it the greater speed.","The heavier one: kinetic energy rises with the mass of the fragment.","They share it equally, since momentum is conserved in the split.","It cannot be decided without knowing the two binding energies."],"correctChoice":"The lighter one: equal and opposite momenta give it the greater speed.","answer":"The lighter one: equal and opposite momenta give it the greater speed.","why":"The nucleus was at rest, so total momentum is zero and the fragments leave with equal and opposite momentum: the lighter one moves faster in inverse proportion to its mass. Kinetic energy is momentum squared over twice the mass, so with momenta equal the energies go as one over mass — the lighter fragment takes the larger share. Both conservation laws are doing separate work here, which is the point: momentum fixes the speeds, and energy then follows from them.","rebuttals":["Kinetic energy at fixed momentum falls with mass rather than rising with it.","Equal momenta do not mean equal energies, because energy depends on momentum squared over mass.","The binding energies fix the total energy released, not how it divides between the fragments."]},"assumes":["momentum is conserved in an isolated system"]},{"day":24,"title":"Data acquisition architecture","progress":"Describe trigger, analog conditioning, digitization, buffering, metadata, and synchronization.","takeaway":"Data quality includes the record of how the data were produced.","game":{"type":"Sequence","title":"From sensor to analyzable event","setup":"Order the data-acquisition chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Condition and amplify the analog sensor output -> Apply a trigger or continuous sampling rule -> Digitize and timestamp the waveform -> Store data with configuration and calibration metadata)","why":"A waveform without configuration and timing metadata may be impossible to interpret later.","cards":["Condition and amplify the analog sensor output","Apply a trigger or continuous sampling rule","Digitize and timestamp the waveform","Store data with configuration and calibration metadata"],"order":[0,1,2,3]},"story":"A data-acquisition system carries a signal from sensor to amplifier, trigger, digitizer, timestamp, and recorded file. Each stage can change or lose information, and the configuration must be stored with the data. The bomb program’s fast experiments required the entire chain to work once, so end-to-end tests are as important as the detector itself."},{"day":25,"title":"High-speed imaging and radiography","progress":"Introduce frame rate, exposure, blur, line-of-sight integration, spatial resolution, and calibration at a high level.","takeaway":"Exposure time sets a direct spatial-blur limit for rapidly moving objects.","game":{"type":"Ballpark","title":"Motion blur scale","setup":"An object moves at 500 m/s during a 1 microsecond exposure.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"0.5 mm.","why":"Anything moving during the exposure travels a real distance. That distance is blur: speed times exposure time. Five hundred metres per second across one microsecond is half a millimetre. That is the resolution limit whatever the optics can do. Exposure time, viewing angle, penetration and timing together decide what an image can establish. Blur is the one nobody can argue with afterwards, because it is arithmetic rather than judgement.","givens":["Blur distance = speed x exposure time"],"task":"Estimate the blur distance.","relationship":"Motion blur = speed × exposure time. Multiply by 1,000 to turn metres into millimetres."},"story":"Everything worth seeing during an implosion happens inside an opaque assembly, in microseconds. These photographs are the evidence the design argument gets settled with.","assumes":["a photograph records everything that happened while the shutter was open"]},{"day":26,"title":"Instrumented non-nuclear tests","progress":"Design tests that isolate one physical uncertainty while preserving configuration control.","takeaway":"A small decisive test can be more valuable than a large ambiguous one.","game":{"type":"CHOICE","title":"Choose the next test","setup":"Three test concepts compete for one week of facility time.","play":"One week of facility time. Which test do you run?","answer":"A small test that cleanly separates the two competing timing hypotheses.","why":"A test earns its facility time by being able to come out either way and by changing what the programme does next. Work out, before firing, what each possible result would mean: if both hypotheses predict the same trace, the shot cannot discriminate and its cost buys nothing but reassurance. That is why the discriminating quantity is chosen first and the instrumentation designed around it, rather than instrumenting whatever is easy and hoping the record settles something. A result that both hypotheses predict is an expensive way of learning nothing, however large the shot was.","task":"One week of facility time. Which test do you run?","question":"One week of facility time. Which test do you run?","choices":["A small test that cleanly separates the two competing timing hypotheses.","A full-scale assembly shot, with the diagnostics that will fit around it.","A long series of repeat shots at one condition, for the statistics.","A repeat of last month’s test, whose configuration record was never written up."],"correctChoice":"A small test that cleanly separates the two competing timing hypotheses.","rebuttals":["A full assembly with limited diagnostics produces a spectacular record with too many possible causes to attribute anything to.","Repeating one condition measures the scatter at a point already known, and separates no hypothesis at all.","A repeat with no configuration record cannot be compared with the shot it is repeating, which is the only thing that would have made it useful."]},"story":"Three test concepts are competing for one week of facility time. A non-nuclear test uses inert or surrogate material to reproduce motion, timing and shock behaviour without a chain reaction.","assumes":["an experiment is worth what it can rule out"]},{"day":27,"title":"Field instrumentation","progress":"Account for shock, vibration, cable loss, electromagnetic interference, remote triggering, and inaccessible sensors.","takeaway":"A field instrument must survive, synchronize, and explain its own health.","game":{"type":"Protocol","columns":["The field problem","How you handle it"],"title":"Harden the field diagnostic","setup":"Match each field risk to the best mitigation.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Long analog cable degrades a fast pulse -> Digitize closer to the sensor or characterize cable response; Strong electromagnetic transient couples into wiring -> Use shielding, grounding, and differential transmission; Sensor cannot be accessed after installation -> Add remote health checks and redundant channels; Mechanical shock threatens connectors -> Use qualified connectors and strain relief","why":"Field measurement design begins with failure modes that do not exist on the laboratory bench.","scenarios":["Long analog cable degrades a fast pulse","Strong electromagnetic transient couples into wiring","Sensor cannot be accessed after installation","Mechanical shock threatens connectors"],"choices":["Digitize closer to the sensor or characterize cable response.","Use shielding, grounding, and differential transmission.","Add remote health checks and redundant channels.","Use qualified connectors and strain relief."],"mapping":[0,1,2,3]},"story":"Field instruments face vibration, long cables, weather, electromagnetic interference, uncertain power, and limited access. A detector that works on a laboratory bench may fail at a remote test site. Los Alamos must qualify complete field packages and plan backups because Trinity offers no convenient second attempt for a missing measurement."},{"day":28,"title":"Blind analysis and data integrity","progress":"Introduce preregistered cuts, blind regions, checksums, audit trails, and separation of calibration from inference.","takeaway":"Data integrity is both a technical and organizational property.","game":{"type":"Sequence","title":"Protect an analysis from bias","setup":"Order a simple blind-analysis workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Define selections and validation tests before viewing the answer-sensitive region -> Develop and tune using simulations, sidebands, or calibration data -> Freeze the analysis and document software versions -> Unblind, compute the result, and perform prespecified checks)","why":"Blinding prevents unconscious tuning toward a desired answer.","cards":["Define selections and validation tests before viewing the answer-sensitive region","Develop and tune using simulations, sidebands, or calibration data","Freeze the analysis and document software versions","Unblind, compute the result, and perform prespecified checks"],"order":[0,1,2,3]},"story":"Blind analysis hides selected information from analysts until methods and quality checks are fixed. The goal is to reduce the temptation to adjust choices until the result matches expectations. In a high-pressure bomb program, preserving data integrity helps distinguish genuine agreement with theory from unconscious tuning."},{"day":13,"title":"The plot that makes a decay a straight line","place":"Diagnostics Bay","scene":"Two counters have produced a table of count rate against time, and the notebook has it plotted on ordinary axes as a curve that nobody can read a number off.","story":"Two counters have produced a table of count rate against time, and the notebook has it plotted on ordinary axes as a curve that nobody can read a number off.","takeaway":"Plotting a logarithm turns an exponential into a straight line, and its slope is the decay constant.","game":{"type":"CHOICE","title":"The plot that makes a decay a straight line","setup":"Diagnostics Bay","play":"How should the count-rate data be plotted, and what does the plot then give you?","question":"How should the count-rate data be plotted, and what does the plot then give you?","choices":["Log of count rate against time: a straight line, whose slope is the decay constant.","Count rate against time: the curvature itself gives the half-life directly.","Log of count rate against log of time: a straight line for any decay process.","Count rate against the square of time, which straightens exponential data."],"correctChoice":"Log of count rate against time: a straight line, whose slope is the decay constant.","answer":"Log of count rate against time: a straight line, whose slope is the decay constant.","why":"An exponential plotted on linear axes is a curve, and a curve is hard to read and harder to check. Take the logarithm of the count rate and the same data is a straight line whose slope is minus the decay constant — so the half-life comes out of a ruler rather than a guess. It also makes the failures visible: a second component appears as a break in slope, and background appears as the line flattening onto a floor. Choosing the axes is part of the measurement.","rebuttals":["Curvature on linear axes is not readable in that way; two different processes look similar.","Log-log straightens power laws, not exponentials.","Squaring the time straightens nothing here; the relationship is exponential in time."]},"assumes":["a logarithm turns a constant ratio into a constant difference"]},{"day":30,"title":"Final diagnostic readiness review","progress":"Integrate calibration, statistics, timing, redundancy, field hardening, and analysis integrity into a release decision.","takeaway":"The final product is a trustworthy evidence system, not merely a collection of sensors.","game":{"type":"Sequence","title":"Release the diagnostic package","setup":"Order the final readiness chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Verify calibration and configuration records -> Run end-to-end timing and health checks -> Demonstrate independent coverage of critical observables -> Approve deployment with named residual risks and contingencies)","why":"Calibration and configuration records come first. An instrument nobody can describe afterwards produces data nobody can use. End-to-end timing and health checks then prove the chain works as a chain, rather than as a set of working parts. Independent coverage of the critical observables comes next — independent, so one failure does not take a whole answer with it. Deployment is approved with the residual risks named and a backup for each. Readiness means failures will be recognised, not that there are none.","cards":["Verify calibration and configuration records","Run end-to-end timing and health checks","Demonstrate independent coverage of critical observables","Approve deployment with named residual risks and contingencies"],"order":[0,1,2,3],"rebuttals":["Verify calibration and configuration records first. An instrument nobody can describe afterwards produces data nobody can use.","Run end-to-end timing and health checks second. Every part working is not the same as the chain working.","Demonstrate independent coverage of the critical observables third, so one failure does not take a whole answer with it.","Approve deployment with named residual risks and contingencies last. Readiness means failures will be recognised, not that there are none."]},"story":"The readiness review asks whether the instruments will actually record what happens. There is exactly one event to record, and a diagnostic that saturates produces nothing at all.","assumes":["an instrument can be working and still miss the event"]}],"CM":[{"day":1,"title":"Isotopes and chemical identity","progress":"Explain that isotopes share electron chemistry but differ in mass and nuclear properties.","takeaway":"Materials work must track both chemical form and isotopic composition.","game":{"type":"Protocol","columns":["What you want to know","What the physics says"],"title":"Separate chemical from nuclear information","setup":"Match each question to the relevant property.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Will two isotopes form similar chemical compounds? -> Yes: bonding is set by electron structure, which extra neutrons barely disturb.; Will they have the same half-life? -> No: stability is set inside the nucleus and can differ by orders of magnitude.; Can mass spectrometry distinguish them? -> Yes: sorting by mass-to-charge ratio responds to exactly the difference chemistry ignores.; Does atomic number determine the element? -> Yes: the proton count fixes the electron structure and therefore the chemical identity.","why":"Isotopes of an element carry the same proton count and nearly the same electrons. So they form the same compounds and answer to the same reagents. That is exactly why ordinary chemistry cannot tell them apart, or pull them apart. Nuclear stability is a different matter. It is set inside the nucleus, and half-lives can differ by a factor of a million between isotopes of one element. Mass spectrometry sorts by mass-to-charge ratio. That responds to the one difference chemistry ignores, which is why separation happens at Oak Ridge and costs what it costs.","scenarios":["Will two isotopes form similar chemical compounds?","Will they have the same half-life?","Can mass spectrometry distinguish them?","Does atomic number determine the element?"],"choices":["Yes: bonding is set by electron structure, which extra neutrons barely disturb.","No: stability is set inside the nucleus and can differ by orders of magnitude.","Yes: sorting by mass-to-charge ratio responds to exactly the difference chemistry ignores.","Yes: the proton count fixes the electron structure and therefore the chemical identity."],"mapping":[0,1,2,3],"rebuttals":["Two isotopes form similar compounds, because bonding is set by electron structure and extra neutrons barely disturb it.","They do not share a half-life. Stability lives inside the nucleus, and it can differ by orders of magnitude.","Mass spectrometry can separate them, because sorting by mass-to-charge responds to exactly the difference chemistry cannot see.","Atomic number does fix the element, because the proton count fixes the electron structure and the chemistry with it."]},"story":"Chemistry and Metallurgy is being asked what it can and cannot deliver, and the answer turns on one fact about isotopes. Everything shipped here has both a chemical form and an isotopic composition.","assumes":["chemical bonding is done by electrons"]},{"day":2,"title":"Radiochemical tracers","progress":"Use small radioactive tracers to follow yield, mixing, loss, and contamination.","takeaway":"A tracer turns invisible material loss into a measurable fraction.","game":{"type":"Ballpark","title":"Tracer recovery","setup":"A process begins with 5,000 tracer counts per minute and, once corrected for decay during the separation, recovers 4,000 counts per minute.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 80%.","why":"A tracer is a small amount of radioactive material that travels with the chemistry and reports where it went. That turns an invisible loss into a measurable fraction: yield is what came out over what went in. The correction that makes it honest is decay — the tracer has been decaying throughout the separation, so a raw count afterwards understates the recovery and flatters the loss. Both counts have to be corrected to the same moment before the ratio means anything.","givens":["Chemical yield = recovered signal / initial signal","The recovered count must be decay-corrected before it is compared"],"task":"Estimate the chemical yield.","relationship":"Yield = recovered ÷ started, as a percentage."},"story":"Chemistry and Metallurgy is running separations on quantities too small to weigh and needs to know how much is being lost. Every percent lost is weeks of production at Hanford.","assumes":["a radioactive sample announces itself through its own radiation"]},{"day":3,"title":"Mass balance","progress":"Apply conservation of matter across feed, product, recycle, waste, and sampled fractions.","takeaway":"Missing mass is often missing measurement or an undefined boundary.","game":{"type":"Sequence","title":"Close a material balance","setup":"Order the bookkeeping workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Define the system boundary and time interval -> Measure or estimate all incoming streams -> Measure product, waste, and inventory changes -> Compare inputs and outputs with uncertainty)","why":"A balance cannot close until the boundary and inventory change are defined.","cards":["Define the system boundary and time interval","Measure or estimate all incoming streams","Measure product, waste, and inventory changes","Compare inputs and outputs with uncertainty"],"order":[0,1,2,3]},"story":"Mass balance accounts for material entering, leaving, remaining, and being lost from a process. If the numbers do not close within uncertainty, material may be hidden in waste, equipment, samples, or measurement error. In the bomb program, careful balances protect scarce material and help detect contamination or procedural failures."},{"day":4,"title":"Oxidation states","progress":"Explain electron transfer, redox couples, complexation, and how oxidation state affects solubility and separation.","takeaway":"Separation chemistry is controlled manipulation of equilibrium, not magic filtration.","game":{"type":"Protocol","columns":["What you want to do","How you do it"],"title":"Choose the chemical control","setup":"Match each goal to the most direct chemical lever.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Change an ion’s oxidation state -> Add a redox reagent under monitored conditions; Keep a metal ion dissolved -> Add a suitable complexing ligand; Drive a sparingly soluble compound to precipitate -> Adjust chemistry to exceed solubility product; Prevent unwanted oxidation by air -> Use an inert atmosphere or reducing conditions","why":"Oxidation state and complexation often control where an element resides.","scenarios":["Change an ion’s oxidation state","Keep a metal ion dissolved","Drive a sparingly soluble compound to precipitate","Prevent unwanted oxidation by air"],"choices":["Add a redox reagent under monitored conditions.","Add a suitable complexing ligand.","Adjust chemistry to exceed solubility product.","Use an inert atmosphere or reducing conditions."],"mapping":[0,1,2,3]},"story":"An element can exist in several oxidation states, meaning it has lost or gained different numbers of electrons. Those states can change solubility, color, reactivity, and which chemical separation will work. Los Alamos chemists need control of oxidation state because a small chemical change can redirect valuable material into the wrong phase or waste stream."},{"day":5,"title":"Precipitation and solubility","progress":"Introduce solubility product, supersaturation, nucleation, coprecipitation, and washing.","takeaway":"A precipitate is both a chemical product and a potential collector of impurities.","game":{"type":"Sequence","title":"Run a clean precipitation","setup":"Order the procedure.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Adjust solution conditions to form the desired solid -> Allow nucleation and growth under controlled mixing -> Separate and wash the precipitate -> Measure yield and purity)","why":"Yield without washing and purity checks can preserve contaminants.","cards":["Adjust solution conditions to form the desired solid","Allow nucleation and growth under controlled mixing","Separate and wash the precipitate","Measure yield and purity"],"order":[0,1,2,3]},"story":"Precipitation turns dissolved ions into a solid when solution conditions make the solid less soluble. Temperature, acidity, concentration, mixing, and competing ions affect how completely and cleanly the material precipitates. The bomb program uses controlled precipitation to separate and purify materials, but must avoid trapping impurities inside the growing solid."},{"day":6,"title":"Solvent extraction","progress":"Explain distribution ratios, phase contact, mixing, settling, and multiple-stage extraction at a high level.","takeaway":"Several modest stages can outperform one imperfect separation.","game":{"type":"Ballpark","title":"One extraction stage","setup":"A solute has distribution ratio D=4 between organic and aqueous phases, with equal phase volumes.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 80%.","why":"4/(4+1)=0.8.","givens":["Fraction in organic phase = D/(D+1) for equal volumes"],"task":"Estimate the fraction extracted in one stage.","relationship":"Fraction extracted = D ÷ (D + phase-volume ratio), as a percentage."},"story":"Solvent extraction moves a dissolved species between two liquids that do not mix, such as an aqueous phase and an organic phase. Chemical conditions determine which phase the desired species prefers. Los Alamos uses repeated extraction stages to purify materials, so chemists must balance recovery against contamination carried along with the product."},{"day":7,"title":"Ion exchange","progress":"Describe resin sites, selectivity, loading, breakthrough, washing, and elution.","takeaway":"Breakthrough signals that the process is outrunning the resin capacity.","game":{"type":"Sequence","title":"Use an ion-exchange column","setup":"Order the column workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Condition the resin in the desired chemical form -> Load the sample below capacity -> Wash away weakly retained species -> Elute the target under changed conditions)","why":"Column selectivity is useful only when capacity and chemical form are controlled.","cards":["Condition the resin in the desired chemical form","Load the sample below capacity","Wash away weakly retained species","Elute the target under changed conditions"],"order":[0,1,2,3]},"story":"Ion exchange uses a solid resin whose charged sites selectively hold ions from a solution. Changing acidity or chemical composition can wash unwanted species away and later release the target. The method is valuable for separating small amounts of nuclear material, but resin capacity and incomplete washing can reduce yield or purity."},{"day":8,"title":"Analytical yield and purity","progress":"Distinguish recovery, chemical yield, radiochemical purity, isotopic purity, and measurement uncertainty.","takeaway":"Every materials report should state both quantity and quality.","game":{"type":"Diagnosis","pack":"cm8","title":"The batch that does not add up","setup":"You are reconciling a separation batch whose numbers do not close.","play":"Read the whole reading panel, including the calm readings, then select the one cause that fits all of it.","answer":"Target adsorbed onto the vessel walls","why":"Three different quantities are being confused. Chemical yield is the fraction of target material recovered. Radiochemical purity is the fraction of the measured activity that belongs to the species you wanted. Isotopic purity is the fraction of atoms of the right isotope. A batch can score well on one and badly on another, and each failure means something different upstream — so a yield figure is only as complete as the list of loss routes somebody actually measured. Material left on the vessel walls is not in any of the three numbers."},"story":"A separation batch has come back and the numbers do not close. Downstream, somebody is going to cast this material assuming the report meant what they thought it meant.","assumes":["a report can be accurate and still answer the wrong question"]},{"day":9,"title":"Contamination control","progress":"Explain zones, personal protective equipment, surface surveys, swipes, blanks, and clean-to-dirty workflow.","takeaway":"Contamination control protects both people and the validity of samples.","game":{"type":"Sequence","title":"Respond to possible contamination","setup":"Order the response.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Stop work and control access -> Survey people, tools, and surfaces -> Contain and decontaminate based on the survey -> Document clearance and corrective actions)","why":"Containment comes before cleanup, and clearance requires measurement.","cards":["Stop work and control access","Survey people, tools, and surfaces","Contain and decontaminate based on the survey","Document clearance and corrective actions"],"order":[0,1,2,3]},"story":"Radioactive contamination can spread invisibly through dust, liquids, tools, clothing, and airflow. The first task is to stop movement, survey where the material went, and contain it before cleanup. In the bomb program, contamination control protects workers and prevents small traces from corrupting precision measurements or material accounts."},{"day":10,"title":"Gloveboxes and atmospheres","progress":"Describe confinement, pressure control, filtration, inert atmospheres, transfer ports, and monitoring.","takeaway":"Confinement protects the room; atmosphere control protects the material.","game":{"type":"Protocol","columns":["What you want to do","How you do it"],"title":"Choose the enclosure feature","setup":"Match each risk to the appropriate feature.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Prevent airborne material from escaping -> Negative pressure with filtered exhaust. Air leaks inward rather than outward, so even a breach moves contamination the safe way.; Prevent oxygen or moisture reaction -> An inert atmosphere. Removes the reactant instead of containing the product.; Move items without opening the main enclosure -> A transfer lock or bag-out port. Holds the pressure boundary during transfer, which is when confinement is most often lost.; Detect loss of confinement -> Pressure indicators and contamination monitors. Confinement can fail silently, so the boundary needs an instrument watching it.","why":"A glovebox is a controlled system of confinement, atmosphere, transfer, and monitoring.","scenarios":["Prevent airborne material from escaping","Prevent oxygen or moisture reaction","Move items without opening the main enclosure","Detect loss of confinement"],"choices":["Negative pressure with filtered exhaust. Air leaks inward rather than outward, so even a breach moves contamination the safe way.","An inert atmosphere. Removes the reactant instead of containing the product.","A transfer lock or bag-out port. Holds the pressure boundary during transfer, which is when confinement is most often lost.","Pressure indicators and contamination monitors. Confinement can fail silently, so the boundary needs an instrument watching it."],"mapping":[0,1,2,3]},"story":"A glovebox is a sealed workspace that lets operators handle hazardous material through fixed gloves while controlling air pressure and atmosphere. Negative pressure keeps contamination from escaping, while an inert gas can keep reactive material away from oxygen or moisture. Los Alamos needs both kinds of control for materials that are radioactive, chemically reactive, or scarce."},{"day":11,"title":"Corrosion and compatibility","progress":"Introduce galvanic effects, oxidation, moisture, stress corrosion, and material compatibility.","takeaway":"Compatibility must be demonstrated under the chemical, thermal, and mechanical conditions of use.","game":{"type":"Science Tank","title":"Fund a compatibility campaign","setup":"A new process fluid contacts several metals and seals.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 35 to A, 60 to C, 5 held; none to B.","why":"Screening identifies candidates; representative long tests reveal slow or stress-assisted failure.","proposals":[{"label":"A","text":"Short coupon tests across candidate materials"},{"label":"B","text":"Use the cheapest material and wait for failure"},{"label":"C","text":"Longer exposure tests including temperature and stress"}],"research":"","recommended":{"A":35,"C":60}},"story":"Corrosion is a chemical or electrochemical reaction that changes a material at its surface. A metal may attack another metal, react with moisture, or form brittle products that weaken an interface. Because bomb components must fit and remain reliable during storage and transport, Los Alamos needs compatibility tests for every material combination and environment."},{"day":12,"title":"Phase diagrams","progress":"Read composition-temperature phase diagrams, identify phase fields, and understand why processing history affects final structure.","takeaway":"Composition and temperature jointly determine which phases are possible.","game":{"type":"Diagnosis","pack":"cm12","title":"A phase that should not be there","setup":"You are explaining a microstructure the phase diagram does not predict.","play":"Read the whole reading panel, including the calm readings, then select the one cause that fits all of it.","answer":"A trace impurity stabilised an extra phase","why":"A phase diagram maps which solid and liquid phases are stable at each temperature and composition. Crossing a boundary can melt a material, throw out a second phase, or change how it behaves under load. Plutonium is notorious for it. Several solid phases, and large volume changes between them. But a diagram describes one composition. So before doubting the map, check you still have the material it was drawn for. A trace impurity is enough to hold open a phase that should not be there."},"story":"A metallurgist has a microstructure under the microscope that the phase diagram says should not be there. Everything the laboratory does with this metal is an argument with a diagram drawn from very little data.","assumes":["a metal can exist in more than one solid form"]},{"day":13,"title":"Allotropy and polymorphism","progress":"Explain that one element can have multiple crystal structures with different density and properties.","takeaway":"Structure is a material variable alongside composition.","game":{"type":"Sequence","title":"Track a phase transformation","setup":"Order a generic transformation analysis.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Identify the initial crystal structure and temperature -> Cross a transformation boundary -> Nucleate and grow the new structure -> Measure resulting dimensions and properties)","why":"A phase change can alter dimensions and mechanical behavior even without changing composition.","cards":["Identify the initial crystal structure and temperature","Cross a transformation boundary","Nucleate and grow the new structure","Measure the dimension and property changes the transformation produces"],"order":[0,1,2,3]},"story":"Allotropy or polymorphism means one material can adopt different crystal structures. A transformation between structures may change density, volume, and mechanical behavior even though the chemical composition stays the same. This is critical for plutonium metallurgy because temperature history can alter the shape and properties of a component intended for precise assembly."},{"day":14,"title":"Solidification and casting","progress":"Describe nucleation, grain growth, shrinkage, porosity, segregation, and cooling-rate effects without operational component recipes.","takeaway":"A visually smooth casting can still contain internal porosity or segregation.","game":{"type":"Sequence","title":"Analyze a casting defect","setup":"Order the causal chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Molten material begins to solidify at the mold wall -> Grains grow and solute redistributes -> Volume contraction and trapped gas create defect risks -> Inspection links defects to cooling and feed conditions)","why":"Casting quality is a history of heat flow, phase change, and material transport.","cards":["Molten material begins to solidify at the mold wall","Grains grow and solute redistributes","Volume contraction and trapped gas create defect risks","Inspection links defects to cooling and feed conditions"],"order":[0,1,2,3]},"story":"During casting, solidification begins at cool surfaces and advances inward. Grain growth, shrinkage, trapped gas, and uneven cooling can create voids or distorted regions. Los Alamos must connect casting conditions to internal defects because an apparently smooth component can contain hidden flaws that affect machining or implosion symmetry."},{"day":15,"title":"Density measurement","progress":"Compare geometric, displacement, pycnometric, and radiographic density methods.","takeaway":"Density measurements can reveal voids, phase changes, or composition differences.","game":{"type":"Ballpark","title":"Density from mass and volume","setup":"A sample has mass 250 g and measured volume 20 cm^3.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"12.5 g/cm^3.","why":"250/20=12.5.","givens":["Density = mass/volume"],"task":"Estimate the density.","relationship":"Density = mass ÷ volume."},"story":"Density is mass divided by volume, but measuring either quantity becomes difficult for small, irregular, reactive, or radioactive samples. A density change can signal porosity, phase transformation, or composition differences. For an implosion weapon, density matters because it affects both neutron behavior and how the material responded to compression."},{"day":16,"title":"Thermal properties","progress":"Introduce heat capacity, thermal conductivity, expansion, diffusivity, and thermal cycling.","takeaway":"Small expansion coefficients can create meaningful dimensional changes over large temperature swings.","game":{"type":"Ballpark","title":"Thermal expansion scale","setup":"A 100 mm component has expansion coefficient 15 x 10^-6 per kelvin and warms by 100 K.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"About 0.15 mm.","why":"15 x 10^-6 x 0.10 x 100=1.5 x 10^-4 m.","givens":["Delta L = alpha L Delta T"],"task":"Estimate the length change in millimetres.","relationship":"Length change = expansion coefficient × original length × temperature change."},"story":"Thermal expansion, heat capacity, and thermal conductivity describe how a material changes size, stores heat, and spreads temperature. Temperature differences during fabrication or storage can create stress and misalignment. Los Alamos engineers need these properties to keep precisely fitted components within tolerance and to predict how materials behaved during rapid heating."},{"day":17,"title":"Mechanical properties","progress":"Define elastic modulus, yield strength, ductility, hardness, toughness, and creep.","takeaway":"Strength, stiffness, hardness, and toughness should not be treated as synonyms.","game":{"type":"Diagnosis","pack":"cm17","title":"The part that broke without bending","setup":"You are running the failure analysis on a component that broke in service.","play":"Read the whole reading panel, including the calm readings, then select the one cause that fits all of it.","answer":"Machining damaged the surface layer","why":"Four properties are involved and they are not synonyms. Elastic modulus is stiffness — how much it deflects under load. Yield strength is where permanent deformation begins. Hardness is resistance to indentation. Toughness is how much energy the material absorbs before it fractures. A material can be hard and brittle, or soft and very tough, so choosing the wrong one of these as 'strong' is how a part that passed every specification arrives cracked. A part is only as good as the property nobody inspected."},"story":"A component has failed in service and the failure analysis has landed on your bench. This programme cannot spare either the material or the weeks.","assumes":["a material can be strong in one sense and weak in another"]},{"day":18,"title":"Crystal defects","progress":"Introduce vacancies, dislocations, grain boundaries, impurities, and their effects on diffusion and strength.","takeaway":"Many material properties are controlled by defects rather than the perfect crystal.","game":{"type":"Sequence","title":"From processing to strength","setup":"Order a generic strengthening chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Processing changes grain size or defect density -> Dislocation motion becomes easier or harder -> Yield behavior changes -> Mechanical testing verifies the effect)","why":"Microstructure changes properties by changing how defects move.","cards":["Processing changes grain size or defect density","Dislocation motion becomes easier or harder","Yield behavior changes","Mechanical testing verifies the effect"],"order":[0,1,2,3]},"story":"Crystals contain defects such as dislocations, vacancies, and grain boundaries. Processing changes how easily those defects move, which changes strength and ductility. Los Alamos uses mechanical tests and microscopy to connect heat treatment and fabrication history to the reliability of nuclear and high-explosive components."},{"day":19,"title":"Heat treatment","progress":"Explain annealing, recovery, recrystallization, phase transformation, and quenching at a high level.","takeaway":"Heat treatment is a reproducible path through temperature and time, not a single temperature setting.","game":{"type":"Science Tank","title":"Choose a heat-treatment study","setup":"A material shows inconsistent hardness after fabrication.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 45 to A, 50 to C, 5 held; none to B.","why":"A controlled process map connects thermal history, microstructure, and properties.","proposals":[{"label":"A","text":"Run controlled heat-treatment coupons that map how time and temperature change the metal’s microscopic structure."},{"label":"B","text":"Heat the material without a planned schedule and judge success only by whether hardness rises."},{"label":"C","text":"Test small samples with several controlled cooling rates, then compare hardness, strength, and microstructure."}],"research":"","recommended":{"A":45,"C":50}},"story":"Heat treatment changes a material’s microscopic structure by controlling temperature and time, then cooling at a chosen rate. The same composition can become harder, softer, stronger, or more brittle depending on that history. The bomb program needs controlled coupons and records rather than arbitrary heating because reproducible properties are essential for assembly and shock response."},{"day":20,"title":"Machining and surface integrity","progress":"Discuss cutting forces, heat, residual stress, contamination, burrs, and inspection without giving component-production instructions.","takeaway":"A dimension can be correct while the surface or contamination state is unacceptable.","game":{"type":"Protocol","columns":["What can go wrong","How you control it"],"title":"Protect surface integrity","setup":"Match each machining risk to a control.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Tool wear changes dimensions -> Monitor tool life and re-check dimensions. Wear is gradual, so parts drift out of tolerance with no single obvious failure.; Cutting heat alters the surface -> Control speed, feed, and cooling under a qualified process. A part can be dimensionally perfect and still carry a damaged or transformed surface layer.; Coolant contaminates the material -> Use approved coolant and verify post-machining cleaning. The residue is chemical, so no dimensional inspection will find it.; Burrs interfere with fit -> Deburr and inspect edges. A raised fragment is small enough to pass a dimensional check yet still prevent assembly or break loose later.","why":"Machining quality includes chemistry, stress, cleanliness, and geometry.","scenarios":["Tool wear changes dimensions","Cutting heat alters the surface","Coolant contaminates the material","Burrs interfere with fit"],"choices":["Monitor tool life and re-check dimensions. Wear is gradual, so parts drift out of tolerance with no single obvious failure.","Control speed, feed, and cooling under a qualified process. A part can be dimensionally perfect and still carry a damaged or transformed surface layer.","Use approved coolant and verify post-machining cleaning. The residue is chemical, so no dimensional inspection will find it.","Deburr and inspect edges. A raised fragment is small enough to pass a dimensional check yet still prevent assembly or break loose later."],"mapping":[0,1,2,3]},"story":"Machining creates the final dimensions and surface of a component, but cutting forces, heat, tool wear, coolant, and burrs can damage the material. A part can meet a simple diameter measurement while still carrying surface cracks or contamination. Los Alamos therefore treats machining as a controlled materials process, not merely shaping metal."},{"day":21,"title":"Nondestructive evaluation","progress":"Compare visual, ultrasonic, radiographic, eddy-current, dye-penetrant, and dimensional inspection.","takeaway":"No single nondestructive test sees every defect.","game":{"type":"Protocol","columns":["What you need to find","Which method finds it"],"title":"Choose the inspection method","setup":"Match each defect to a likely method.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Surface-breaking crack on a nonporous part -> Dye penetrant. Liquid wicks in and bleeds back out under developer, so the flaw must reach the surface and the surface must not absorb the dye.; Internal void in a thick object -> Radiography or ultrasound. Both send energy through the bulk, reaching flaws no surface method can see.; Subsurface flaw in a conductive material -> Eddy-current testing. Induced currents are perturbed by a flaw just below the surface, but only in metals.; Overall dimensional distortion -> Dimensional metrology. Nothing is cracked or hollow, so what is measured is geometry against the drawing.","why":"Inspection method must match defect location, material, and required resolution.","scenarios":["Surface-breaking crack on a nonporous part","Internal void in a thick object","Subsurface flaw in a conductive material","Overall dimensional distortion"],"choices":["Dye penetrant. Liquid wicks in and bleeds back out under developer, so the flaw must reach the surface and the surface must not absorb the dye.","Radiography or ultrasound. Both send energy through the bulk, reaching flaws no surface method can see.","Eddy-current testing. Induced currents are perturbed by a flaw just below the surface, but only in metals.","Dimensional metrology. Nothing is cracked or hollow, so what is measured is geometry against the drawing."],"mapping":[0,1,2,3]},"story":"Nondestructive evaluation looks for flaws without cutting apart the finished component. Surface inspection, dye penetrant, ultrasound, radiography, and eddy currents reveal different kinds and depths of defects. Since bomb components are scarce and often cannot be sacrificed for testing, the program needs multiple inspection methods matched to the flaw being sought."},{"day":22,"title":"Assay and inventory","progress":"Introduce destructive assay, nondestructive assay, calibration standards, material balance, and uncertainty.","takeaway":"An inventory difference is a question requiring uncertainty analysis, not automatic evidence of loss.","game":{"type":"Ballpark","title":"Inventory difference","setup":"A process begins with 100.0 units of material and reports 97.5 units in product plus 1.5 units in measured waste.","play":"Use the supplied values, show the governing relationship, and give a sensible rounded result.","answer":"1.0 unit.","why":"100.0 - 97.5 - 1.5=1.0.","givens":["Unaccounted inventory = input - known outputs"],"task":"Estimate the unaccounted amount.","relationship":"Mass balance: what is unaccounted for = what went in − product − waste."},"story":"Assay measures how much nuclear material is present, while inventory records where it is and who is responsible for it. Measurements have uncertainty, and transfers must preserve identity. Los Alamos needs assay and inventory together because losing track of material is both a scientific problem and a severe safety and security failure."},{"day":23,"title":"Sample preparation and self-absorption","progress":"Explain why thickness, uniformity, matrix, and geometry affect alpha, beta, gamma, and mass-spectrometric measurements.","takeaway":"Analytical accuracy can be lost before the sample reaches the instrument.","game":{"type":"Sequence","title":"Prepare a representative analytical sample","setup":"Order the workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Define the measurement and required sample form -> Homogenize or subsample with contamination controls -> Prepare thickness and geometry consistently -> Measure standards, blanks, and the sample)","why":"The sample must represent the bulk and be compatible with the measurement physics.","cards":["Define the measurement and required sample form","Homogenize or subsample with contamination controls","Prepare thickness and geometry consistently","Measure standards, blanks, and the sample"],"order":[0,1,2,3]},"story":"A thick radioactive sample can absorb some of its own emitted particles before they reach the detector, a problem called self-absorption. Sample thickness, uniformity, and geometry therefore change the measured count. The bomb program needs standardized preparation, blanks, and reference standards so analytical results reflect composition rather than sample shape."},{"day":24,"title":"Chemical process safety","progress":"Cover incompatible chemicals, heat release, gas generation, pressure, remote handling, and stop-work criteria.","takeaway":"A chemically successful reaction can still be an unsafe process.","game":{"type":"Protocol","columns":["The hazard","How you control it"],"title":"Control a reactive process","setup":"Match each hazard to a primary control.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Unexpected heat release -> Monitor temperature, add reagent slowly, and keep a shutdown path ready, so the rate of energy release stays bounded.; Gas generation in a closed vessel -> Provide relief and a vent path, because otherwise the pressure has nowhere to go and the vessel becomes the failure point.; Unknown chemical compatibility -> Test at small scale first, so anything unexpected is small enough to contain.; Loss of ventilation -> Stop work and restore confinement, because the control that was keeping vapour out of the room is gone.","why":"Process safety controls the rate and consequence of energy and material release.","scenarios":["Unexpected heat release","Gas generation in a closed vessel","Unknown chemical compatibility","Loss of ventilation"],"choices":["Monitor temperature, add reagent slowly, and keep a shutdown path ready, so the rate of energy release stays bounded.","Provide relief and a vent path, because otherwise the pressure has nowhere to go and the vessel becomes the failure point.","Test at small scale first, so anything unexpected is small enough to contain.","Stop work and restore confinement, because the control that was keeping vapour out of the room is gone."],"mapping":[0,1,2,3]},"story":"Chemical processes can release heat, generate gas, build pressure, or combine incompatible materials. Small-scale compatibility tests, controlled addition, ventilation, and emergency shutdowns reveal and limit those hazards. Los Alamos must develop processes quickly without allowing schedule pressure to replace basic chemical safety."},{"day":25,"title":"Waste and environmental control","progress":"Explain segregation, characterization, minimization, treatment, storage, and traceability.","takeaway":"Environmental responsibility is part of the process design, not a final cleanup step.","game":{"type":"Sequence","title":"Manage a waste stream","setup":"Order the responsible workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"2 -> 3 -> 4 -> 5 (Characterize the waste and hazards -> Segregate incompatible or different regulatory categories -> Minimize, treat, or stabilize through an approved process -> Label, store, and document transfer or disposal)","why":"Waste management begins with characterization and compatibility.","cards":["Characterize the waste and hazards","Segregate incompatible or different regulatory categories","Minimize, treat, or stabilize through an approved process","Label, store, and document transfer or disposal"],"order":[0,1,2,3]},"story":"Radioactive and chemical wastes remain hazardous after the useful material has been removed. Different wastes may react with one another or require different containment, treatment, and records. The bomb program’s environmental legacy begins with these routine choices about segregation, storage, and disposal, not only with the final weapon."},{"day":26,"title":"Batch variability","progress":"Use control charts, replicate samples, process records, and designed experiments to find sources of variation.","takeaway":"Quality improves fastest when variation is traced to controllable process variables.","game":{"type":"Science Tank","title":"Reduce batch scatter","setup":"Three interventions compete for 100 credits.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 35 to B, 55 to C, 10 to A.","why":"Inspection catches failures; process measurement and controlled experiments explain and prevent them.","proposals":[{"label":"A","text":"Rely on more end-of-line inspection without measuring which process variable caused the batch difference."},{"label":"B","text":"Measure temperature, composition, and timing during each run so batch differences can be traced to process history."},{"label":"C","text":"Vary the suspected process controls systematically so their separate effects and interactions can be measured."}],"research":"","recommended":{"B":35,"C":55,"A":10}},"story":"Two batches produced by the same written process can differ because temperature, composition, mixing, timing, or equipment drifts. Final inspection may find the difference but does not reveal its cause. Los Alamos needs process measurements and designed experiments to learn which variables controlled material properties and to make production reproducible."},{"day":27,"title":"Acceptance criteria","progress":"Distinguish specification limits, measurement uncertainty, guard bands, and disposition of borderline parts.","takeaway":"Acceptance criteria need explicit rules for uncertainty and borderline results.","game":{"type":"Ballpark","title":"Guard-band decision","setup":"A property must be at least 100 units. The measurement is 102 with uncertainty +/-3 units.","play":"Estimate the conservative lower bound of the measurement.","answer":"About 99 units, which is below the 100-unit threshold, so it is not an unambiguous pass.","why":"An acceptance criterion turns good material into something testable. A limit, a method, and a stated uncertainty. Results near the boundary are exactly why the rule has to say what to do about that uncertainty. Agreed in advance, rather than argued over once the number is on the table. The low end of this measurement is ninety-nine, which is under the limit. So the result is not a clean pass, whatever the middle of it says. A rule that reads only the central value is a rule that fails at the boundary.","givens":["The lower plausible value is about 99"],"task":"Estimate the conservative lower bound of the measurement.","relationship":"The lower bound of a result = the measured value − its uncertainty. Compare that against the threshold, not the central value."},"story":"A property has to be at least a hundred units and the measurement reads a hundred and two, plus or minus three. Material this scarce cannot be scrapped casually, or accepted on hope.","assumes":["a measurement has a range, not just a value"]},{"day":28,"title":"Chain of custody and records","progress":"Track sample identity, transfers, processing history, analytical results, revisions, and approvals.","takeaway":"A technically good result without provenance may be unusable.","game":{"type":"Protocol","columns":["The gap in the record","How you close it"],"title":"Repair the record trail","setup":"Match each record problem to the corrective action.","play":"Match each information need or situation to the best action, instrument, or control. Each option is used once.","answer":"Sample label detached -> Quarantine and reconcile identity using independent evidence; Result file lacks calibration version -> Link the calibration and software record; Transfer occurred without signature -> Document custody gap and investigate; Process sheet was revised after the run -> Preserve both versions and explain the revision","why":"Traceability requires contemporaneous identity, configuration, and approval records.","scenarios":["Sample label detached","Result file lacks calibration version","Transfer occurred without signature","Process sheet was revised after the run"],"choices":["Quarantine the sample and reconstruct its identity from independent records before using any result linked to it.","Link the result file to the exact calibration and software version so another analyst can reproduce how the number was obtained.","Document and investigate the custody gap because an unsigned transfer leaves uncertainty about who controlled the material.","Preserve both process-sheet versions and explain the later revision so the record does not falsely imply the newer procedure was used during the run."],"mapping":[0,1,2,3]},"story":"Chain of custody records who handled a sample or component, when it moved, and whether its identity remained secure. Technical records connect that identity to processing, inspection, and test results. Los Alamos needs this traceability because a perfect measurement is useless if no one can prove which part or batch it describes."},{"day":14,"title":"Why separation is a physical problem","place":"Chemistry and Metallurgy Building","scene":"A request has come in for a chemical route to separate uranium-235 from uranium-238, on the grounds that the chemists separate everything else.","story":"A request has come in for a chemical route to separate uranium-235 from uranium-238, on the grounds that the chemists separate everything else.","takeaway":"Isotopes of an element are chemically alike, so separating them means exploiting a mass difference.","game":{"type":"CHOICE","title":"Why separation is a physical problem","setup":"Chemistry and Metallurgy Building","play":"Why can the chemists not separate uranium-235 from uranium-238?","question":"Why can the chemists not separate uranium-235 from uranium-238?","choices":["The two isotopes have the same electron structure, so every chemical method treats them identically; only their mass differs.","The chemistry differs only slightly, so the process would simply take longer.","Uranium is too dense for solution chemistry to work at all.","They can be separated chemically; the difficulty is the radioactivity."],"correctChoice":"The two isotopes have the same electron structure, so every chemical method treats them identically; only their mass differs.","answer":"The two isotopes have the same electron structure, so every chemical method treats them identically; only their mass differs.","why":"Chemical behaviour is decided by electrons, and the two isotopes have the same number of them in the same arrangement — so a chemical process cannot prefer one. What differs is mass, by about one part in 235, and every enrichment method exploits that: diffusion rates through a barrier, deflection in a magnetic field, centrifugal separation. That factor of 1.004 in the physics is why enrichment plants are the size of towns while the chemistry of uranium fits in a beaker.","rebuttals":["It is not a matter of degree. A chemical route has no property to select on at all.","Density is irrelevant; both isotopes have essentially the same chemistry in solution.","Radioactivity is a hazard to manage, not the reason chemical separation fails."]},"assumes":["chemical behaviour is set by electrons, and isotopes differ only in the nucleus"]},{"day":30,"title":"Final chemistry and metallurgy dossier","progress":"Synthesize separation chemistry, contamination control, phase behavior, fabrication, assay, and quality assurance.","takeaway":"The final materials capability joins chemistry, structure, properties, and traceability.","game":{"type":"CHOICE","title":"Final laboratory investment","setup":"The division has one final 100-credit improvement budget.","play":"One last improvement to the division’s materials capability. Which?","answer":"Traceable records linking each batch’s process conditions to its measured properties.","why":"A measurement says what one batch was on one day. A record that links process conditions to measured properties says what the process does. That is a different claim, and a more durable one. It is also the only form that lets somebody a year from now diagnose a batch that came out different — and this metal has several solid phases and very little data behind its diagram.","task":"One last improvement to the division’s materials capability. Which?","question":"One last improvement to the division’s materials capability. Which?","choices":["Traceable records linking each batch’s process conditions to its measured properties.","Independent composition measurements and microscopy on every batch.","Re-measurement of the batches already released, to a tighter tolerance.","Higher production throughput, with the measurements and records unchanged."],"correctChoice":"Traceable records linking each batch’s process conditions to its measured properties.","rebuttals":["Independent composition and microscopy verify a batch and are already required. They produce more measurements with nothing connecting them.","Re-measuring released material improves numbers on parts that are already installed and links none of them to how they were made.","More throughput on the same records makes more material that nobody can characterise afterwards."]},"story":"The final dossier has to show more than that components existed. The division has one last hundred credits of improvement to spend, and the choice says what it thinks a materials capability is.","assumes":["somebody will read this after everyone who made it has gone"]}],"E":[{"day":1,"title":"Two weapon architectures at Los Alamos","progress":"Compare the gun-type and implosion concepts as engineering systems, including their different demands on material, timing, testing, and packaging.","takeaway":"Weapon architecture determines the entire downstream engineering program.","game":{"type":"Protocol","columns":["What the engineers are looking at","What they decide"],"title":"Two weapon architectures at Los Alamos","setup":"Oppenheimer asks the Ordnance Division to classify the program consequences of the two early weapon concepts without using design dimensions.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"A design relies on bringing two separated pieces together along one axis. -> Gun-type architecture; A design relies on a converging wave that must preserve three-dimensional symmetry. -> Implosion architecture; A concept is comparatively straightforward to reason about but becomes unsuitable for reactor-produced plutonium. -> Gun-type program consequence; A concept demands a large diagnostic and high-explosive development program. -> Implosion program consequence","why":"Both concepts aim at the same goal. Bring subcritical material together fast enough that a chain reaction can grow before the assembly blows itself apart. They get there by completely different routes. A gun-type device drives one piece into another along one axis. That is a linear problem with a long history behind it. Implosion squeezes one piece inward with a converging wave, and nobody has built one. The two are not merely different shapes. They create different organisations, different test programmes and different risks.","scenarios":["Engineers sketch a long device in which one subcritical piece would be driven into another along a single axis.","Engineers sketch a compact device in which explosive waves would squeeze the material inward from every direction.","Plutonium measurements show that a slower assembly could be interrupted by a stray neutron before full assembly.","The alternative requires synchronized detonators, wave-shaping explosives, and repeated hydrodynamic tests before a nuclear trial."],"choices":["Use the gun-type concept: bring two separated subcritical pieces together rapidly along one line.","Use the implosion concept: compress one piece inward with a nearly spherical converging pressure wave.","Reject the plutonium gun program because its slower assembly leaves too much time for pre-initiation.","Build an implosion-development program focused on timing, symmetry, diagnostics, and reproducible explosive components."],"mapping":[0,1,2,3],"rebuttals":["A long device driving one subcritical piece into another along a single axis is the gun-type architecture. One dimension, and a well-understood one.","A compact device squeezing the material inward from every direction is implosion. The difficulty is that it has to work in three dimensions at once.","Plutonium measurements showing that a slow assembly can be interrupted early are what make the plutonium gun unusable, whatever its engineering merits.","Synchronised detonators, wave-shaping explosives and repeated hydrodynamic tests are the programme implosion demands. That is an organisation, not a drawing."]},"story":"Oppenheimer has asked Ordnance to lay out the programme consequences of the two assembly concepts, without discussing any design dimensions. The choice decides which divisions grow and what the site does for two years.","assumes":["a chain reaction needs the material held together long enough to grow"]},{"day":2,"title":"Why Thin Man was abandoned","progress":"Trace how measurements of reactor-produced plutonium forced Los Alamos away from the plutonium gun concept and toward Fat Man.","takeaway":"In complex engineering, one new measurement can invalidate an entire development path.","game":{"type":"Sequence","title":"Why Thin Man was abandoned","setup":"Order the historical reasoning that turned an unexpected material result into a program-wide redesign.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Measure an unexpectedly high spontaneous-neutron background in reactor-produced plutonium. -> Recognize that a slow assembly could begin reacting before the intended configuration was reached. -> Conclude that the plutonium gun concept carried an unacceptable pre-initiation risk. -> Concentrate the plutonium effort on the faster implosion approach that became Fat Man.)","why":"This is what a measurement invalidating a development path looks like from inside: not a debate about opinion, but a chain from one new fact to a decision that costs a year. The unexpectedly high spontaneous-neutron background in reactor plutonium comes first, because it is the new evidence. That makes a slow assembly vulnerable to starting early. That vulnerability makes the plutonium gun unacceptable. And only then does the effort move to implosion, which is a decision rather than a fact.","cards":["Measure an unexpectedly high spontaneous-neutron background in reactor-produced plutonium.","Recognize that a slow assembly could begin reacting before the intended configuration was reached.","Conclude that the plutonium gun concept carried an unacceptable pre-initiation risk.","Concentrate the plutonium effort on the faster implosion approach that became Fat Man."],"order":[0,1,2,3],"rebuttals":["The unexpected spontaneous-neutron measurement comes first. It is the only new fact in the chain; everything after it is inference or decision.","Recognising that a slow assembly could begin reacting early is the inference from that fact — the step from a material property to a timing problem.","Concluding the plutonium gun carried unacceptable pre-initiation risk is the verdict on the concept, and it needs the two steps above it.","Concentrating the plutonium effort on implosion is the decision, and it is last. A programme reorganises after the conclusion, not before it."]},"story":"Thin Man was the plutonium gun design and much of the site's effort was pointed at it. Then the counters returned a number the concept could not survive, and within weeks the laboratory reorganised.","assumes":["a measurement can rule out a design without anybody being wrong"]},{"day":3,"title":"Translate Fat Man into engineering requirements","progress":"Convert the broad goal of an air-deliverable plutonium implosion weapon into traceable requirements for packaging, interfaces, safety, and verification.","takeaway":"A requirement becomes useful only when its owner and verification method are clear.","game":{"type":"Protocol","columns":["What the statement demands","Which kind of requirement that is"],"title":"Translate Fat Man into engineering requirements","setup":"Match each Fat Man program question to the requirement category it belongs to.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"The complete system must fit and function in the modified delivery aircraft. -> An aircraft-integration requirement. It binds mass, balance, clearance, connections, and release, and it is verified by fit checks against the actual airframe.; The firing system must not become enabled during normal handling. -> A safety-and-arming requirement. Written as several conditions that must all hold, so no single failure can enable the chain.; The high-explosive assembly, electrical unit, and diagnostic ports must agree on controlled interfaces. -> An interface-control requirement. It fixes one approved set of dimensions and connections so independently built parts still mate.; A claim about reliability must be backed by inspection, test, or rehearsal evidence. -> A verification requirement. It names the inspection, test, or rehearsal that turns a claim into a record.","why":"Fat Man was a system of interacting subsystems, not a single physics package.","scenarios":["The complete system must fit and function in the modified delivery aircraft.","The firing system must not become enabled during normal handling.","The high-explosive assembly, electrical unit, and diagnostic ports must agree on controlled interfaces.","A claim about reliability must be backed by inspection, test, or rehearsal evidence."],"choices":["An aircraft-integration requirement. It binds mass, balance, clearance, connections, and release, and it is verified by fit checks against the actual airframe.","A safety-and-arming requirement. Written as several conditions that must all hold, so no single failure can enable the chain.","An interface-control requirement. It fixes one approved set of dimensions and connections so independently built parts still mate.","A verification requirement. It names the inspection, test, or rehearsal that turns a claim into a record."],"mapping":[0,1,2,3]},"story":"A physical idea becomes an engineering program only after it is translated into requirements: what must fit, what must happen in sequence, what must remain safe, and what evidence will count as success. For Fat Man, the implosion assembly, firing system, casing, aircraft, and field procedures all must agree at their interfaces. The team must connect each broad need to a concrete requirement that can be inspected or tested."},{"day":4,"title":"Packaging and center of gravity","progress":"Use a simplified mass-moment calculation to see why aircraft integration depends on where subsystems are placed inside a large casing.","takeaway":"Packaging decisions affect handling, suspension, and flight behavior even when every component works individually.","game":{"type":"Ballpark","title":"Find the balance point","setup":"An inert mockup has a 100 kg module and a 300 kg module separated by 1.5 m along a reference axis. This is not a Fat Man dimension set.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"About 1.13 m from the light module, three-quarters of the way toward the heavy one.","why":"Balance follows the mass, so the centre of gravity sits close to the heavier module.","givens":["Total mass = 400 kg","Distance from the light module = separation x heavy mass / total mass"],"task":"Estimate how far the centre of mass sits from the light module.","relationship":"Centre of mass from the light module = separation × heavy mass ÷ total mass."},"story":"Fat Man is not only a nuclear assembly; it is a large object that must fit inside a modified B-29, remain balanced, and separate safely from the aircraft. Center of gravity describes where the object’s weight effectively acts, and a shift can change flight or release behavior. Engineers use inert shapes and weight distributions to study packaging without exposing nuclear components."},{"day":5,"title":"Integrate Fat Man with the Silverplate B-29","progress":"Prioritize the aircraft modifications and evidence needed to carry an unusually large weapon safely and predictably.","takeaway":"Integration funding should target evidence at the boundary between systems.","game":{"type":"Science Tank","title":"Integrate Fat Man with the Silverplate B-29","setup":"The air-integration team can fund only the most decision-relevant work this month.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 75 to B, 15 to C after interface control, 10 in reserve; A receives none unless a functional problem emerges.","why":"The instrumented carriage-and-release test addresses the coupled aircraft-weapon interface and can expose multiple failure modes at once.","proposals":[{"label":"A","text":"Repeat cosmetic casing refinements that do not affect fit, loads, or release."},{"label":"B","text":"Instrument an inert full-scale shape during carriage and release tests, measuring loads, vibration, clearance, and separation."},{"label":"C","text":"Optimize one internal bracket before the aircraft interface drawing is frozen."}],"research":"","recommended":{"B":75,"C":15,"A":0}},"story":"The Silverplate B-29 is modified to carry and release the unusually shaped Fat Man weapon. Aircraft structure, bomb-bay clearances, electrical connections, crew procedures, and flight performance all become part of the weapon system. A design that works on a laboratory stand will still fail as a weapon if it cannot be loaded, carried, armed, and released reliably from the aircraft."},{"day":6,"title":"Drop time and the pumpkin-bomb test program","progress":"Connect inert ballistic test articles to release timing, observation windows, and aircraft separation.","takeaway":"Ballistic mockups convert a paper release concept into measured flight evidence.","game":{"type":"Ballpark","title":"Drop time and the pumpkin-bomb test program","setup":"Use a deliberately simplified vacuum calculation for an inert training shape; real trajectories require drag and full flight testing.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"t approximately sqrt(16,000/9.8) approximately 40 seconds.","why":"The simple result establishes a scale; inert drop tests were necessary because real aerodynamic behavior, winds, and aircraft motion matter.","givens":["Release altitude h = 8,000 m","g = 9.8 m/s^2","Use t approximately sqrt(2h/g)"],"task":"Estimate the fall time ignoring drag.","relationship":"For a drop from rest, time = the square root of (2 × height ÷ g)."},"story":"Before using a live weapon, crews dropped inert ‘pumpkin bombs’ with a similar external shape and weight to Fat Man. These tests measure release behavior, fall time, aircraft handling, and bombing procedures without a nuclear core. The program needs estimates from rough flight conditions because the weapon’s fuzing and crew timing depends on how long it will fall after release."},{"day":7,"title":"The Fat Man firing chain","progress":"Identify the functional stages between mission authorization and the simultaneous initiation command, without reproducing circuitry.","takeaway":"No single casual action should bridge the entire path from safe state to firing.","game":{"type":"Sequence","title":"The Fat Man firing chain","setup":"Order the high-level firing-chain logic used in a safety-critical ordnance system.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Maintain the system in a safe, inhibited state during storage and handling. -> Receive independent arming conditions and mission-authorized inputs. -> Condition and distribute the firing command through the controlled electrical system. -> Initiate the approved test or mission configuration and record the system state.)","why":"A safe firing chain separates storage, arming, command conditioning, and final action into traceable stages.","cards":["Maintain the system in a safe, inhibited state during storage and handling.","Receive independent arming conditions and mission-authorized inputs.","Condition and distribute the firing command through the controlled electrical system.","Initiate the approved test or mission configuration and record the system state."],"order":[0,1,2,3]},"story":"The Fat Man firing chain carries an authorized command through power, switching, timing, and many output channels. Each link must remain disabled during handling but work reliably after release. Engineers treat the chain as a sequence because an error in order—power too early, a missing permissive, or a late pulse—can make the weapon unsafe or ineffective."},{"day":8,"title":"Arming, fuzing, and safety interlocks","progress":"Distinguish controls that prevent premature action from controls that determine when an authorized system acts.","takeaway":"A safe system makes its state constrained, visible, and independently checkable.","game":{"type":"Protocol","columns":["What the situation requires","Which safeguard delivers it"],"title":"Arming, fuzing, and safety interlocks","setup":"Match each scenario to the most relevant ordnance control.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"The weapon is being transported and must remain electrically inhibited. -> Transport safety device; The aircraft has released the weapon, but the firing chain should not respond until authorized conditions are met. -> Fuzing logic; Two independent states must agree before the final command can pass. -> Interlock or permissive logic; A technician must confirm which safe/armed state was present after a rehearsal. -> State indication and recorded checklist","why":"Safety, fuzing, interlocks, and indication solve different parts of the control problem.","scenarios":["The weapon is being transported and must remain electrically inhibited.","The aircraft has released the weapon, but the firing chain should not respond until authorized conditions are met.","Two independent states must agree before the final command can pass.","A technician must confirm which safe/armed state was present after a rehearsal."],"choices":["Keep the transport safety device engaged so electrical energy cannot reach the firing chain during handling.","Use fuzing logic that waits for approved post-release conditions before allowing a firing command.","Use an interlock, or permissive, that requires two independent safe-to-fire conditions to agree.","Provide a visible state indication and a recorded checklist so technicians can prove whether the system was safe or armed."],"mapping":[0,1,2,3]},"story":"Arming and fuzing are different jobs. Arming changes the system from a safe state toward readiness, while fuzing decides when conditions such as release, time, or altitude permit firing. Interlocks require independent conditions to agree before a dangerous command can pass. Fat Man needs these layers so normal transport or a single fault cannot accidentally initiate the firing chain."},{"day":9,"title":"Why simultaneity became an engineering requirement","progress":"Estimate how small electrical-path differences can create measurable timing differences in a multi-channel initiation system.","takeaway":"Timing synchronization is a physical interface, not merely a clock-setting problem.","game":{"type":"Ballpark","title":"Why simultaneity became an engineering requirement","setup":"This exercise uses generic signal-cable values and does not state an actual Fat Man tolerance.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"Delta t = 0.40/(2.0 x 10^8) = 2 x 10^-9 s, or 2 ns.","why":"A small delay at one point does not produce a slightly worse implosion; it produces an asymmetric one. So simultaneity stops being a matter of setting clocks and becomes a physical interface problem: a difference in cable path length is a difference in arrival time, at the speed the signal travels. Divide the path mismatch by that speed and the answer is in nanoseconds. Cables, capacitors, switches and firing units all contribute time, and all of it has to be accounted for rather than assumed small.","givens":["Signal speed in cable = 2.0 x 10^8 m/s","Two cable paths differ by 0.40 m","Delay difference = path difference / signal speed"],"task":"Estimate the delay difference.","relationship":"Delay = path mismatch ÷ signal speed. Multiply by 10⁹ to turn seconds into nanoseconds."},"story":"Many detonators have to act so nearly together that their separate waves merge into one inward-moving shape. The values in this exercise are generic, not an actual tolerance.","assumes":["a signal travels along a cable at a finite speed"]},{"day":10,"title":"Detonator development and lot acceptance","progress":"Choose a development portfolio that tests simultaneity, reproducibility, and manufacturing variation rather than celebrating one successful unit.","takeaway":"Reliability belongs to the manufactured population, not the prototype champion.","game":{"type":"CHOICE","title":"Detonator development and lot acceptance","setup":"The detonator program has three competing requests for its next 100 credits.","play":"The detonator programme can run one of these. Which?","answer":"Sample several production lots and measure the timing distribution of each.","why":"Implosion does not need a good detonator. It needs every unit in a lot to fire inside a spread of well under a microsecond, because the symmetry depends on simultaneity and the worst unit sets the result. That is a property of a manufactured population rather than of a design, so the evidence has to be a distribution — mean and spread from a sample large enough to bound the tail. Testing the best units, or a handful chosen by an engineer, measures the way to know it is to sample the population and look at the tail.","task":"The detonator programme can run one of these. Which?","question":"The detonator programme can run one of these. Which?","choices":["Sample several production lots and measure the timing distribution of each.","Build one unit to the best achievable standard and fire it repeatedly.","Tighten the drawing tolerances and re-inspect the parts dimensionally.","Wait for the first full-system trial and judge the detonators from it."],"correctChoice":"Sample several production lots and measure the timing distribution of each.","rebuttals":["One unit fired repeatedly measures that unit. It says nothing about the next thirty off the line, which is what the device will be built from.","Dimensional inspection catches parts outside the drawing. The requirement here is written in nanoseconds, and two parts inside the same tolerance can fire measurably apart.","Waiting for the full-system trial makes every component a suspect at once when it disappoints, and there is one trial."]},"story":"The detonator programme has three competing requests and enough credit for one hundred points of work. A detonator turns an electrical pulse into the start of an explosive wave.","assumes":["a sample of a production run says something about the rest of it"]},{"day":11,"title":"Explosive-lens segment interfaces","progress":"Treat the lens system as a controlled assembly whose segment identity, orientation, fit, and inspection status must remain traceable.","takeaway":"Configuration control is part of the physical design.","game":{"type":"Protocol","columns":["What you find on the floor","What you do about it"],"title":"Explosive-lens segment interfaces","setup":"Match each observed problem to the first engineering response.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"A segment arrives without a readable lot identifier. -> Quarantine and restore traceability; Two interface drawings specify different reference surfaces. -> Resolve the configuration conflict before assembly; A fitted assembly shows a gap outside the approved inspection limit. -> Stop and disposition the nonconformance; A technician proposes rotating a segment to make it fit without an approved change. -> Reject the unapproved field modification","why":"Precision assemblies fail when identity, geometry, and configuration authority become informal.","scenarios":["A segment arrives without a readable lot identifier.","Two interface drawings specify different reference surfaces.","A fitted assembly shows a gap outside the approved inspection limit.","A technician proposes rotating a segment to make it fit without an approved change."],"choices":["Quarantine the unidentified segment until its production lot and inspection history are restored.","Stop assembly and resolve which drawing revision defines the correct reference surface.","Record the out-of-limit gap as a nonconformance and obtain an authorized engineering disposition.","Reject the unapproved rotation because changing orientation can alter wave timing even if the part appears to fit."],"mapping":[0,1,2,3]},"story":"Fat Man’s explosive system is assembled from many manufactured segments whose surfaces must meet in controlled positions. A gap, reversed piece, missing identity mark, or conflicting drawing can change how the wave crosses an interface. Engineers use configuration records, inspection limits, and quarantine procedures because ‘making it fit’ by an unapproved adjustment can hide a serious symmetry error."},{"day":12,"title":"Select high-explosive materials for a wave-shaping system","progress":"Balance wave behavior, manufacturability, stability, compatibility, and inspection in the historically novel lens program.","takeaway":"A material is suitable only when its performance and its production process are both controlled.","game":{"type":"Science Tank","title":"Select high-explosive materials for a wave-shaping system","setup":"Choose a safe research portfolio; no formulations or processing recipes are provided.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 90 to B, 5 to A for bounded physics comparison, 5 in reserve.","why":"The lens program required materials to satisfy a coupled set of physical and production constraints.","proposals":[{"label":"A","text":"Optimize only the highest detonation velocity, ignoring casting quality and compatibility."},{"label":"B","text":"Compare candidate materials using inert property characterization, small authorized tests, aging observations, and manufacturability evidence."},{"label":"C","text":"Select the easiest material to machine even if its wave behavior is poorly characterized."}],"research":"","recommended":{"B":90,"A":5}},"story":"An explosive lens uses materials with different detonation speeds and shaped boundaries to bend an outward detonation wave into a converging one. Engineers must choose materials not only for speed but also for stability, manufacturability, compatibility, and reproducibility. The best theoretical pair will be useless if production cannot hold its properties consistently from segment to segment."},{"day":13,"title":"The X-unit as a pulsed-power subsystem","progress":"Understand the high-level role of the X-unit in storing energy, receiving an authorized command, and delivering coordinated outputs.","takeaway":"A pulsed-power unit is an interface between mission logic and precise physical timing.","game":{"type":"Sequence","title":"The X-unit as a pulsed-power subsystem","setup":"Order a conceptual pulsed-power sequence without circuit values or construction details.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Charge and verify the energy-storage subsystem while final outputs remain inhibited. -> Confirm safe/armed state and continuity through approved checks. -> Receive the authorized firing command. -> Distribute the conditioned pulse to the initiation channels and record diagnostic evidence.)","why":"Energy storage, state verification, command receipt, and output distribution are separate functions that must be tested separately and together.","cards":["Charge and verify the energy-storage subsystem while final outputs remain inhibited.","Confirm safe/armed state and continuity through approved checks.","Receive the authorized firing command.","Distribute the conditioned pulse to the initiation channels and record diagnostic evidence."],"order":[0,1,2,3]},"story":"The X-unit stores electrical energy and releases it as a short, synchronized pulse to the detonators. It must remain safely inhibited during handling, verify its state, and then distribute a closely timed command through many channels. This pulsed-power problem connects ordinary electrical engineering directly to the symmetry of the implosion."},{"day":14,"title":"Cable routing and signal integrity","progress":"Use a generic propagation estimate to show why matched routing and documented cable changes mattered.","takeaway":"Seemingly passive hardware can carry critical timing information.","game":{"type":"Ballpark","title":"Turn a timing budget into a length limit","setup":"An inert test rack must hold two signal paths matched to within 2 ns; signal speed in the cable is 2.0 x 10^8 m/s. These are classroom values.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"About 0.4 m, or 40 cm. The response is to turn the timing requirement into a measurable cable-length limit held under configuration control.","why":"Cable geometry can become part of the timing system.","givens":["Timing tolerance = 2 ns = 2 x 10^-9 s","Signal speed = 2.0 x 10^8 m/s","Allowed path mismatch = tolerance x signal speed"],"task":"Estimate the largest allowed path mismatch, then state the engineering response.","relationship":"Allowed length mismatch = timing tolerance × signal speed. Multiply by 100 to turn metres into centimetres."},"story":"A fast electrical pulse can be distorted by cable length, impedance mismatch, poor connections, or electromagnetic interference. If channels receive different pulse shapes or arrival times, detonators may not act together. Fat Man engineers therefore controlled cable routing, connector identity, shielding, and calibration as carefully as the explosive components themselves."},{"day":9,"title":"Why the limit is written down","place":"Chemistry and Metallurgy Building","scene":"Two half-assemblies go on the same bench this afternoon. The procedure sets a mass limit and a spacing. Both sit well below anything calculated to be critical.","story":"Two half-assemblies go on the same bench this afternoon. The procedure sets a mass limit and a spacing. Both sit well below anything calculated to be critical.","takeaway":"Administrative limits sit far below the physical limit, because the failures are human rather than nuclear.","game":{"type":"CHOICE","title":"Why the limit is written down","setup":"Chemistry and Metallurgy Building","play":"The written limit is well below the critical mass. What is the argument for keeping it there?","question":"The written limit is well below the critical mass. What is the argument for keeping it there?","choices":["The margin absorbs the mistakes that actually happen — a miscount, a moved reflector, a second piece brought in.","The calculation of critical mass is unreliable, so the limit compensates for it.","It is a formality: the physical limit is the only one that matters.","Below the limit the material cannot be reflected, so geometry no longer matters."],"correctChoice":"The margin absorbs the mistakes that actually happen — a miscount, a moved reflector, a second piece brought in.","answer":"The margin absorbs the mistakes that actually happen — a miscount, a moved reflector, a second piece brought in.","why":"Criticality depends on mass, geometry, reflection and moderation. Any of those can change by accident. A hand nearby reflects neutrons. A spilled solution moderates them. A second piece on the bench adds mass. The written limit sits far below the physical one, so one human error cannot reach it. It is written down so the margin does not depend on who is on shift. Two of this laboratory's fatal accidents were exactly that error.","rebuttals":["The calculations are good; the limit exists because the inputs to them get changed by accident.","A physical limit reached by surprise kills people. The written limit is what keeps distance from it.","Reflection is possible at any mass, and a hand or a bench is a reflector."]},"assumes":["criticality depends on geometry and surroundings as well as on mass"]},{"day":16,"title":"V-Site assembly workflow","progress":"Follow the controlled movement from inspected components to an integrated non-nuclear assembly at the Los Alamos V-Site.","takeaway":"Assembly is the moment when documentation becomes hardware.","game":{"type":"Sequence","title":"V-Site assembly workflow","setup":"Order a historically grounded but non-operational assembly-control workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Verify identity, inspection status, and approved configuration of incoming components. -> Use dedicated tooling to assemble controlled subassemblies with independent checks. -> Complete electrical continuity and state-verification tests on the authorized configuration. -> Seal records, photograph configuration, and release the assembly to the next controlled test or transport step.)","why":"The V-Site brought high explosives, electrical systems, tooling, and records together under strict safety and configuration controls.","cards":["Verify identity, inspection status, and approved configuration of incoming components.","Use dedicated tooling to assemble controlled subassemblies with independent checks.","Complete electrical continuity and state-verification tests on the authorized configuration.","Seal the records, photograph the configuration, and certify the assembly for the transport it is authorized for."],"order":[0,1,2,3]},"story":"At V-Site, crews must assemble large high-explosive and mechanical components in a controlled sequence. Identity checks, approved tooling, cleanliness, inspections, and independent sign-offs prevent one hidden mistake from being sealed inside the assembly. Fat Man’s complexity makes the assembly procedure part of the engineering design, not an afterthought."},{"day":17,"title":"Tooling, jigs, and tolerance stack-up","progress":"Estimate how small placement errors can accumulate across a segmented precision assembly.","takeaway":"Precision comes from the full datum and tooling system.","game":{"type":"Ballpark","title":"Tooling, jigs, and tolerance stack-up","setup":"Use an invented three-interface fixture; no weapon geometry is represented.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"Worst case = +/-0.45 mm.","why":"A fixture must control the assembly-level stack, not merely each individual component.","givens":["Three independent worst-case placement limits are each +/-0.15 mm","Worst-case absolute limits add","Statistical root-sum-square may be smaller but requires justified independence"],"task":"Estimate the worst-case stack.","relationship":"Worst-case stack-up = tolerance per interface × the number of interfaces."},"story":"A jig holds a part in a repeatable position, and a tolerance is the allowed variation in a dimension. When several parts are assembled, their small variations can add into a tolerance stack-up that produces a large final misalignment. Fat Man engineers need tooling and dimensional analysis to make sure acceptable individual parts still form an acceptable complete assembly."},{"day":18,"title":"Inspection and lot traceability","progress":"Build an evidence chain from material lot through machining, inspection, assembly, and test result.","takeaway":"The historical record of a complex device is itself an engineering instrument.","game":{"type":"Protocol","columns":["What you want to know","Which record tells you"],"title":"Inspection and lot traceability","setup":"Match each record to the question it answers.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"Which production batch supplied this component? -> Lot traveler; Was the approved geometry verified before assembly? -> Inspection report; Which exact configuration produced the test result? -> As-built configuration record; What happened to a component that failed inspection? -> Nonconformance and disposition record","why":"Without traceability, a successful test cannot be reproduced and a failure cannot be bounded.","scenarios":["Which production batch supplied this component?","Was the approved geometry verified before assembly?","Which exact configuration produced the test result?","What happened to a component that failed inspection?"],"choices":["Read the lot traveler to identify the production batch and every processing step the component passed through.","Read the inspection report to see which approved dimensions and properties were actually measured.","Read the as-built configuration record to identify the exact parts and revision used in the test.","Read the nonconformance and disposition record to learn why a failed part was rejected, repaired, or accepted by authority."],"mapping":[0,1,2,3]},"story":"Inspection records show what is measured, lot travelers trace a component through production, and as-built records identify the exact configuration that is being tested. If a part fails inspection, a nonconformance record documents what happened and who authorized the disposition. This traceability allows Los Alamos to connect a test result to the actual Fat Man hardware rather than to an ideal drawing."},{"day":19,"title":"Environmental qualification of Fat Man subsystems","progress":"Prioritize tests for vibration, temperature, handling shock, electrical state, and aircraft carriage without risking scarce full assemblies.","takeaway":"Qualification is a ladder of evidence, not one final ordeal.","game":{"type":"Science Tank","title":"Environmental qualification of Fat Man subsystems","setup":"The qualification team must distribute its next 100 credits.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 85 to B, 10 to A only after prerequisites, 5 in reserve.","why":"A staged campaign finds inexpensive failures early while preserving integrated tests for coupled effects.","proposals":[{"label":"A","text":"Spend all credits on one dramatic full-system trial."},{"label":"B","text":"Build a staged program: component screening, subsystem environments, instrumented carriage, then a limited integrated test."},{"label":"C","text":"Test only at room temperature because the mission duration is short."}],"research":"","recommended":{"B":85,"A":10}},"story":"Fat Man subsystems must survive transportation, vibration, temperature changes, humidity, and aircraft operation before they enter service. Environmental qualification exposes hardware to representative conditions and then checks whether performance changes. A component that works only in a quiet laboratory cannot be considered ready for Tinian or a combat mission."},{"day":20,"title":"Reliability of a series firing chain","progress":"Estimate why many individually reliable elements can still produce a weaker system reliability.","takeaway":"System reliability cannot be inferred from the best component.","game":{"type":"Ballpark","title":"Reliability of a series firing chain","setup":"A generic chain has four required subsystems, each with independent reliability 0.98 for one mission.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"R approximately 0.98^4 approximately 0.92.","why":"Every required element creates another opportunity for failure, even when each appears highly reliable.","givens":["Four required subsystems","Each reliability = 0.98","Series reliability = product of component reliabilities"],"task":"Estimate total reliability.","relationship":"A chain works only if every link does, so reliability = the per-link reliability raised to the number of links."},"story":"In a series firing chain, every required link must work for the final command to pass, so the reliability of the complete chain can be lower than the reliability of any one part. Adding more necessary components can reduce total success probability unless each is exceptionally reliable. Engineers use this logic to identify weak links and decide where redundancy or redesign matters most."},{"day":21,"title":"Fat Man failure modes and effects analysis","progress":"Classify failures by whether they threaten safety, prevent function, corrupt evidence, or create a recoverable delay.","takeaway":"FMEA turns surprise into an organized decision.","game":{"type":"Protocol","columns":["What you observe","Which kind of problem it is"],"title":"Fat Man failure modes and effects analysis","setup":"Match each notional failure to the first review category.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"An arming indicator disagrees with the physical safe-state check. -> A safety-critical ambiguity. The true state is unknown, so stop and verify independently instead of trusting either indication.; One initiation channel fails continuity before release. -> A mission-function failure. The system is safe but will not work, so hold, find the break, and repair before release.; A diagnostic recorder is not synchronized, but the device remains safe. -> An evidence loss. Nothing is unsafe and nothing will fail, but the test may no longer answer the question it was built to answer.; A casing access panel is delayed but can be replaced before the mission window. -> A recoverable schedule problem. No safety or function consequence, so handle it through configuration control rather than escalation.","why":"Not all anomalies carry the same consequence, but each needs a predefined disposition path.","scenarios":["An arming indicator disagrees with the physical safe-state check.","One initiation channel fails continuity before release.","A diagnostic recorder is not synchronized, but the device remains safe.","A casing access panel is delayed but can be replaced before the mission window."],"choices":["A safety-critical ambiguity. The true state is unknown, so stop and verify independently instead of trusting either indication.","A mission-function failure. The system is safe but will not work, so hold, find the break, and repair before release.","An evidence loss. Nothing is unsafe and nothing will fail, but the test may no longer answer the question it was built to answer.","A recoverable schedule problem. No safety or function consequence, so handle it through configuration control rather than escalation."],"mapping":[0,1,2,3]},"story":"Failure-modes-and-effects analysis begins by imagining how each part can fail, what causes that failure, how it will be detected, and what the system will do next. For Fat Man, failures ranged from a safe abort to an undetected asymmetry. The value of the analysis is not predicting every accident, but forcing the team to connect component faults to system consequences before deployment."},{"day":22,"title":"Common-mode failure in simultaneous initiation","progress":"Recognize that nominally redundant channels can share one clock, power source, procedure, or manufacturing defect.","takeaway":"The hardest reliability risks often hide in shared infrastructure.","game":{"type":"Science Tank","title":"Common-mode failure in simultaneous initiation","setup":"Choose the most valuable reliability investment.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 90 to B, 10 in reserve; A and C receive none until common causes are addressed.","why":"Redundancy protects only against failures that are genuinely independent.","proposals":[{"label":"A","text":"Add more channels that all share the same untested trigger path."},{"label":"B","text":"Create independent timing references and diagnostics, then test shared power and procedure failure modes."},{"label":"C","text":"Assume identical channels fail independently because they are physically separate."}],"research":"","recommended":{"B":90,"C":0}},"story":"Redundancy does not protect a system when several channels share the same power supply, clock, connector design, or manufacturing defect. That shared vulnerability is a common-mode failure. Since Fat Man relies on many simultaneous initiation channels, engineers must look for one fault capable of making all channels late, weak, or silent together."},{"day":23,"title":"Configuration control after a design change","progress":"Prevent the Fat Man program from mixing old and new lens, electrical, casing, or assembly definitions during the final push.","takeaway":"A design is not changed until the whole evidence system is changed with it.","game":{"type":"Sequence","title":"Configuration control after a design change","setup":"Order the change-control process.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Document the anomaly and identify every affected interface and test result. -> Review the proposed correction with owners from all affected divisions. -> Approve one controlling revision and update drawings, travelers, trainers, and spares. -> Retest the changed functions and preserve the evidence linking old and new configurations.)","why":"A late change propagates through hardware, procedures, training, and interpretation of earlier tests.","cards":["Document the anomaly and identify every affected interface and test result.","Review the proposed correction with owners from all affected divisions.","Approve one controlling revision and update drawings, travelers, trainers, and spares.","Retest the changed functions and preserve the evidence linking old and new configurations."],"order":[0,1,2,3]},"story":"After a design change, drawings, parts, procedures, training materials, and test records must all refer to the same revision. Configuration control prevents a team from assembling one version while interpreting evidence from another. As Trinity approached, Los Alamos needs strict change authority because even a sensible local improvement can invalidate earlier qualification work."},{"day":24,"title":"Critical path to an integrated trial","progress":"Identify how the longest dependency chain—not the largest team—sets the earliest possible test date.","takeaway":"Schedule management starts with dependencies, not activity counts.","game":{"type":"Ballpark","title":"How much float does the parallel chain have?","setup":"A simplified schedule has three dependency chains: lens inspection at 3 + 4 + 2 weeks, electrical qualification at 2 + 3 + 2, and casing work at 2 + 2 + 3.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"Two weeks of float; a third week of slippage makes it the new critical path.","why":"The longest chain is the critical path. It is the only place where adding people or shifts moves the date. Effort poured into a task that is not on it changes nothing, however busy it makes everyone. It is spent on float that was already there. Float is the gap between the controlling chain and the one being worked on, and it is finite. Enough slippage on a parallel chain makes that chain the new critical path. At which point the whole calculation has to be done again.","givens":["Lens inspection chain totals 9 weeks and controls the date","Each other chain totals 7 weeks","Float = controlling chain - parallel chain"],"task":"Estimate how much a parallel chain can slip before it controls the date.","relationship":"Float on a parallel chain = the length of the controlling chain − the length of that chain."},"story":"Three chains of work are running in parallel and the integrated trial cannot happen until the longest one finishes. Fat Man's schedule is managed this way.","assumes":["work that can happen in parallel does not add up"]},{"day":25,"title":"The Jumbo contingency decision","progress":"Examine the historical proposal for a massive containment vessel intended to recover scarce material if the Trinity high explosives worked but the nuclear reaction did not.","takeaway":"Good engineering retires or reshapes contingencies when their decision value changes.","game":{"type":"Science Tank","title":"The Jumbo contingency decision","setup":"The Trinity team must decide where to invest as confidence in implosion rises.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 70 to B, 15 to A for limited contingency knowledge, 15 to site safety and reserve within B.","why":"Jumbo illustrates how contingency plans can become less valuable as evidence changes, while consequence management remains essential.","proposals":[{"label":"A","text":"Continue the containment-vessel plan regardless of new evidence."},{"label":"B","text":"Shift funds toward diagnostics, site safety, and recovery plans while retaining a bounded contingency assessment."},{"label":"C","text":"Cancel every contingency because a successful test is now expected."}],"research":"","recommended":{"B":70,"A":15}},"story":"Jumbo is a massive steel vessel considered as a way to contain scarce plutonium if the Trinity high explosives fail to produce a nuclear explosion. Using it might protect material, but it can interfere with diagnostics and create new hazards. The decision forces engineers to compare uncertain failure risk with the scientific value of an unobstructed full-scale test."},{"day":26,"title":"Trinity field engineering","progress":"Coordinate transport, tower or ground interfaces, electrical connections, weather protection, communications, and controlled final assembly.","takeaway":"Field integration is ordered so that every interface is proved before the thing that needs it arrives.","game":{"type":"Sequence","title":"Trinity field engineering","setup":"Order the high-level field-integration sequence without operational assembly details.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1. Survey the site and establish power, communications and controlled access, which everything after this runs on. 2. Install and independently inspect each electrical and diagnostic interface, while there is still time to replace one. 3. Bring the approved assembly into the field configuration, once every interface it will use has been proved. 4. Run the countdown against defined hold points, then secure and document the site.","why":"Field integration succeeds or fails on interfaces, and an interface has to be proved before the thing that depends on it arrives. Site survey, power, communications and controlled access come first because everything after them runs on them. Each electrical and diagnostic interface is then installed and independently inspected while there is still time to replace one. Only then does the approved assembly come into field configuration — once it is at the tower, replacing a cable run means undoing the step before it. The countdown runs against defined hold points, and the site is documented afterwards.","cards":["Survey the site and establish power, communications and controlled access.","Install each electrical and diagnostic interface, and have every one independently inspected.","Bring the approved assembly up the tower into its field configuration.","Run the countdown against the defined hold points, and record what every instrument saw."],"order":[0,1,2,3],"rebuttals":["Survey, power, communications and access come first. Everything after this runs on them, and none of it can be installed before they exist.","Install and independently inspect each interface second — while there is still time to replace one, which is the whole reason it is here rather than later.","Bring the assembly into field configuration third, after every interface it will use has been proved. Once it is at the tower, fixing a cable means undoing this step.","Run the countdown against hold points and document the site last. A hold point is what makes a countdown stoppable rather than a commitment."]},"story":"The device is a small part of what has to work in the desert. Trinity is scheduled around a weather window, and a missed interface is not recoverable inside it.","assumes":["a schedule set by weather cannot be extended"]},{"day":27,"title":"Interfaces to Trinity diagnostics","progress":"Ensure the test article, firing system, timing network, cameras, pressure measurements, and radiation instruments share a controlled timing and configuration basis.","takeaway":"Measurement interfaces deserve the same control as hardware interfaces.","game":{"type":"Protocol","columns":["What is wrong with the record","How you fix it"],"title":"Interfaces to Trinity diagnostics","setup":"Match each diagnostic concern to the correct engineering control.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"A camera time mark cannot be related to the firing command. -> Shared timing fiducial; A cable change is made after the timing calibration. -> Repeat calibration and record the new configuration; Two instruments use different coordinate origins for the same event. -> Common reference frame and interface document; A recorder saturates at the expected signal level. -> Add a lower-sensitivity channel or alternate diagnostic","why":"Diagnostics are useful only if their time, position, range, and configuration are traceable to the event.","scenarios":["A camera time mark cannot be related to the firing command.","A cable change is made after the timing calibration.","Two instruments use different coordinate origins for the same event.","A recorder saturates at the expected signal level."],"choices":["Add a shared timing fiducial so the camera record can be aligned with the firing command and other instruments.","Repeat the timing calibration after the cable change and record the new configuration before testing.","Create one common coordinate system and interface drawing so every instrument describes the same physical location.","Add a lower-sensitivity channel or a different diagnostic so an unexpectedly strong signal does not saturate every record."],"mapping":[0,1,2,3]},"story":"Trinity diagnostics need shared timing marks, known viewing directions, calibrated cables, and enough dynamic range to record unexpectedly large or small signals. A measurement without a common time or coordinate reference cannot be compared with the firing sequence or another instrument. Engineers therefore treat diagnostic interfaces as part of the test configuration."},{"day":28,"title":"Post-Trinity design freeze","progress":"Translate the Trinity evidence into a controlled Fat Man configuration while separating proven performance from remaining production and mission risks.","takeaway":"A freeze comes before the paperwork, or the paperwork describes something still changing.","game":{"type":"Sequence","title":"Post-Trinity design freeze","setup":"Order the post-test decision process.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1. Recover and reconcile the timing, hydrodynamic and radiation records into one account of the shot. 2. Compare that account with the pre-test predictions, and name what is still unexplained. 3. Approve only the changes the evidence supports, and freeze the configuration. 4. Update assembly records, procedures and training against the frozen configuration.","why":"Each stage is the input to the next. The timing, hydrodynamic and radiation records are reconciled into one account of the shot, because there is nothing to compare until they agree with each other. That account is then compared with the pre-test predictions, and what remains unexplained is named rather than absorbed. Only then can the evidence-supported changes be approved and the configuration frozen. The freeze comes before the paperwork — reverse those two and the documents describe a configuration that is still moving.","cards":["Recover and reconcile the timing, hydrodynamic and radiation records into one account of the shot.","Compare that account with the pre-test predictions, and name what is still unexplained.","Approve only the changes the evidence supports, and freeze the configuration.","Update assembly records, procedures and training against the frozen configuration."],"order":[0,1,2,3],"rebuttals":["Reconcile the records into one account of the shot first. Three disagreeing records are not evidence about anything yet.","Compare that account with the pre-test predictions second, and name what is still unexplained. An unnamed discrepancy is one nobody will return to.","Approve only the evidence-supported changes and freeze the configuration third. This is the step that ties the article to the test.","Update records, procedures and training last, against the frozen configuration. Do it earlier and the paperwork describes something still changing."]},"story":"Trinity has produced new evidence and there is almost no time to use it. The pressure at this moment is to keep improving, and every unlogged improvement breaks the link between the test and the article.","assumes":["what was tested and what gets built can drift apart"]},{"day":29,"title":"Project Alberta and Tinian logistics","progress":"Connect Los Alamos engineering to the overseas team responsible for final preparation, aircraft integration, and mission support.","takeaway":"Deployment is a new integration phase, not merely transportation.","game":{"type":"Protocol","columns":["What the mission requires","How it is arranged"],"title":"Project Alberta and Tinian logistics","setup":"Match each Tinian challenge to the needed Project Alberta capability.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"Specialized components and records must arrive securely and in known condition. -> Controlled transport and custody; A modified B-29 requires depot-level support without exposing the program broadly. -> Dedicated Silverplate maintenance organization; Final assembly and checks must occur near the mission base under strict control. -> Special assembly facilities and checklists; Scientific personnel must interpret anomalies without the full Los Alamos organization present. -> Embedded Los Alamos technical team with clear authority","why":"Project Alberta extended the laboratory into a distant operational environment.","scenarios":["Specialized components and records must arrive securely and in known condition.","A modified B-29 requires depot-level support without exposing the program broadly.","Final assembly and checks must occur near the mission base under strict control.","Scientific personnel must interpret anomalies without the full Los Alamos organization present."],"choices":["Use controlled transport and chain-of-custody records so every component arrives with known identity and condition.","Provide a dedicated Silverplate maintenance organization able to support the modified B-29 without exposing the project broadly.","Use special assembly facilities and step-by-step checklists for final work near the mission base.","Embed a Los Alamos technical team with authority to interpret anomalies and approve or stop field work."],"mapping":[0,1,2,3]},"story":"Project Alberta moves Fat Man components, records, trained specialists, and Silverplate aircraft support to Tinian. Transport must preserve identity and condition, while final assembly must occur under strict technical and security control far from Los Alamos. The weapon is not truly deployable until the field team can reproduce the approved configuration and diagnose problems on site."},{"day":30,"title":"Final Fat Man engineering readiness review","progress":"Synthesize the evidence for a specific controlled configuration: aircraft compatibility, safe handling, electrical function, initiation reliability, assembly records, and trained field teams.","takeaway":"A weapon-system readiness decision is broader than proof of its central physical concept.","game":{"type":"Science Tank","title":"Final Fat Man engineering readiness review","setup":"The board must decide how to allocate its final review effort.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 90 to B, 10 to independent challenge and reserve; A and C are insufficient.","why":"Trinity established the implosion principle, but readiness also depended on production, assembly, aircraft, safety, and field evidence.","proposals":[{"label":"A","text":"Review only the successful Trinity result."},{"label":"B","text":"Build an evidence matrix linking every mission-critical claim to component tests, integrated tests, inspections, rehearsals, and responsible sign-off."},{"label":"C","text":"Approve because the schedule is fixed and the major physics question has been answered."}],"research":"","recommended":{"B":90}},"story":"The final engineering review asks whether Fat Man can be assembled, carried, armed, released, and initiated in the exact configuration supported by tests. It combines hardware reliability, records, crew training, aircraft interfaces, and unresolved risks. A successful physics concept is only one part of declaring the complete weapon ready."}],"X":[{"day":1,"title":"Why plutonium required implosion","progress":"Connect the spontaneous-neutron problem in reactor-produced plutonium to the need for a much faster assembly method.","takeaway":"Material physics can determine the required system architecture.","game":{"type":"Protocol","columns":["What is true of the material","What follows for the design"],"title":"Why plutonium required implosion","setup":"Match each observation to its implication for the plutonium weapon program.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"Reactor-produced plutonium contains isotopic components with a higher spontaneous-neutron background. -> Material measurement; A comparatively slow assembly remains vulnerable to an early neutron. -> Timing consequence; An early chain reaction can disrupt the assembly before the intended state is reached. -> Pre-initiation consequence; Los Alamos therefore reorganizes around rapid, symmetric compression. -> Implosion-program response","why":"Reactor-produced plutonium contains isotopes that emit neutrons on their own. The material supplies its own stray neutrons, at a rate nobody chose. A slow assembly spends longer in the state where one of those could start the chain. A chain that starts early releases enough energy to blow the pieces apart before most of the material has reacted. That is pre-initiation. It is a property of the material, not a defect better workmanship can fix. Implosion is the answer: squeeze from all sides, and cut the vulnerable time.","scenarios":["Reactor-produced plutonium contains isotopic components with a higher spontaneous-neutron background.","A comparatively slow assembly remains vulnerable to an early neutron.","An early chain reaction can disrupt the assembly before the intended state is reached.","Los Alamos therefore reorganizes around rapid, symmetric compression."],"choices":["Measure the plutonium’s spontaneous-neutron background, because reactor-produced material contains isotopes that emit random neutrons.","Recognize the timing problem: a slower assembly gives a stray neutron more opportunity to start the chain reaction too early.","Predict pre-initiation: early fission releases energy before full assembly and disrupts the material, producing a much weaker result.","Shift to rapid implosion, which compresses the material from all sides and shortens the vulnerable assembly time."],"mapping":[0,1,2,3],"rebuttals":["The higher spontaneous-neutron background in reactor-produced plutonium is a material measurement. It is the fact everything downstream follows from.","A slow assembly staying vulnerable longer is the timing consequence: more time in the dangerous state means more chances for a stray neutron.","An early chain reaction disrupting the assembly is pre-initiation — the physical consequence, and the reason the timing matters.","Reorganising around rapid symmetric compression is the programme's response. It is what the laboratory did about the first three, not another fact about the material."]},"story":"Measurements on reactor-produced plutonium have come back from the counters and Ordnance has been called in. What follows is the largest redirection of the programme so far.","assumes":["a chain reaction started early releases energy early"]},{"day":2,"title":"From outward detonation to inward compression","progress":"Develop a conceptual picture of how surrounding high explosives could create a converging pressure wave around a plutonium assembly.","takeaway":"The central challenge is controlled convergence, not simply a larger explosion.","game":{"type":"Sequence","title":"From outward detonation to inward compression","setup":"Order the high-level physical chain; no lens geometry or explosive recipe is included.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Initiate the approved outer high-explosive system at multiple controlled points. -> Shape and redirect the resulting waves toward the center. -> Drive an inward-moving pressure front through inert surrounding layers and the plutonium assembly. -> Increase density rapidly enough to change the neutron-balance condition before expansion begins.)","why":"The central problem is controlled convergence rather than raw explosive power. The outer explosive system is initiated at multiple controlled points, because one point gives one outward wave and nothing else. Those waves are then shaped and redirected toward the centre — this is the step that has no precedent. The resulting inward front drives through the inert layers and the assembly. And the density has to rise fast enough to change the neutron balance before expansion begins, which is what makes speed part of the physics rather than a preference.","cards":["Initiate the approved outer high-explosive system at multiple controlled points.","Shape and redirect the detonation waves toward the center.","Drive an inward-moving pressure front through inert surrounding layers and the plutonium assembly.","Increase density rapidly enough to change the neutron-balance condition before expansion begins."],"order":[0,1,2,3],"rebuttals":["Initiating at multiple controlled points comes first. A single point produces a single outward wave, and there is nothing to shape.","Shaping and redirecting the waves toward the centre is the step with no precedent, and it is what the lens programme exists for.","Driving the inward front through the surrounding layers and the assembly is the mechanical consequence of the shaping.","Raising density before expansion begins is the point of all of it. Compression that arrives late is compression that never happened."]},"story":"Ordinary high explosive detonates outward from wherever it was lit, and every intuition anybody on the Hill has comes from that. Implosion needs the opposite, and nobody has done it before.","assumes":["a detonation travels outward from where it starts"]},{"day":3,"title":"Spherical compression and density","progress":"Use constant-mass geometry to relate a modest change in radius to a larger change in density.","takeaway":"Three-dimensional convergence amplifies small radial changes.","game":{"type":"Ballpark","title":"Spherical compression and density","setup":"This is a generic sphere calculation, not a Fat Man dimension or compression claim.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"rho_f/rho_i = 1/(0.90)^3 approximately 1.37.","why":"A ten-percent radius decrease corresponds to roughly a thirty-seven-percent density increase for a constant-mass sphere.","givens":["Mass remains constant","Final radius = 0.90 times initial radius","Density scales as 1/radius^3"],"task":"Estimate final density divided by initial density.","relationship":"Density = mass ÷ volume, and volume goes as radius³. At fixed mass, the density ratio = 1 ÷ (radius ratio)³."},"story":"Compressing a sphere increases its density and reduces the distance neutrons travel before finding another nucleus, while the smaller effective leakage helps the chain reaction grow. But compression must occur throughout the volume rather than merely crushing the surface. Implosion scientists therefore study how radius, density, mass conservation, and wave motion fit together."},{"day":4,"title":"What an explosive lens does","progress":"Treat the Fat Man explosive lens as a wave-shaping device that transforms initially diverging fronts into a more nearly converging front.","takeaway":"A conceptual analogy must still be tested against the actual nonlinear physics.","game":{"type":"Protocol","columns":["What the lens has to do","How it does it"],"title":"What an explosive lens does","setup":"Match each lens-program question to the relevant physics or engineering idea.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"Different regions of the assembly transmit the detonation wave at different speeds. -> Detonation-velocity contrast; Interfaces are shaped so different paths reach the desired wavefront together. -> Wavefront shaping; Segment boundaries and material variation can distort the wave. -> Manufacturing and interface control; Diagnostics must determine whether the wave is converging symmetrically. -> Hydrodynamic symmetry measurement","why":"An explosive lens puts together explosives with different detonation speeds. A front crossing the boundary between them is reshaped, and that speed contrast is the working principle. The boundaries are shaped so faster and slower paths arrive together, as one inward-curving front. Manufacturing then matters as physics. A gap or a property change at a segment boundary distorts the wave crossing it. And symmetry has to be measured rather than assumed, because detonation is violent and nonlinear in a way light is not.","scenarios":["Different regions of the assembly transmit the detonation wave at different speeds.","Interfaces are shaped so different paths reach the desired wavefront together.","Segment boundaries and material variation can distort the wave.","Diagnostics must determine whether the wave is converging symmetrically."],"choices":["Use the contrast in detonation velocity: the wave travels at different speeds through the two explosive materials.","Shape the material boundary so faster and slower paths combine into the desired inward-curving wavefront.","Control manufacturing and segment interfaces because gaps or property variations distort the wave as it crosses the lens.","Measure hydrodynamic symmetry with timing, radiography, or density diagnostics to see whether the wave converges evenly."],"mapping":[0,1,2,3],"rebuttals":["Different regions transmitting the wave at different speeds is the detonation-velocity contrast. It is the property the whole device is built out of.","Shaping the interfaces so different paths arrive together is wavefront shaping — the geometry, which the velocity contrast makes possible.","Segment boundaries and material variation distorting the wave is manufacturing control. It is where a good design becomes a bad component.","Determining whether the wave converges symmetrically is a measurement problem, and it is the one that says whether any of the three above worked."]},"story":"The lens programme has been given the problem of shaping a detonation front, and the name is a deliberate analogy. Every part of that analogy has to be earned against real firing data.","assumes":["a lens bends light by slowing it in some places more than others"]},{"day":8,"title":"How many half-lives have passed","place":"Diagnostics Bay","scene":"A sample counted at 8,000 counts a minute reads 500 today, and the notebook does not say how long ago the first count was taken. The half-life is on the chart at 12 hours.","story":"A sample counted at 8,000 counts a minute reads 500 today, and the notebook does not say how long ago the first count was taken. The half-life is on the chart at 12 hours.","takeaway":"Exponential decay is counted in half-lives, and logarithms are how you get the number of them.","game":{"type":"BALLPARK","title":"How many half-lives have passed","setup":"Diagnostics Bay","play":"Use the supplied values and give a sensible rounded result with units.","question":"Estimate the elapsed time since the first count.","relationship":"Elapsed time = half-life × log2(first rate ÷ present rate).","answer":"8,000 to 500 is a factor of 16, which is four half-lives, so about 48 hours.","why":"Every half-life halves the count rate, so the elapsed time is the number of halvings times the half-life. Eight thousand to five hundred is a factor of sixteen, and sixteen is two to the fourth: four half-lives, or 48 hours. Written as a logarithm it is log base two of the ratio, which is what a semi-log plot shows as a straight line. The useful habit is to work in ratios rather than differences — the difference of 7,500 counts means nothing on its own.","estimate":{"relationship":"Elapsed time = half-life x log2(initial rate / final rate).","prompt":"8,000 counts a minute then, 500 now, with a 12-hour half-life.","question":"Estimate the elapsed time since the first count.","labels":["8,000 cpm (the first count)","500 cpm (today)","12 h (half-life)","16 (the ratio, worked out)","4 (halvings, worked out)","2 (the base)"],"values":[8000,500,12,16,4,2],"slots":3,"template":"log2({0} ÷ {1}) × {2}","formula":"Math.log2(a/b)*c","correct":[0,1,2],"target":48,"tolerance":6,"units":"hours","solution":"8,000 ÷ 500 = 16; log2(16) = 4 half-lives; × 12 h = 48 hours.","explanation":"Ratios, not differences: the count rate falls by a constant factor per half-life, not a constant number."},"rebuttals":[]},"assumes":["a half-life is the time for half of a sample to decay"]},{"day":6,"title":"Invest in multipoint initiation evidence","progress":"Choose between a single impressive shot and a program that measures channel-to-channel timing, lot variation, and shared failure modes.","takeaway":"Precision must be demonstrated statistically and diagnostically.","game":{"type":"Science Tank","title":"Invest in multipoint initiation evidence","setup":"The implosion group has 100 credits for initiation research.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 90 to B, 5 to A as a reference, 5 in reserve.","why":"The system needed reproducible simultaneity across manufactured components, not one exceptional assembly.","proposals":[{"label":"A","text":"Build one hand-selected set and optimize it until it gives a good result."},{"label":"B","text":"Test multiple sets with independent timing diagnostics, controlled cable configurations, and lot traceability."},{"label":"C","text":"Add more initiation points without improving measurement or common-mode analysis."}],"research":"","recommended":{"B":90,"A":5}},"story":"Multipoint initiation requires many detonators, cables, and firing channels to act together, but testing every possible failure is impossible. The team must invest in evidence that separates detonator variation from cable delay, firing-unit error, and measurement error. That knowledge determines whether the implosion program is improving the physical system or merely improving one instrument."},{"day":7,"title":"Hydrodynamic scaling with inert mock materials","progress":"Use scaled non-nuclear experiments to study wave propagation, convergence, and deformation before risking scarce plutonium.","takeaway":"Similarity is an argument supported by evidence, not a visual resemblance.","game":{"type":"Sequence","title":"Hydrodynamic scaling with inert mock materials","setup":"Order the logic of a useful scaled hydrodynamic experiment.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Identify the dimensionless or relative quantities the model must preserve. -> Choose inert materials and geometry that reproduce the relevant wave interactions as closely as practical. -> Instrument the shot with multiple independent diagnostics. -> Compare the measured wave history with the model and revise the scaling assumptions.)","why":"A scaled experiment is informative only when the preserved and distorted physics are explicit.","cards":["Identify the dimensionless or relative quantities the model must preserve.","Choose inert materials and geometry that reproduce the relevant wave interactions as closely as practical.","Instrument the shot with multiple independent diagnostics.","Revise the scaling assumptions against the wave history the diagnostics recorded."],"order":[0,1,2,3]},"story":"Hydrodynamic tests use inert materials to reproduce the motion of solids and explosives without a nuclear chain reaction. Scaling laws compare dimensions, times, densities, and wave speeds to decide what a smaller or safer test can teach about the full assembly. Los Alamos relies on these repeated mock shots to develop implosion before risking plutonium or a nuclear test."},{"day":8,"title":"Shock impedance at material boundaries","progress":"Understand why a pressure wave changes when it crosses interfaces among explosives, metal shells, and other layers.","takeaway":"In an implosion system, every interface is part of the physics.","game":{"type":"Protocol","columns":["What the record shows","What causes it"],"title":"Shock impedance at material boundaries","setup":"Match each observation to the best qualitative interpretation.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"A wave partially reflects from a boundary. -> An impedance mismatch. Density and shock response differ across the interface, so part of the wave has nowhere to go but back.; Transmitted pressure changes after entering a different material. -> A different constitutive response. The second material accepts a different pressure at the same particle velocity, so speed and amplitude both shift.; A small void creates a local disturbance and jet-like flow. -> A defect that focuses flow. Material collapsing into the empty space arrives ahead of the surrounding front and drives a local jet.; Two nominally identical interfaces produce different records. -> Unexplained variation. Before calling this physics, rule out machining tolerance and diagnostic differences between the two records.","why":"Interfaces transmit, reflect, and reshape waves according to the properties and state of both materials.","scenarios":["A wave partially reflects from a boundary.","Transmitted pressure changes after entering a different material.","A small void creates a local disturbance and jet-like flow.","Two nominally identical interfaces produce different records."],"choices":["An impedance mismatch. Density and shock response differ across the interface, so part of the wave has nowhere to go but back.","A different constitutive response. The second material accepts a different pressure at the same particle velocity, so speed and amplitude both shift.","A defect that focuses flow. Material collapsing into the empty space arrives ahead of the surrounding front and drives a local jet.","Unexplained variation. Before calling this physics, rule out machining tolerance and diagnostic differences between the two records."],"mapping":[0,1,2,3]},"story":"When a shock wave reaches a boundary between materials, part of the wave can reflect and part can transmit with a changed speed and pressure. The outcome depends on shock impedance, which combines material density and response. Fat Man contains many interfaces, so a void, wrong material, or poor contact can create a local disturbance that grows into asymmetric compression."},{"day":9,"title":"Density, geometry, and neutron multiplication","progress":"Connect compression to neutron behavior without using actual core masses or design parameters.","takeaway":"Hydrodynamics and neutron physics are coupled during the assembly.","game":{"type":"Sequence","title":"Density, geometry, and neutron multiplication","setup":"Order the qualitative chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Compression places the same fissile mass into a smaller volume. -> Average density rises and characteristic leakage paths shorten relative to the amount of material. -> A larger fraction of neutrons can induce additional fissions before escaping. -> The effective multiplication condition can move from subcritical toward supercritical.)","why":"Implosion changes both material density and the geometry that governs neutron leakage.","cards":["Compression places the same fissile mass into a smaller volume.","Average density rises and characteristic leakage paths shorten relative to the amount of material.","A larger fraction of neutrons can induce additional fissions before escaping.","The effective multiplication condition can move from subcritical toward supercritical."],"order":[0,1,2,3]},"story":"Neutron multiplication depends on density, geometry, and leakage as well as the amount of fissile material. Implosion is valuable because compression puts nuclei closer together and makes it harder for neutrons to escape before causing another fission. The integration group must connect hydrodynamic measurements of compression to nuclear predictions of how rapidly the chain reaction will grow."},{"day":10,"title":"Reflector and tamper functions","progress":"Separate the conceptual neutron and mechanical roles of surrounding dense layers in the implosion design.","takeaway":"Subsystem labels should not hide coupled functions.","game":{"type":"Protocol","columns":["What the layer has to do","How it does it"],"title":"Reflector and tamper functions","setup":"Match each statement to the relevant role.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"Some escaping neutrons are scattered back toward the fissile region. -> Neutron-reflector role; Inward motion of surrounding mass helps delay rapid expansion. -> Tamper or inertial role; The layer must transmit the imploding pressure wave without intolerable asymmetry. -> Hydrodynamic-interface requirement; Material choice also changes interfaces, inertia, and diagnostic interpretation. -> Coupled systems tradeoff","why":"One physical layer can affect neutron transport, hydrodynamics, and mechanical timing simultaneously.","scenarios":["Some escaping neutrons are scattered back toward the fissile region.","Inward motion of surrounding mass helps delay rapid expansion.","The layer must transmit the imploding pressure wave without intolerable asymmetry.","Material choice also changes interfaces, inertia, and diagnostic interpretation."],"choices":["Use the layer as a neutron reflector, scattering some escaping neutrons back toward the fissile region.","Use the layer as a tamper, adding inertia that delays rapid expansion while the chain reaction grows.","Require the layer and its interfaces to transmit the imploding pressure wave without introducing unacceptable asymmetry.","Treat material selection as a coupled tradeoff because neutron reflection, inertia, shock behavior, and diagnostics all change together."],"mapping":[0,1,2,3]},"story":"A surrounding layer can serve several roles at once: scatter some escaping neutrons back inward, add inertia that delays expansion, and transmit the imploding pressure wave. These neutron-reflector and tamper functions cannot be chosen independently because changing the material also changes shock behavior and interfaces. Fat Man design therefore requires a coupled nuclear and hydrodynamic tradeoff."},{"day":11,"title":"The modulated neutron initiator as a timing problem","progress":"Place the initiator in the historical Fat Man evidence chain as a controlled neutron source intended to act near the desired stage of compression.","takeaway":"In a fast transient system, source timing can be as important as source strength.","game":{"type":"Sequence","title":"The modulated neutron initiator as a timing problem","setup":"Order the conceptual logic; no construction details are given.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Maintain the pre-assembly neutron environment within the assumptions used by theory. -> Compress the plutonium assembly toward the intended high-density state. -> Produce a controlled burst of initiating neutrons near the selected time. -> Compare the resulting chain-reaction timing with predictions and diagnostic evidence.)","why":"The initiator addressed when a dependable starting population of neutrons would appear, while pre-initiation remained a separate risk.","cards":["Maintain the pre-assembly neutron environment within the assumptions used by theory.","Compress the plutonium assembly toward the intended high-density state.","Produce a controlled burst of initiating neutrons near the selected time.","Compare chain-reaction timing against prediction and diagnostic evidence."],"order":[0,1,2,3]},"story":"A neutron initiator is intended to provide neutrons at a controlled point late in the implosion rather than rely entirely on random background neutrons. The important idea is timing: too early can encourage pre-initiation, while too late will fail to influence the first chain-reaction generations. Los Alamos treats the initiator as one element in the larger synchronization problem."},{"day":12,"title":"Pre-initiation probability as a time-window problem","progress":"Use a generic Poisson estimate to show why shortening an assembly interval reduces exposure to random neutron events.","takeaway":"The plutonium problem was fundamentally a race between random neutrons and assembly speed.","game":{"type":"Ballpark","title":"Pre-initiation probability as a time-window problem","setup":"Invented classroom rates are used and do not represent plutonium or Fat Man.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"lambda = 200 x 10^-5 = 0.002, so P is about 0.2 percent.","why":"For a fixed random-event rate, a shorter vulnerable time lowers the chance of an event during assembly.","givens":["Random-event rate r = 200 per second","Vulnerable window t = 10 microseconds = 1 x 10^-5 s","Expected events lambda = r t"],"task":"Estimate the probability of at least one event using P approximately lambda when lambda is small.","relationship":"Probability ≈ the event rate × the length of the vulnerable window. Multiply by 100 for a percentage."},"story":"Pre-initiation risk depends on both the neutron background and the length of time the material remains vulnerable during assembly. A faster implosion shortens that time window, reducing the chance that a random neutron begins the reaction too soon. This probability argument explains why measuring plutonium’s spontaneous-neutron rate changes the entire Fat Man program."},{"day":13,"title":"RaLa: seeing an implosion with gamma rays","progress":"Follow the historical radiolanthanum diagnostic concept used to infer changing density and symmetry in non-nuclear implosion experiments.","takeaway":"A decisive diagnostic converts an invisible internal process into multiple measurable traces.","game":{"type":"Sequence","title":"RaLa: seeing an implosion with gamma rays","setup":"Order a safe, conceptual RaLa evidence chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Place a controlled gamma-ray source within an inert or surrogate implosion experiment. -> Position external detectors along multiple viewing directions. -> Record how transmitted gamma intensity changes as the assembly compresses. -> Infer relative density history and compare symmetry among directions and against calculations.)","why":"Changing density changes gamma-ray attenuation, allowing the otherwise hidden implosion to be probed in time.","cards":["Place a controlled gamma-ray source within an inert or surrogate implosion experiment.","Position external detectors along multiple viewing directions.","Record how transmitted gamma intensity changes as the assembly compresses.","Infer relative density history and compare symmetry among directions and against calculations."],"order":[0,1,2,3]},"story":"The RaLa experiments place a strong gamma-ray source inside an imploding mock assembly and measure how much radiation passed through as the material compresses. Greater density absorbs more gamma rays, so changing detector signals reveal the motion indirectly. This gives Los Alamos a way to see inside an opaque implosion and compare different lens designs without a nuclear core."},{"day":14,"title":"Betatron and high-speed radiography","progress":"Understand how penetrating x-rays could provide snapshots of rapidly changing internal structure during implosion development.","takeaway":"A picture becomes evidence only when its formation process is understood.","game":{"type":"Protocol","columns":["What is wrong with the image","How you fix it"],"title":"Betatron and high-speed radiography","setup":"Match each radiography problem to its remedy.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"The image is blurred because the exposure window is too long. -> Shorter or better-timed pulse; Dense regions exceed the useful detector range. -> Alternate sensitivity or exposure; The x-ray time cannot be related to initiation time. -> Shared timing fiducial; One viewing angle cannot distinguish two possible asymmetries. -> Additional view or complementary diagnostic","why":"Radiography depends on temporal resolution, dynamic range, timing registration, and geometry.","scenarios":["The image is blurred because the exposure window is too long.","Dense regions exceed the useful detector range.","The x-ray time cannot be related to initiation time.","One viewing angle cannot distinguish two possible asymmetries."],"choices":["Use a shorter or more precisely timed x-ray pulse so motion during the exposure does not blur the image.","Add an alternate exposure or lower-sensitivity detector so dense regions remain within the useful range.","Record a shared timing fiducial that connects the x-ray exposure to initiation time.","Add another viewing direction or a complementary diagnostic so two different three-dimensional shapes do not look identical."],"mapping":[0,1,2,3]},"story":"A betatron produces energetic x-rays that can photograph dense material during a rapid event. High-speed radiography requires a short exposure, precise synchronization, enough penetration, and viewing angles that separate possible shapes. These images help determine whether an implosion stays symmetric rather than relying only on external flashes or fragments."},{"day":15,"title":"Hydrodynamic shots with surrogate cores","progress":"Use non-fissile materials to test convergence, interfaces, and diagnostics while preserving scarce nuclear material.","takeaway":"A safe analog is useful only when its limits are explicit.","game":{"type":"Sequence","title":"Hydrodynamic shots with surrogate cores","setup":"Order the test-development loop.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Define which hydrodynamic behavior the surrogate must reproduce and which it cannot. -> Assemble the authorized mock configuration with full traceability. -> Conduct the instrumented shot and preserve timing, radiographic, and physical records. -> Compare observations with models, inspect recovered evidence when possible, and update the next test.)","why":"Surrogates reduce nuclear risk but introduce model-form uncertainty that must be tracked.","cards":["Define which hydrodynamic behavior the surrogate must reproduce and which it cannot.","Assemble the authorized mock configuration with full traceability.","Conduct the instrumented shot and preserve timing, radiographic, and physical records.","Compare observations with models, inspect recovered evidence where possible, and change the design of the following shot."],"order":[0,1,2,3]},"story":"Hydrodynamic shots replace the fissile core with surrogate materials chosen to mimic important mass and shock properties. Multiple diagnostics then measure wave arrival, density, and shape. The purpose is to test the mechanical implosion repeatedly so that Trinity’s one nuclear test will not be the first time the full geometry had been examined."},{"day":16,"title":"Control jets and hydrodynamic instabilities","progress":"Prioritize work on defects, material interfaces, and perturbation growth that can spoil convergence.","takeaway":"The correct response to a small anomalous feature is a discriminating experiment, not more energy or less resolution.","game":{"type":"Science Tank","title":"Control jets and hydrodynamic instabilities","setup":"The group has 100 credits after radiography reveals a narrow high-velocity feature near an interface.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 90 to B, 10 in reserve; A and C receive none.","why":"Local defects and interface instabilities can grow into system-level asymmetry.","proposals":[{"label":"A","text":"Increase total explosive energy without locating the source of the feature."},{"label":"B","text":"Run controlled defect and interface studies with improved radiography and model comparison."},{"label":"C","text":"Average the image until the narrow feature disappears."}],"research":"","recommended":{"B":90,"C":0}},"story":"A narrow jet of material can form when shocks interact with a void, gap, or surface imperfection, while hydrodynamic instabilities can amplify small ripples during acceleration. Such effects break spherical symmetry and mix materials. Fat Man development therefore requires both smooth manufacturing and experiments that can reveal how small defects grew under implosion."},{"day":17,"title":"Synchronizing many channels","progress":"Use a simple uncertainty calculation to combine independent timing errors from trigger, cable, and diagnostic registration.","takeaway":"A timing budget must include the full measurement chain.","game":{"type":"Ballpark","title":"Synchronizing many channels","setup":"Three independent timing contributions are a 2 ns shared trigger, 3 ns of cable delay, and 4 ns of diagnostic registration.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"sigma_total = sqrt(29), about 5.4 ns.","why":"The physical system contributes some delay, cable lengths contribute more, a trigger threshold shifts the moment a pulse is registered, and the recording instrument adds its own. Los Alamos handles this by building a timing budget: every contribution named, measured and combined. Independent contributions add in quadrature — squared, summed, square-rooted — so the largest term dominates and several smaller ones still raise the total. Two, three and four nanoseconds do not make nine; they make about five and a half.","givens":["Independent uncertainties combine in quadrature","sigma_total = sqrt(2^2 + 3^2 + 4^2) ns","Do not add signs, because these are uncertainty scales"],"task":"Estimate sigma_total.","relationship":"Independent timing errors add in quadrature: the root of the sum of the squares. They do not add straight."},"story":"Dozens of detonators and diagnostic channels have to share one time reference, and the delays come from everywhere. A budget that omits one term is how a system passes every check and fails as a whole.","assumes":["independent errors do not simply add"]},{"day":18,"title":"Build the implosion uncertainty budget","progress":"Separate uncertainties in materials, geometry, timing, diagnostics, and theory so the team knows which one limits confidence.","takeaway":"Improvement starts by naming the dominant source of uncertainty.","game":{"type":"Diagnosis","pack":"x18","title":"Two entries in one budget","setup":"You are assigning an implosion trial's anomalies to the right uncertainty terms.","play":"Read the whole reading panel, then select the two causes that together account for every reading. No single cause does.","answer":"Explosive lot-to-lot wave-speed variation + Attenuation-model error in the density inversion","why":"A budget lists the separate contributions: material properties, geometry, timing, diagnostics, models. For each one it estimates how much it moves the final claim. Its value is not the total but the ranking. Improvement starts with the dominant source, and effort spent anywhere else changes nothing. The honesty of it matters here too. When two anomalies sit in different subsystems, the budget has two entries. Force one cause onto both and you misattribute one of them — and that is the entry somebody then goes and works on."},"story":"An implosion trial has produced anomalies and each one has to be assigned to the term it belongs to. This programme has very little effort left to spend in the wrong place.","assumes":["two problems can have two different causes"]},{"day":19,"title":"Model-test correlation","progress":"Create a disciplined loop between hydrodynamic calculations, diagnostic predictions, and observed implosion traces.","takeaway":"Post hoc agreement is weaker than a successful pre-test prediction.","game":{"type":"Sequence","title":"Model-test correlation","setup":"Order the correlation workflow.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Generate pre-test predictions for specific observables, including uncertainty bands. -> Conduct the controlled experiment without retuning the prediction afterward. -> Compare arrival times, transmission histories, radiographs, and symmetry metrics. -> Update model parameters or model form, then test the revised model on a new experiment.)","why":"A model earns predictive authority by confronting data it did not already absorb.","cards":["Generate pre-test predictions for specific observables, including uncertainty bands.","Conduct the controlled experiment without retuning the prediction afterward.","Compare arrival times, transmission histories, radiographs, and symmetry metrics.","Update model parameters or model form, and test that version on a fresh experiment."],"order":[0,1,2,3]},"story":"Model-test correlation compares a calculated quantity with a measurement that represents the same physical feature. Agreement in one observable does not guarantee the entire model is correct, while disagreement may come from either physics or diagnostics. Los Alamos needs carefully matched comparisons to use hydrodynamic tests as evidence for the Fat Man design."},{"day":20,"title":"The Christy design simplification","progress":"Study the historical move toward a more robust solid-core implosion concept, often called the Christy gadget, without design dimensions.","takeaway":"Robust design often wins by reducing the number of ways reality can differ from the model.","game":{"type":"Protocol","columns":["What the program needs","What the simplification gives it"],"title":"The Christy design simplification","setup":"Match each program concern to the benefit sought by simplifying the internal configuration.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"A complicated internal geometry amplifies manufacturing and assembly uncertainty. -> Reduce internal geometric complexity; Theoretical calculations need a more tractable starting configuration. -> Improve calculational tractability; Hydrodynamic tests must map more directly onto the proposed final design. -> Strengthen model-test relevance; The program needs one configuration to freeze for Trinity and Fat Man. -> Enable an integration baseline","why":"The Christy concept was valuable partly because it converted a difficult physics problem into a more controllable systems problem.","scenarios":["A complicated internal geometry amplifies manufacturing and assembly uncertainty.","Theoretical calculations need a more tractable starting configuration.","Hydrodynamic tests must map more directly onto the proposed final design.","The program needs one configuration to freeze for Trinity and Fat Man."],"choices":["Reduce internal geometric complexity so fewer manufactured interfaces can introduce asymmetry.","Use a simpler starting geometry so theoretical calculations are more tractable and easier to check.","Make hydrodynamic tests resemble the proposed final configuration more directly, strengthening model-test comparison.","Establish one integration baseline that can be frozen for Trinity and the Fat Man weapon."],"mapping":[0,1,2,3]},"story":"The Christy design simplifies the internal core geometry into a more nearly solid configuration, reducing interfaces and making calculations and experiments easier to compare. Simplification does not make implosion easy, but it removes sources of uncertainty that are difficult to manufacture and model. This helps the program converge on one configuration for Trinity and Fat Man."},{"day":21,"title":"Freeze the implosion architecture","progress":"Decide when to stop exploring many lens and core concepts and concentrate resources on one testable configuration.","takeaway":"A design freeze is a decision about evidence, schedule, and residual risk.","game":{"type":"Science Tank","title":"Freeze the implosion architecture","setup":"The laboratory has 100 credits and only months before Trinity.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 75 to B mainline development, 15 to independent challenge, 10 to targeted backup studies.","why":"Late-stage programs need focus, but focus must be earned by evidence and protected against groupthink.","proposals":[{"label":"A","text":"Continue every implosion concept equally to preserve optionality."},{"label":"B","text":"Concentrate on the best-supported architecture while retaining a small independent challenge team and targeted backup studies."},{"label":"C","text":"Freeze immediately without resolving the largest diagnostic discrepancy."}],"research":"","recommended":{"B":75}},"story":"Freezing the implosion architecture means selecting one controlled arrangement of lenses, initiation, core geometry, surrounding layers, and interfaces for final qualification. Without a baseline, each successful test might describe a different system. The freeze allows Trinity evidence to support the actual Fat Man configuration rather than a moving target."},{"day":12,"title":"What a scaled shot can and cannot tell you","place":"Implosion Test Range","scene":"A half-scale shot is proposed: an eighth of the explosive, two weeks instead of six. The detonation velocity is 8.8 km/s at either size, the reaction zone is a fraction of a millimetre at either size, and the room is arguing about which numbers carry over.","story":"A half-scale shot is proposed: an eighth of the explosive, two weeks instead of six. The detonation velocity is 8.8 km/s at either size, the reaction zone is a fraction of a millimetre at either size, and the room is arguing about which numbers carry over.","takeaway":"A scaled experiment reproduces the dimensionless quantities, and only what depends on them transfers.","game":{"type":"CHOICE","title":"What a scaled shot can and cannot tell you","setup":"Implosion Test Range","play":"A half-scale shot is fired. Which of its results transfer to full scale?","question":"A half-scale shot is fired. Which of its results transfer to full scale?","choices":["Anything set by dimensionless ratios transfers; anything set by an absolute length or time does not.","All of it, since the geometry is similar and physics does not care about size.","None of it, because the materials behave differently at different sizes.","Only the timings, since time is the same at any scale."],"correctChoice":"Anything set by dimensionless ratios transfers; anything set by an absolute length or time does not.","answer":"Anything set by dimensionless ratios transfers; anything set by an absolute length or time does not.","why":"Scaling works through dimensionless groups: reproduce those and the phenomena they govern reproduce too. What does not scale is anything with a dimension of its own — a detonation velocity, a diffusion length, a reaction time — because halving the geometry does not halve them. So a half-scale shot can settle a symmetry question governed by ratios and cannot settle a timing margin measured in microseconds. The discipline is to state, before firing, which quantities the shot is entitled to decide.","rebuttals":["Similar geometry is necessary and not sufficient: the material timescales stay where they are.","Plenty transfers. Ratios and shapes are exactly what a scaled shot is for.","Timings are the classic thing that does NOT scale, because they are fixed by material properties."]},"assumes":["a dimensionless ratio has the same value at any scale"]},{"day":23,"title":"What Trinity had to answer","progress":"Define Trinity as the first full-system test of the plutonium implosion concept, not merely a demonstration of explosive power.","takeaway":"A full-system test should be written as a set of questions before it becomes an event.","game":{"type":"Protocol","columns":["What the test had to answer","Which kind of question that is"],"title":"What Trinity had to answer","setup":"Match each question to the evidence Trinity was intended to provide.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"Would the integrated implosion configuration produce the predicted nuclear chain reaction? -> The nuclear-performance question. Only a full-scale test can answer it, because no component test assembles the whole chain.; Did the firing and initiation system act in the required coordinated sequence? -> The ordnance-integration question. Answerable from timing records, and answerable even if the nuclear result disappoints.; How did observed effects compare with the broad range of pre-test yield predictions? -> The model-validation question. The pre-test predictions spanned a wide range, so this tests the theory rather than the device.; What radiological and physical hazards existed at and beyond the site? -> The safety-and-consequence question. It reaches past the site and past the day of the test, and it is the only one with obligations to people who were not present.","why":"A test without its questions written down in advance becomes an argument afterwards about what it proved. Four questions are in play and they are answerable by different evidence. Whether the integrated configuration produces the predicted chain reaction needs the full-scale event, because no component test assembles the whole chain. Whether the firing system acted in sequence comes from timing records, and survives a disappointing nuclear result. How the effects compare with pre-test predictions tests the theory rather than the device. And the hazards reach past the site and past the day.","scenarios":["Would the integrated implosion configuration produce the predicted nuclear chain reaction?","Did the firing and initiation system act in the required coordinated sequence?","How did observed effects compare with the broad range of pre-test yield predictions?","What radiological and physical hazards existed at and beyond the site?"],"choices":["The nuclear-performance question. Only a full-scale test can answer it, because no component test assembles the whole chain.","The ordnance-integration question. Answerable from timing records, and answerable even if the nuclear result disappoints.","The model-validation question. The pre-test predictions spanned a wide range, so this tests the theory rather than the device.","The safety-and-consequence question. It reaches past the site and past the day of the test, and it is the only one with obligations to people who were not present."],"mapping":[0,1,2,3],"rebuttals":["Whether the integrated configuration produces the predicted chain reaction is the nuclear-performance question, and only a full-scale test can answer it.","Whether the firing and initiation system acted in coordinated sequence comes from timing records — and it is answerable even if the nuclear result disappoints.","Comparing observed effects with the pre-test predictions is model validation. The predictions spanned a wide range, so this tests the theory rather than the device.","The radiological and physical hazards are the safety question, and it is the only one with obligations to people who were not present."]},"story":"Trinity is being written as a set of questions before it becomes an event, and this is that document. There is one device and one attempt.","assumes":["a test proves what it was designed to ask"]},{"day":24,"title":"Design the Trinity diagnostic portfolio","progress":"Allocate limited field resources among yield indicators, timing, radiation, photography, blast, and redundant measurements.","takeaway":"High-consequence experiments need independent observables and dynamic-range redundancy.","game":{"type":"Science Tank","title":"Design the Trinity diagnostic portfolio","setup":"The test director has 100 diagnostic credits.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: 85 to B, 10 to photography as one documented channel, 5 in reserve.","why":"No single instrument could be guaranteed to survive, remain in range, or be interpreted correctly.","proposals":[{"label":"A","text":"Put nearly all resources into one expected best yield measurement."},{"label":"B","text":"Use several physically independent yield and timing methods, plus radiation and fallout monitoring."},{"label":"C","text":"Maximize dramatic photography even if quantitative channels are underfunded."}],"research":"","recommended":{"B":85}},"story":"Because no instrument is guaranteed to survive or stay within range at Trinity, the diagnostic plan uses several independent methods for timing, radiation, blast, photography, and energy release. Redundancy across different physical principles makes the result interpretable even if one channel fails. The team must choose breadth of evidence over dependence on one expected ‘best’ measurement."},{"day":25,"title":"Trinity countdown and decision gates","progress":"Use weather, electrical status, diagnostic readiness, site safety, and configuration control as explicit hold points.","takeaway":"The authority to hold is as important as the authority to proceed.","game":{"type":"Sequence","title":"Trinity countdown and decision gates","setup":"Order the final decision chain.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Confirm the approved test configuration and all independent sign-offs. -> Review weather, evacuation, communications, diagnostics, and firing-system status at defined holds. -> Proceed only when the test director releases the final hold under the agreed authority structure. -> After the event, maintain access control, collect remote evidence, and initiate radiation surveys before recovery work.)","why":"A countdown is a governance structure that prevents schedule pressure from silently overriding unresolved conditions.","cards":["Confirm the approved test configuration and all independent sign-offs.","Review weather, evacuation, communications, diagnostics, and firing-system status at defined holds.","Proceed only when the test director releases the final hold under the agreed authority structure.","After the event, maintain access control, collect remote evidence, and initiate radiation surveys before recovery work."],"order":[0,1,2,3]},"story":"A countdown is a series of decision gates, not simply a clock reaching zero. Weather, evacuation, communications, diagnostic readiness, configuration, and firing-system status each had a hold point and responsible authority. Trinity can produce useful evidence only if schedule pressure does not override an unresolved condition."},{"day":26,"title":"Compare a prediction band with an observation","progress":"Practice interpreting a successful test result without pretending the pre-test model was exact.","takeaway":"Evidence should update a model claim by claim, not by declaring total victory.","game":{"type":"Ballpark","title":"Measure the offset between prediction and observation","setup":"A classroom model predicts an observable between 15 and 25 units; the measurement reads 21 units with an uncertainty of +/-2.","play":"Use the supplied classroom values, show the governing relationship, and give a sensible rounded result.","answer":"|21 - 20|/2 = 0.5 sigma. The observation is consistent with the prediction band, but a band that wide makes consistency weak evidence; it does not confirm every model assumption, and diagnostics that disagree with each other still need explaining.","why":"The gap between an observation and a prediction is measured in units of the measurement's own uncertainty. Take the difference and divide by that uncertainty. Half a sigma from the middle of the band is consistent. But consistency with a band this wide is weak evidence, because fifteen to twenty-five would have accommodated almost anything. Agreement supports the part of the model that produced the band, and no more. One agreeing diagnostic can sit beside others that disagree, and those still need explaining.","givens":["Prediction band: 15 to 25, midpoint 20","Measurement: 21 +/- 2"],"task":"Estimate the offset in units of the measurement uncertainty, then state the strongest justified conclusion.","relationship":"Distance in sigma = |observed − predicted| ÷ the measurement uncertainty."},"story":"A model predicts an observable between fifteen and twenty-five units. The measurement reads twenty-one, plus or minus two. The temptation after Trinity is to read one comparison as a verdict on everything.","assumes":["a wide prediction is easy to agree with"]},{"day":27,"title":"From the Gadget to Fat Man","progress":"Translate Trinity’s test configuration into a weaponized, air-deliverable Fat Man system under configuration control.","takeaway":"Demonstrating physics is not the same as fielding a system.","game":{"type":"Sequence","title":"From the Gadget to Fat Man","setup":"Order the transition.","play":"Arrange the four cards from earliest cause or prerequisite to latest result.","answer":"1 -> 2 -> 3 -> 4 (Reconcile Trinity results with pre-test predictions and identify configuration-specific lessons. -> Freeze the validated central implosion architecture and document any approved corrections. -> Complete aircraft, casing, fuzing, safety, assembly, and field-interface qualification. -> Transfer the controlled configuration, trained personnel, records, and spares to Project Alberta.)","why":"The Gadget and Fat Man shared the implosion principle, but combat deployment added a distinct engineering and logistics layer.","cards":["Reconcile Trinity results with pre-test predictions and identify configuration-specific lessons.","Freeze the validated central implosion architecture and document any approved corrections.","Complete aircraft, casing, fuzing, safety, assembly, and field-interface qualification.","Transfer the controlled configuration, trained personnel, records, and spares to Project Alberta."],"order":[0,1,2,3]},"story":"The Trinity Gadget demonstrates the central implosion principle, but Fat Man also needs a casing, aircraft interfaces, fuzing, safety systems, field assembly, and controlled records. Moving from test device to weapon means preserving the validated core design while qualifying everything required for delivery. The transition joins Los Alamos science with Project Alberta engineering and logistics."},{"day":28,"title":"Radiation, blast, and fallout consequences","progress":"Connect the physics of a nuclear detonation to prompt radiation, thermal effects, blast, residual radioactivity, and fallout.","takeaway":"Technical understanding must include what the device does to people and environments.","game":{"type":"Protocol","columns":["What the explosion produces","Which effect that is"],"title":"Radiation, blast, and fallout consequences","setup":"Match each consequence to its primary physical origin.","play":"Match each situation to the best action, control, document, or interpretation. Each option is used once.","answer":"A rapidly expanding high-temperature region drives a pressure wave. -> Blast. Mechanical overpressure moving at roughly the speed of sound, so it arrives after the light does.; Electromagnetic radiation carries intense heat outward. -> Thermal radiation. Arrives first at light speed, and is stopped by anything opaque between source and target.; Prompt neutrons and gamma rays deliver ionizing radiation near the event. -> Prompt ionizing radiation. Delivered within moments and only near the event, because air attenuates it strongly.; Fission products and activated material can be transported and deposited after the event. -> Residual radiation and fallout. The one channel that persists for days to years and can be carried far downwind.","why":"The weapon’s effects arise through several distinct channels with different spatial and temporal behavior.","scenarios":["A rapidly expanding high-temperature region drives a pressure wave.","Electromagnetic radiation carries intense heat outward.","Prompt neutrons and gamma rays deliver ionizing radiation near the event.","Fission products and activated material can be transported and deposited after the event."],"choices":["Blast. Mechanical overpressure moving at roughly the speed of sound, so it arrives after the light does.","Thermal radiation. Arrives first at light speed, and is stopped by anything opaque between source and target.","Prompt ionizing radiation. Delivered within moments and only near the event, because air attenuates it strongly.","Residual radiation and fallout. The one channel that persists for days to years and can be carried far downwind."],"mapping":[0,1,2,3]},"story":"A nuclear explosion releases energy through several channels: a pressure wave from rapidly expanding hot material, intense thermal radiation, prompt neutrons and gamma rays, and later radiation from fission products and activated material. Understanding these channels is essential not only for predicting weapon effects but also for recognizing the human and environmental consequences of Fat Man."},{"day":29,"title":"Scientific responsibility after Trinity","progress":"Examine the competing roles scientists adopted once the implosion weapon was technically demonstrated.","takeaway":"Expertise carries obligations when scientific work changes the scale of possible harm.","game":{"type":"CHOICE","title":"Scientific responsibility after Trinity","setup":"Allocate 100 discussion credits among three historically grounded priorities.","play":"The physics is settled and the decisions that follow are not physics. What does the laboratory owe?","answer":"A clear account of the expected humanitarian and radiological consequences, given to those deciding.","why":"The people making the decision cannot weigh what only this laboratory knows: the yield actually achieved, the radiological aftermath, and how uncertain both still are. That knowledge does not confer authority over the decision, and withholding it does not remove the laboratory from the consequences either. What the position has to distinguish is a technical judgement, which these scientists are uniquely able to give, from a political one, which they are not — and to state which is which. Szilard’s petition and the Franck Report were both attempts to put exactly that on the record. Expertise does not settle the question; withholding it removes the one thing expertise can contribute to it.","task":"The physics is settled and the decisions that follow are not physics. What does the laboratory owe?","question":"The physics is settled and the decisions that follow are not physics. What does the laboratory owe?","choices":["A clear account of the expected humanitarian and radiological consequences, given to those deciding.","Nothing beyond the technical work: the decision belongs to the elected government.","A refusal to continue technical work until the decision has been taken.","An argument for postwar international control, and silence on the immediate decision."],"correctChoice":"A clear account of the expected humanitarian and radiological consequences, given to those deciding.","rebuttals":["Leaving it to the government assumes the government already holds the technical picture. In the summer of 1945 it did not, and only the laboratory could supply it.","Refusing to continue was a position several people took, and it changes who does the work rather than what the decision-makers know about its effects.","Postwar control was argued for by many of the same people, in the same documents. It is a claim about the years after, and it leaves the question in front of them unanswered."]},"story":"Trinity yielded about 20 kilotons, the fireball was seen 200 miles away, and the fallout reached cattle 30 miles downwind. A petition signed by 155 scientists is circulating at another site, the laboratory has been asked for a technical opinion, and the questions that follow are not ones physics can settle.","assumes":["a technical question and a decision about its use are different questions"]},{"day":30,"title":"Final Fat Man implosion synthesis","progress":"Synthesize material physics, wave shaping, diagnostics, neutron behavior, timing, engineering, Trinity evidence, deployment, and consequences.","takeaway":"The complete lesson is how science, systems, institutions, and human consequences became inseparable.","game":{"type":"Science Tank","title":"Final Fat Man implosion synthesis","setup":"The final review has 100 curriculum credits to preserve the most important lessons.","play":"Allocate 100 research credits across the three proposals. You may hold credits in reserve, but explain the decision criterion.","answer":"Recommended: about 35 to A, 35 to B, and 30 to C; nearby balanced allocations are acceptable if the learner explicitly connects the three chains.","why":"Fat Man cannot be understood as only a physics device, only an engineering project, or only a historical event.","proposals":[{"label":"A","text":"The physics chain: plutonium measurement, rapid assembly, compression, neutron multiplication, and diagnostics."},{"label":"B","text":"The engineering chain: reproducible components, timing, configuration control, aircraft and field integration."},{"label":"C","text":"The historical and ethical chain: Trinity, Nagasaki, radiation effects, secrecy, dissent, and nuclear legacy."}],"research":"","recommended":{"A":35,"B":35,"C":30}},"story":"Fat Man brings together plutonium measurements, rapid compression, explosive lenses, synchronized initiation, neutron multiplication, diagnostics, aircraft engineering, and field operations. Its history cannot be understood as one clever device; it is a tightly linked scientific and institutional system. A final synthesis must connect how the bomb works with how it is tested, deployed, and used."}]};
const BALLPARK_CALCS={"X-8":{"relationship":"Elapsed time = half-life × log2(first rate ÷ present rate).","prompt":"A sample read 8,000 counts a minute when it was first measured and reads 500 today. The half-life on the chart is 12 hours.","question":"Estimate the elapsed time since the first count.","labels":["8,000 cpm (the first count)","500 cpm (today)","12 h (half-life)","16 (the ratio)","4 (halvings)","2 (the base)"],"values":[8000,500,12,16,4,2],"slots":3,"template":"log2({0} ÷ {1}) × {2}","formula":"Math.log2(a/b)*c","correct":[0,1,2],"target":48,"tolerance":6,"units":"hours","solution":"8,000 ÷ 500 = 16. log2(16) = 4 half-lives. Times 12 hours is 48 hours.","explanation":"Work in ratios, not differences. The rate falls by a constant factor each half-life."},"T-2":{"prompt":"A medium-heavy nucleus has about 200 nucleons, and nuclei of that size show a mass defect of roughly 0.008 atomic mass units per nucleon. One atomic mass unit is worth about 931 MeV. Estimate the total binding energy.","question":"Choose the mass defect per nucleon, the nucleon count, and the mass-to-energy conversion.","labels":["0.008 u/nucleon","200 nucleons","931 MeV/u","8 u/nucleon"],"values":[0.008,200,931,8],"correct":[0,1,2],"slots":3,"template":"E ≈ {0} × {1} × {2}","formula":"a*b*c","target":1489.6,"tolerance":80,"units":"MeV","solution":"0.008 u/nucleon × 200 nucleons × 931 MeV/u ≈ 1.5×10³ MeV.","explanation":"A single medium-heavy nucleus is bound by roughly 1,500 MeV. Set that against the few electron-volts holding a chemical bond: the nuclear scale is something like a hundred million times larger per particle, which is the whole reason a nuclear device and a chemical explosive are not the same category of thing. The binding energy per nucleon here, about 7.5 MeV, is the quantity the curve plots on the next day."},"T-4":{"prompt":"A tracer with a two-hour half-life is left on the bench for a six-hour shift, starting from 10,000 nuclei. Each half-life leaves half of what was there. Estimate how many nuclei remain.","question":"Choose the starting population, the decay factor, and the number of half-lives that elapse.","labels":["10,000 nuclei","1/2","3 half-lives","30 half-lives"],"values":[10000,0.5,3,30],"correct":[0,1,2],"slots":3,"template":"N ≈ {0} × ({1})^{2}","formula":"a*Math.pow(b,c)","target":1250,"tolerance":80,"units":"nuclei","solution":"10,000 × (1/2)³ ≈ 1,250 nuclei.","explanation":"Six hours at a two-hour half-life is three half-lives, not dozens: the number of half-lives is the elapsed time divided by the half-life. Each one halves the survivors, so three of them leave an eighth."},"T-6":{"prompt":"A solid holds about 10^22 nuclei per cubic centimetre, and the neutron cross section of interest is about one barn, or 10^-24 cm^2. Estimate the mean free path from lambda = 1/(n sigma).","question":"Choose the numerator, the number density, and the cross section.","labels":["1","10²² cm⁻³","10⁻²⁴ cm²","10⁶ cm²"],"values":[1,1e+22,1e-24,1000000],"correct":[0,1,2],"slots":3,"template":"λ ≈ {0} ÷ ({1} × {2})","formula":"a/(b*c)","target":100,"tolerance":15,"units":"cm","solution":"1 ÷ (10²² cm⁻³ × 10⁻²⁴ cm²) ≈ 10² cm.","explanation":"Multiply the powers of ten first: n sigma is about 0.01 cm⁻¹, so the mean free path is around a metre. A barn-scale cross section makes solid matter surprisingly transparent to neutrons, which is why assemblies must be large or reflected."},"T-9":{"prompt":"A neutron in a large water tank scatters about 100 times, travelling about 2 cm between collisions. Random-walk displacement is roughly the step length times the square root of the number of steps. Estimate its net displacement.","question":"Choose the step length and the number of steps.","labels":["2 cm","100 steps","200 cm","10 steps"],"values":[2,100,200,10],"correct":[0,1],"slots":2,"template":"displacement ≈ {0} × √{1}","formula":"a*Math.sqrt(b)","target":20,"tolerance":2,"units":"cm","solution":"2 cm × √100 ≈ 20 cm.","explanation":"The neutron covers 200 cm of path but ends up only about 20 cm from where it started. That gap between path length and net displacement is why a moderator can be far smaller than the total distance a neutron travels inside it."},"T-10":{"prompt":"A system starts with 1,000 neutrons and is slightly subcritical at k = 0.95. Estimate the population two generations later.","question":"Choose the initial population, the multiplication factor, and the generation count.","labels":["1,000 neutrons","0.95","2 generations","0.50"],"values":[1000,0.95,2,0.5],"correct":[0,1,2],"slots":3,"template":"N₂ ≈ {0} × ({1})^{2}","formula":"a*Math.pow(b,c)","target":902.5,"tolerance":35,"units":"neutrons","solution":"1,000 × 0.95² ≈ 900 neutrons.","explanation":"A system described as only slightly subcritical should have k just below one, so the population declines gently over a few generations."},"T-13":{"prompt":"One fission releases about 200 MeV, and 1 MeV is 1.6×10⁻¹³ joule. Estimate the energy of a single fission in joules.","question":"Choose the energy per fission and the MeV-to-joule conversion.","labels":["200 MeV","1.6×10⁻¹³ J/MeV","931 MeV","10⁶ J/MeV"],"values":[200,1.6e-13,931,1000000],"correct":[0,1],"slots":2,"template":"E ≈ {0} × {1}","formula":"a*b","target":3.2e-11,"tolerance":5e-12,"units":"J","solution":"200 MeV × 1.6×10⁻¹³ J/MeV ≈ 3.2×10⁻¹¹ J.","explanation":"A fission releases a few hundred MeV. One MeV is about 1.6×10⁻¹³ joule."},"T-17":{"prompt":"A sample emits spontaneous-fission neutrons at about 10⁴ per second, and a slow mechanical assembly takes about 10⁻³ s to complete. Estimate how many neutrons are expected during the assembly window.","question":"Choose the spontaneous-fission rate and the assembly time.","labels":["10⁴ neutrons/s","10⁻³ s slow assembly","10⁻⁶ s fast assembly","10² neutrons/s"],"values":[10000,0.001,0.000001,100],"correct":[0,1],"slots":2,"template":"expected neutrons ≈ {0} × {1}","formula":"a*b","target":10,"tolerance":1.5,"units":"neutrons","solution":"10⁴ s⁻¹ × 10⁻³ s ≈ 10 neutrons.","explanation":"Ten neutrons during assembly is not a risk of starting early, it is a certainty: the chain begins well before the pieces are together. Put the fast assembly time in instead and the same source gives 10⁻² neutrons — roughly a one-in-a-hundred chance. Nothing about the material changed; only the length of time it spent vulnerable did. That single factor of a thousand in assembly speed is the whole argument for abandoning the slow route."},"T-19":{"prompt":"Leakage is set by how much boundary a body has per unit of volume. For a sphere that ratio is 3/R. Estimate it for a sphere of radius 5 cm.","question":"Choose the sphere factor and the radius.","labels":["3 (sphere factor)","5 cm radius","10 cm radius","2 (doubling factor)"],"values":[3,5,10,2],"correct":[0,1],"slots":2,"template":"S/V ≈ {0} ÷ {1}","formula":"a/b","target":0.6,"tolerance":0.05,"units":"cm⁻¹","solution":"3 ÷ 5 cm ≈ 0.6 cm⁻¹.","explanation":"A 10 cm sphere gives 3 ÷ 10 = 0.3 cm⁻¹, half as much surface per unit of volume. Surface grows as L² while volume grows as L³, so doubling the size halves the boundary available for leakage — which is why a larger assembly reaches criticality on less material."},"T-20":{"prompt":"A predicted reaction rate carries an 8% cross-section uncertainty and a 6% flux uncertainty, and the two are independent. Estimate the combined uncertainty.","question":"Choose the two component uncertainties to combine in quadrature.","labels":["8%","6%","14%","2%"],"values":[8,6,14,2],"correct":[0,1],"slots":2,"template":"σ ≈ √({0}² + {1}²)","formula":"Math.sqrt(a*a+b*b)","target":10,"tolerance":0.6,"units":"%","solution":"√(8² + 6²) ≈ 10%.","explanation":"Quadrature gives 10%, not the 14% of a straight sum: independent errors partly cancel. Note also that the larger component dominates — halving the 6% would move the total to about 8.5%, while halving the 8% would move it to 7.2%."},"T-24":{"prompt":"A sample is compressed by an average pressure of 5×10⁹ Pa while its volume falls by 2×10⁻⁶ m³. Estimate the compression work.","question":"Choose the pressure and the volume change.","labels":["5×10⁹ Pa","2×10⁻⁶ m³","5×10⁶ Pa","2×10⁻⁴ m³"],"values":[5000000000,0.000002,5000000,0.0002],"correct":[0,1],"slots":2,"template":"work ≈ {0} × {1}","formula":"a*b","target":10000,"tolerance":1200,"units":"J","solution":"5×10⁹ Pa × 2×10⁻⁶ m³ ≈ 10⁴ J.","explanation":"Gigapascal pressure acting on a few cubic centimetres is kilojoule-scale work. That number sets the bar for whatever drives the compression: it has to deliver at least this much into the sample. It is also why chemical explosive, at a few megajoules per kilogram, is a credible driver at this scale — the energy is available, the difficulty is delivering it symmetrically."},"T-27":{"prompt":"A shock front crosses the assembly at about 8×10³ m/s. Two initiation channels fire 0.5 microseconds (5×10⁻⁷ s) apart. Estimate how far ahead the early side’s front runs by the time the late one starts, in millimetres.","question":"Choose the wave speed, the channel spread, and the metres-to-millimetres conversion.","labels":["8×10³ m/s wave speed","5×10⁻⁷ s channel spread","1,000 mm/m","5×10⁻⁵ s channel spread"],"values":[8000,5e-7,1000,0.00005],"correct":[0,1,2],"slots":3,"template":"lead distance ≈ {0} × {1} × {2}","formula":"a*b*c","target":4,"tolerance":0.5,"units":"mm","solution":"8×10³ m/s × 5×10⁻⁷ s × 1,000 mm/m ≈ 4 mm.","explanation":"Half a microsecond of disagreement puts one side of the front 4 mm ahead of the other — a visible dent in a convergence that was supposed to be spherical. The timing requirement is written in nanoseconds not because that is what the electronics can manage, but because that is how far the physics moves while the channels argue. Every timing contribution combined later gets judged against this millimetre-scale yardstick."},"P-3":{"prompt":"A scintillation event releases about 10,000 detected photoelectrons, and counting fluctuations scale as 1/√N. Estimate the fractional noise.","question":"Choose the numerator and the photoelectron count.","labels":["1","10,000 photoelectrons","100 photoelectrons","1,000,000 photoelectrons"],"values":[1,10000,100,1000000],"correct":[0,1],"slots":2,"template":"fractional noise ≈ {0} ÷ √{1}","formula":"a/Math.sqrt(b)","target":0.01,"tolerance":0.002,"units":"fraction","solution":"1/√10,000 ≈ 0.01, or 1%.","explanation":"Photoelectron statistics are approximately Poisson, so fractional noise decreases as one over the square root of the count."},"P-5":{"prompt":"A detector intercepts 1% of the particles leaving an isotropic source and records 50% of those that reach it. Estimate its absolute efficiency.","question":"Choose the geometric acceptance and the intrinsic efficiency.","labels":["1% geometric acceptance","50% intrinsic efficiency","5% geometric acceptance","100% intrinsic efficiency"],"values":[0.01,0.5,0.05,1],"correct":[0,1],"slots":2,"template":"absolute efficiency ≈ {0} × {1}","formula":"a*b","target":0.005,"tolerance":0.0006,"units":"fraction","solution":"0.01 × 0.50 ≈ 0.005, or 0.5%.","explanation":"Absolute efficiency is the product of how many particles reach the detector and how many entering particles are recorded."},"P-7":{"prompt":"A counting run records 400 net counts, and Poisson fluctuations are about √N. Estimate the fractional statistical uncertainty.","question":"Choose the numerator and the count total.","labels":["1","400 counts","40 counts","4,000 counts"],"values":[1,400,40,4000],"correct":[0,1],"slots":2,"template":"fractional uncertainty ≈ {0} ÷ √{1}","formula":"a/Math.sqrt(b)","target":0.05,"tolerance":0.006,"units":"fraction","solution":"1/√400 ≈ 0.05, or 5%.","explanation":"400 counts gives 5%. The scaling is what matters for planning: uncertainty falls as 1/√N, so halving it to 2.5% takes 1,600 counts — four times the run. Precision bought by counting longer gets expensive fast, which is why detector efficiency and background suppression are worth as much as extra hours."},"P-8":{"prompt":"A sample run records 1,000 counts and an equal-length background run records 100 counts. Estimate the standard deviation of the background-subtracted net counts.","question":"Choose the sample total and the background total.","labels":["1,000 sample counts","100 background counts","10,000 sample counts","10 background counts"],"values":[1000,100,10000,10],"correct":[0,1],"slots":2,"template":"σ_net ≈ √({0} + {1})","formula":"Math.sqrt(a+b)","target":33.166,"tolerance":0.8,"units":"counts","solution":"√(1,000 + 100) ≈ 33 counts.","explanation":"Subtracting the background removes 100 counts from the net but adds its variance: the uncertainty comes from 1,000 + 100, not 1,000 − 100. Net counts are 900 ± 33, so subtraction never improves precision even when it corrects the answer."},"P-9":{"prompt":"A detector with a 10-microsecond (10⁻⁵ s) dead time records 2,000 counts per second. To first order the live fraction is 1 − R tau. Estimate it as a percentage.","question":"Choose the leading factor, the count rate, and the dead time.","labels":["1","2,000 s⁻¹","10⁻⁵ s","10⁻³ s"],"values":[1,2000,0.00001,0.001],"correct":[0,1,2],"slots":3,"template":"live fraction ≈ ({0} − {1}×{2}) × 100","formula":"(a-b*c)*100","target":98,"tolerance":1,"units":"%","solution":"(1 − 2,000×10⁻⁵)×100 ≈ 98%.","explanation":"R tau is 0.02 here, so the linear correction is trustworthy and the detector is live 98% of the time. Ten times the rate would put R tau at 0.2, where the first-order form breaks down and the full nonparalyzable expression is needed — the formula carries its own validity limit."},"P-11":{"prompt":"A gamma-ray line at 1 MeV is recorded with a full width at half maximum of 0.05 MeV. Estimate the detector’s percent energy resolution.","question":"Choose the line width, the line energy, and the percent conversion.","labels":["0.05 MeV width","1 MeV line energy","100 percent/unit","0.5 MeV width"],"values":[0.05,1,100,0.5],"correct":[0,1,2],"slots":3,"template":"resolution ≈ ({0} ÷ {1}) × {2}","formula":"a/b*c","target":5,"tolerance":0.4,"units":"%","solution":"(0.05 MeV ÷ 1 MeV)×100 ≈ 5%.","explanation":"Energy resolution is the peak width divided by the peak energy, expressed as a percentage."},"P-13":{"prompt":"Two detectors count independently at 100 s⁻¹ and 200 s⁻¹ through a 1-microsecond (10⁻⁶ s) coincidence window. Estimate the accidental coincidence rate.","question":"Choose the two rates and the coincidence window.","labels":["100 s⁻¹","200 s⁻¹","10⁻⁶ s","10⁻³ s"],"values":[100,200,0.000001,0.001],"correct":[0,1,2],"slots":3,"template":"accidental rate ≈ {0} × {1} × {2}","formula":"a*b*c","target":0.02,"tolerance":0.004,"units":"s⁻¹","solution":"100×200×10⁻⁶ ≈ 0.02 accidental coincidences per second.","explanation":"For independent streams, accidental coincidence rate scales with both count rates and the width of the coincidence window."},"P-14":{"prompt":"A particle crosses a 3 m flight path in 100 ns (10⁻⁷ s). Estimate its speed.","question":"Choose the path length and the travel time.","labels":["3 m","10⁻⁷ s","30 m","10⁻⁵ s"],"values":[3,1e-7,30,0.00001],"correct":[0,1],"slots":2,"template":"speed ≈ {0} ÷ {1}","formula":"a/b","target":30000000,"tolerance":2500000,"units":"m/s","solution":"3 m ÷ 10⁻⁷ s ≈ 3×10⁷ m/s.","explanation":"A few meters traversed in about one hundred nanoseconds corresponds to a few times ten million meters per second."},"P-23":{"prompt":"Two readings each carry a 10% random error and a 10% shared calibration error. Averaging N readings divides the random part by √N but leaves the shared part untouched. Estimate the uncertainty on the average of the two.","question":"Choose the random error, the number of readings averaged, and the shared calibration error.","labels":["10% random error","2 readings averaged","10% shared calibration","0% shared calibration"],"values":[10,2,10,0],"correct":[0,1,2],"slots":3,"template":"σ ≈ √(({0} ÷ √{1})² + {2}²)","formula":"Math.sqrt(Math.pow(a/Math.sqrt(b),2)+c*c)","target":12.247,"tolerance":0.6,"units":"%","solution":"√((10 ÷ √2)² + 10²) ≈ 12%.","explanation":"Averaging pulls the random part from 10% down to about 7%, but the shared calibration error stays at 10% however many readings are averaged. The total barely moves — 14% for one reading, 12% for two — and it can never fall below the 10% systematic floor. More data cannot fix a miscalibrated instrument."},"P-25":{"prompt":"An object moving at 500 m/s is recorded with a 1-microsecond (10⁻⁶ s) exposure. Estimate the motion blur in millimetres.","question":"Choose the speed, the exposure time, and the metres-to-millimetres conversion.","labels":["500 m/s","10⁻⁶ s","1,000 mm/m","10⁻³ s"],"values":[500,0.000001,1000,0.001],"correct":[0,1,2],"slots":3,"template":"blur ≈ {0} × {1} × {2}","formula":"a*b*c","target":0.5,"tolerance":0.06,"units":"mm","solution":"500 m/s × 10⁻⁶ s × 1,000 mm/m ≈ 0.5 mm.","explanation":"0.5 mm of blur. Whether that is acceptable is not a property of the camera but a comparison: blur has to be small against the feature being resolved. A boundary moving across a 5 mm gap is measurable at this exposure; a 0.5 mm perturbation is not measurable at all, because it is smeared into its own width. Shortening the exposure is the only lever that does not also cost signal."},"CM-2":{"prompt":"A separation starts with 5,000 tracer counts per minute. The recovered fraction is counted afterwards and, once corrected for decay during the process, comes to 4,000 counts per minute. Estimate the chemical yield.","question":"Choose the recovered and initial count rates.","labels":["4,000 recovered counts","5,000 initial counts","400 recovered counts","50,000 initial counts"],"values":[4000,5000,400,50000],"correct":[0,1],"slots":2,"template":"yield ≈ ({0} ÷ {1}) × 100","formula":"a/b*100","target":80,"tolerance":3,"units":"%","solution":"4,000 ÷ 5,000 × 100 ≈ 80%.","explanation":"Four-fifths recovered means a fifth of the target is somewhere else — on glassware, in the discarded phase, or still in the residue — and that missing fifth has to be accounted for before the assay means anything. Note what the decay correction bought: without it the later count is lower simply because time passed, and the chemistry would be blamed for a loss it did not cause. A raw count rate is not a quantity of material."},"CM-6":{"prompt":"A solute has a distribution ratio of 4 between the organic and aqueous phases, and the two phase volumes are equal. Estimate the percentage extracted in one stage.","question":"Choose the distribution ratio and the phase-volume ratio.","labels":["4 distribution ratio","1 equal phase-volume ratio","40 distribution ratio","0.1 phase-volume ratio"],"values":[4,1,40,0.1],"correct":[0,1],"slots":2,"template":"fraction extracted ≈ {0} ÷ ({0}+{1}) × 100","formula":"a/(a+b)*100","target":80,"tolerance":3,"units":"%","solution":"4 ÷ (4+1) × 100 ≈ 80%.","explanation":"One stage at D = 4 leaves a fifth of the solute behind. A second identical stage would leave a fifth of that again, which is why extraction is run as a series of stages rather than pushed to completion in one."},"CM-15":{"prompt":"A metal sample has a mass of 250 g and a measured volume of 20 cm³. Estimate its density.","question":"Choose the mass and the volume.","labels":["250 g","20 cm³","25 g","200 cm³"],"values":[250,20,25,200],"correct":[0,1],"slots":2,"template":"density ≈ {0} ÷ {1}","formula":"a/b","target":12.5,"tolerance":0.7,"units":"g/cm³","solution":"250 g ÷ 20 cm³ ≈ 12.5 g/cm³.","explanation":"At 12.5 g/cm³ the sample sits between lead at 11.3 and uranium at 19, so density alone is enough to flag a substituted material, a porous casting, or a bad volume measurement before any chemistry is done."},"CM-16":{"prompt":"A 100 mm metal component with expansion coefficient 15×10⁻⁶ K⁻¹ is heated by 100 K. Estimate the length change in millimetres.","question":"Choose the coefficient, the original length, and the temperature change.","labels":["15×10⁻⁶ K⁻¹","100 mm","100 K","10 K"],"values":[0.000015,100,100,10],"correct":[0,1,2],"slots":3,"template":"ΔL ≈ {0} × {1} × {2}","formula":"a*b*c","target":0.15,"tolerance":0.02,"units":"mm","solution":"15×10⁻⁶ K⁻¹ × 100 mm × 100 K ≈ 0.15 mm.","explanation":"A tenth of a millimetre sounds negligible until it is compared with the fit it has to hold. Machining tolerances on a precision assembly run at this same scale, so a part measured cold can be out of tolerance warm."},"CM-22":{"prompt":"A process starts with 100.0 units of material, ships 97.5 units as product, and measures 1.5 units in waste. Estimate the unaccounted amount.","question":"Choose the starting, product, and waste amounts.","labels":["100 starting units","97.5 product units","1.5 waste units","15 waste units"],"values":[100,97.5,1.5,15],"correct":[0,1,2],"slots":3,"template":"unaccounted ≈ {0} − {1} − {2}","formula":"a-b-c","target":1,"tolerance":0.12,"units":"unit","solution":"100 − 97.5 − 1.5 = 1.0 unit.","explanation":"A high-yield process can still leave a small but important inventory discrepancy after product and measured waste are counted."},"CM-27":{"prompt":"A property must be at least 100 units. The measurement reads 102 units with an uncertainty of ±3 units. Estimate the conservative lower bound.","question":"Choose the measured value and the uncertainty.","labels":["102 measured units","3 uncertainty units","100 threshold units","30 uncertainty units"],"values":[102,3,100,30],"correct":[0,1],"slots":2,"template":"lower bound ≈ {0} − {1}","formula":"a-b","target":99,"tolerance":0.15,"units":"units","solution":"102 − 3 ≈ 99 units, which falls below a 100-unit threshold.","explanation":"The lower bound of 99 falls below the 100-unit threshold, so a measurement that reads above the limit still does not demonstrate compliance. The margin has to exceed the uncertainty before a pass is unambiguous."},"E-4":{"prompt":"An inert mockup carries a 100 kg module and a 300 kg module 1.5 m apart along its axis, 400 kg in total. Estimate how far the centre of mass sits from the light module.","question":"Choose the separation, the heavy module mass, and the total mass.","labels":["1.5 m separation","300 kg heavy module","400 kg total mass","100 kg light module"],"values":[1.5,300,400,100],"correct":[0,1,2],"slots":3,"template":"x_cm ≈ {0} × {1} ÷ {2}","formula":"a*b/c","target":1.125,"tolerance":0.06,"units":"m","solution":"1.5 m × 300 kg ÷ 400 kg ≈ 1.13 m from the light module.","explanation":"The balance point sits three-quarters of the way toward the heavy module. Balance follows mass, so changing one module’s mass moves the whole assembly’s centre of gravity and with it the aircraft-interface and release behaviour."},"E-6":{"prompt":"An inert test shape is released from 8,000 m, with g = 9.8 m/s². Ignoring drag, the fall time is t ≈ √(2h/g). Estimate it.","question":"Choose the factor in the free-fall equation, the altitude, and g.","labels":["2","8,000 m","9.8 m/s²","800 m"],"values":[2,8000,9.8,800],"correct":[0,1,2],"slots":3,"template":"t ≈ √(({0}×{1}) ÷ {2})","formula":"Math.sqrt(a*b/c)","target":40.4,"tolerance":2.5,"units":"s","solution":"√(2×8,000/9.8) ≈ 40 s.","explanation":"A fall from several kilometers takes tens of seconds in vacuum. Real trajectories require drag and full flight testing."},"E-9":{"prompt":"Two signal paths differ in length by 0.4 m, and signals travel at 2×10⁸ m/s in the cable. Estimate the timing difference in nanoseconds.","question":"Choose the path mismatch, the signal speed, and the seconds-to-nanoseconds conversion.","labels":["0.4 m path mismatch","2×10⁸ m/s signal speed","10⁹ ns/s","2×10⁶ m/s signal speed"],"values":[0.4,200000000,1000000000,2000000],"correct":[0,1,2],"slots":3,"template":"delay ≈ ({0} ÷ {1}) × {2}","formula":"a/b*c","target":2,"tolerance":0.25,"units":"ns","solution":"0.4 m ÷ 2×10⁸ m/s × 10⁹ ns/s ≈ 2 ns.","explanation":"0.4 m of extra cable is 2 ns of delay. That is the number that turns \"fire together\" into an inspectable requirement: nobody measures simultaneity directly on a rack, but anyone can measure cable. Signals move at about two-thirds the speed of light in cable, so roughly every 20 cm costs a nanosecond — a rule worth carrying to the bench."},"E-14":{"prompt":"A test rack must hold two signal paths matched to within 2 ns (2×10⁻⁹ s), and signals travel at 2×10⁸ m/s in the cable. Estimate the largest path mismatch that still meets the requirement, in centimetres.","question":"Choose the timing tolerance, the signal speed, and the metres-to-centimetres conversion.","labels":["2×10⁻⁹ s tolerance","2×10⁸ m/s signal speed","100 cm/m","1×10⁸ m/s signal speed"],"values":[2e-9,200000000,100,100000000],"correct":[0,1,2],"slots":3,"template":"max mismatch ≈ {0} × {1} × {2}","formula":"a*b*c","target":40,"tolerance":4,"units":"cm","solution":"2×10⁻⁹ s × 2×10⁸ m/s × 100 cm/m ≈ 40 cm.","explanation":"A 2 ns budget buys 40 cm of route mismatch — generous on a rack, but easy to spend once a cable detours around equipment. Converting the timing requirement into a length limit is what makes it inspectable: a technician can measure cable, not nanoseconds."},"E-17":{"prompt":"A fixture stacks three independently machined interfaces, each held to ±0.15 mm, and worst-case absolute limits add. Estimate the worst-case stack.","question":"Choose the per-interface tolerance and the number of interfaces.","labels":["0.15 mm/interface","3 interfaces","0.015 mm/interface","12 interfaces"],"values":[0.15,3,0.015,12],"correct":[0,1],"slots":2,"template":"worst-case stack ≈ {0} × {1}","formula":"a*b","target":0.45,"tolerance":0.035,"units":"mm","solution":"0.15 mm × 3 ≈ 0.45 mm.","explanation":"Worst-case tolerance stack-up adds aligned limits directly, unlike statistical root-sum-square combination."},"E-20":{"prompt":"A firing chain needs four subsystems in series, each with independent reliability 0.98. Estimate the reliability of the whole chain.","question":"Choose the per-subsystem reliability and the subsystem count.","labels":["0.98 per subsystem","4 required subsystems","0.80 per subsystem","40 required subsystems"],"values":[0.98,4,0.8,40],"correct":[0,1],"slots":2,"template":"series reliability ≈ ({0})^{1}","formula":"Math.pow(a,b)","target":0.922,"tolerance":0.02,"units":"fraction","solution":"0.98⁴ ≈ 0.92.","explanation":"Series-system reliability declines as more required components are added, even when each component is highly reliable."},"E-24":{"prompt":"The controlling chain of an integrated trial runs 9 weeks. A parallel chain in the same trial runs 7 weeks. Estimate how much the parallel chain can slip before it becomes the chain that sets the date.","question":"Choose the controlling chain duration and the parallel chain duration.","labels":["9 weeks controlling chain","7 weeks parallel chain","4 weeks single task","12 weeks both chains"],"values":[9,7,4,12],"correct":[0,1],"slots":2,"template":"float ≈ {0} − {1}","formula":"a-b","target":2,"tolerance":0.2,"units":"weeks","solution":"9 weeks − 7 weeks = 2 weeks of float.","explanation":"The parallel chain carries two weeks of slack: two weeks of trouble there costs the programme nothing, and a third week makes it the new critical path. This is why adding people to work off the critical path buys no schedule at all — the effort is spent on float that already existed. Manage the float, not just the length."},"X-3":{"prompt":"A sphere is compressed until its radius is 0.90 of the original, with mass unchanged, and density scales as 1/R³. Estimate the ratio of final to initial density.","question":"Choose the mass ratio, the radius ratio, and the spatial exponent.","labels":["1 mass ratio","0.90 radius ratio","3 spatial dimensions","0.50 radius ratio"],"values":[1,0.9,3,0.5],"correct":[0,1,2],"slots":3,"template":"density ratio ≈ {0} ÷ ({1})^{2}","formula":"a/Math.pow(b,c)","target":1.372,"tolerance":0.06,"units":"ratio","solution":"1 ÷ 0.90³ ≈ 1.37.","explanation":"Sphere volume scales with the cube of radius, so a modest radial reduction produces a larger fractional density increase."},"X-5":{"prompt":"Four normalized diagnostic channels read 100, 101, 99, and 100, so the mean is 100 and the spread runs from 99 to 101. Estimate the spread as a percentage of the mean.","question":"Choose the high reading, the low reading, and the mean.","labels":["101 high reading","99 low reading","100 mean reading","1,000 mean reading"],"values":[101,99,100,1000],"correct":[0,1,2],"slots":3,"template":"spread ≈ ({0}−{1}) ÷ {2} × 100","formula":"(a-b)/c*100","target":2,"tolerance":0.15,"units":"%","solution":"(101−99)/100 × 100 ≈ 2%.","explanation":"Two units of spread on a mean of 100 is 2%. Expressing it as a percentage rather than an absolute is what makes it a metric: channels with different gains, and shots at different absolute levels, can all be judged against one tolerance. An absolute spread of two units means nothing until you know whether the mean was 100 or 1,000 — which is exactly what the fourth tile is there to catch."},"X-12":{"prompt":"Random events arrive at 200 per second and the vulnerable window is 10 microseconds (10⁻⁵ s). When the expected number is small, the probability of at least one event is about the expected number. Estimate it as a percentage.","question":"Choose the event rate, the time window, and the percent conversion.","labels":["200 events/s","10⁻⁵ s","100 percent/unit","10⁻² s"],"values":[200,0.00001,100,0.01],"correct":[0,1,2],"slots":3,"template":"probability ≈ {0} × {1} × {2}","formula":"a*b*c","target":0.2,"tolerance":0.03,"units":"%","solution":"200 s⁻¹ × 10⁻⁵ s × 100 ≈ 0.2%.","explanation":"For a small expected count λ, the probability of at least one event is approximately λ. A short window can make even a substantial rate produce a small probability."},"X-17":{"prompt":"Three independent timing contributions — a shared trigger at 2 ns, cable delay at 3 ns, and diagnostic registration at 4 ns — must be combined. Estimate the total timing uncertainty.","question":"Choose the three component uncertainties to combine in quadrature.","labels":["2 ns trigger","3 ns cable","4 ns recorder","12 ns linear sum"],"values":[2,3,4,12],"correct":[0,1,2],"slots":3,"template":"σ_total ≈ √({0}²+{1}²+{2}²)","formula":"Math.sqrt(a*a+b*b+c*c)","target":5.385,"tolerance":0.3,"units":"ns","solution":"√(2² + 3² + 4²) = √29 ≈ 5.4 ns.","explanation":"Quadrature gives 5.4 ns, well under the 9 ns a straight sum predicts, because independent errors do not all peak together — and the 4 ns recorder term alone carries more than half the total variance, so it is the one worth attacking first. Then check the answer against what the front does with that time: at 8×10³ m/s, 5.4 ns is about 0.04 mm of lead. Comfortably inside a millimetre-scale symmetry limit, which a half-microsecond spread would not be."},"X-26":{"prompt":"A model predicts an observable between 15 and 25 units, so its midpoint is 20. The measurement reads 21 units with an uncertainty of ±2. Estimate the offset in units of the measurement uncertainty.","question":"Choose the observed value, the band midpoint, and the measurement uncertainty.","labels":["21 observed","20 band midpoint","2 measurement uncertainty","15 band lower edge"],"values":[21,20,2,15],"correct":[0,1,2],"slots":3,"template":"offset ≈ |{0} − {1}| ÷ {2}","formula":"Math.abs(a-b)/c","target":0.5,"tolerance":0.1,"units":"σ","solution":"|21 − 20| ÷ 2 ≈ 0.5σ.","explanation":"Half a sigma is no disagreement at all — at this precision the observation and the midpoint are indistinguishable. Be careful what that licenses: it says the measurement is consistent with the model, not that the model is confirmed. A band 10 units wide is easy to agree with, so consistency here is weak evidence, and diagnostics that disagree with each other still need explaining."}};
export { JARGON, CURRICULUM, BALLPARK_CALCS };
